  and is_latest = true and is_archived = false;

-- ── 26PMAE01 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Work a chosen problem in elementary number theory by hand — CRT, Euler's theorem, or order of an element mod n.","deliverable_notes":"The full hand computation for the named modulus + one line on the theorem used."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Encrypt and decrypt a short message with a classical cipher (affine/Hill) by hand, then break it via frequency analysis on a real sample.","deliverable_notes":"The hand encryption/decryption + your frequency-based break of a real ciphertext."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Compute in a finite field and test quadratic residues (Legendre/Jacobi symbol) for chosen values by hand.","deliverable_notes":"The residue computations + the symbol evaluations, on paper."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Implement RSA end-to-end on small primes YOU chose: key generation, encrypt, decrypt — show every modular step.","deliverable_notes":"Your RSA keys + a worked encrypt/decrypt of a real short message, by hand or annotated code."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Run a primality test (Miller–Rabin) and a factoring method (Pollard rho) on chosen numbers, showing the steps.","deliverable_notes":"The test/factoring trace on the named numbers, by hand or annotated code."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"RSA I Built and Broke","primary":"Implement RSA yourself (choose primes, generate keys, encrypt a real message to a classmate), then demonstrate WHY it is secure by attempting factoring on your small modulus and timing how it scales.","support":"~400 words reflect on where the hardness actually lives.","llc":"Live-demo an encryption/decryption; faculty give a new message and you process it, then answer why larger primes defeat factoring."},
      {"option_no":2,"title":"A Cipher I Broke by Hand","primary":"Take a real classical ciphertext (encrypt a passage yourself or use a peer's) and break it via frequency analysis, documenting every deduction.","support":"~400 words reflect on why classical ciphers fail and modern ones don't.","llc":"Present the break live; faculty hand you a fresh short ciphertext to start cracking."},
      {"option_no":3,"title":"Primality and Factoring, Traced","primary":"Implement Miller–Rabin and Pollard-rho and run them on numbers you chose, documenting witnesses and cycles, and compare their behaviour.","support":"~400 words reflect on probabilistic vs deterministic guarantees.","llc":"Demo both on a faculty-chosen number and explain the output live."},
      {"option_no":4,"title":"Elliptic Curves, Computed","primary":"Choose an elliptic curve over a small field, compute its point group by hand, and demonstrate the group law geometrically.","support":"~400 words reflect on why ECC gives security at smaller key sizes.","llc":"Present the point addition; faculty pick two points and you add them live."},
      {"option_no":5,"title":"A Number-Theory Theorem I Proved","primary":"Select one theorem (quadratic reciprocity, Fermat/Euler, CRT) and give your own proof with a worked example.","support":"~400 words reflect on the step that tested you.","llc":"Present the proof and defend each step."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAE01'
  and is_latest = true and is_archived = false;

-- ── 26PMAE02 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Map a REAL network you can observe (your hostel corridor connections, a bus route map, a friendship group) as a graph and compute its basic invariants (degree sequence, components).","deliverable_notes":"The hand-drawn real graph + its degree sequence and component count."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"For your real graph, find a spanning tree and test connectivity/cut-vertices by hand.","deliverable_notes":"The spanning tree drawn + the cut-vertices identified on your real graph."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Find a maximum matching / independent set in a chosen real bipartite situation (students-to-projects, tasks-to-slots) by hand.","deliverable_notes":"The matching + one line on whether it is maximum and why (augmenting path)."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Properly colour a real map or timetable-conflict graph you build, achieving the chromatic number and proving it can't be fewer.","deliverable_notes":"The coloured real graph + a lower-bound argument (a clique) for the chromatic number."},
      {"sno":5,"unit":"V","finks_dimension":"Foundational Knowledge","task":"Test a chosen graph for planarity by hand (find a planar embedding or a K5/K3,3 subdivision).","deliverable_notes":"The planar drawing OR the forbidden subdivision, for the named graph."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Real Network I Analysed","primary":"Map a REAL network around you (transport, social, utility, or a citation set you collected) as a graph, compute connectivity/centrality/matching relevant to a real question about it, and state one actionable finding.","support":"~400 words reflect on what the graph revealed that a list of connections did not.","llc":"Present the real network and finding; faculty add/remove an edge and ask how your conclusion changes."},
      {"option_no":2,"title":"The Colouring That Solved a Conflict","primary":"Model a REAL scheduling/allocation conflict (exam slots, room bookings, a sports fixture) as a graph colouring and produce an optimal conflict-free schedule, proving optimality.","support":"~400 words reflect on where the chromatic-number bound bit.","llc":"Present the schedule and defend why fewer colours are impossible."},
      {"option_no":3,"title":"Matching People to Things","primary":"Take a REAL bipartite assignment (students-projects, volunteers-tasks) you gathered with consent, find a maximum matching, and certify it via Hall's condition or a vertex cover.","support":"~400 words reflect on when a perfect matching is impossible and why.","llc":"Present the assignment; faculty change one preference and you re-match live."},
      {"option_no":4,"title":"Planarity, Decided","primary":"Take a real circuit/route/plan and decide its planarity by hand, giving either an embedding or a Kuratowski obstruction.","support":"~400 words reflect on why planarity matters for the real object.","llc":"Defend the verdict; faculty add an edge and ask if it stays planar."},
      {"option_no":5,"title":"A Graph Theorem I Proved","primary":"Choose one theorem (Euler's formula, Hall's, the handshake/degree-sum, a Turán-type bound) and give your own proof with a constructed example.","support":"~400 words reflect on the induction/counting step.","llc":"Present and answer why each step holds."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAE02'
  and is_latest = true and is_archived = false;

-- ── 26PMAE03 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Design a DFA for a chosen non-trivial language, trace it on real strings, and prove it accepts exactly that language.","deliverable_notes":"The DFA diagram + acceptance traces on named strings + a one-line correctness argument."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Convert a chosen regular expression to an NFA to a DFA (Thompson + subset construction) fully by hand.","deliverable_notes":"The three machines drawn by hand for the named regex."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Write a context-free grammar for a chosen language, derive a real string, and draw its parse tree.","deliverable_notes":"The CFG + a leftmost derivation + the parse tree for a named string."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Design a PDA for a chosen non-regular language and trace it accepting/rejecting real strings.","deliverable_notes":"The PDA + stack traces on named accept/reject strings."},
      {"sno":5,"unit":"V","finks_dimension":"Foundational Knowledge","task":"Design a Turing machine for a chosen decidable task and trace its tape on a real input; argue it halts.","deliverable_notes":"The TM transition table + a tape trace on a named input + a halting argument."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Language Recogniser I Built and Defended","primary":"Design an automaton (DFA/PDA/TM as fits) for a language of your choice, IMPLEMENT it in code, and demonstrate it live against strings the faculty supply — including tricky boundary cases.","support":"~400 words reflect on where the machine's memory model (none/stack/tape) was forced by the language.","llc":"Live-run your recogniser on faculty-chosen strings and explain each acceptance."},
      {"option_no":2,"title":"Pumping Lemma, Wielded","primary":"Prove a specific language is NOT regular (or not context-free) using the pumping lemma, constructing the adversary argument yourself.","support":"~400 words reflect on the game-like structure of the proof.","llc":"Present the proof; faculty propose a decomposition and you refute it live."},
      {"option_no":3,"title":"Regex to DFA, Owned","primary":"Take one regex from a real text-processing need you have, convert it through NFA to minimal DFA by hand, and verify against a coded matcher.","support":"~400 words reflect on why minimisation matters.","llc":"Reconstruct a step live under a modified regex."},
      {"option_no":4,"title":"A Grammar for Something Real","primary":"Write a CFG for a real mini-syntax (a date format, a simple arithmetic expression, a command language) and build a parser that accepts/rejects, demoing on real inputs.","support":"~400 words reflect on ambiguity and how you removed it.","llc":"Demo the parser; faculty give a malformed input and you show the rejection."},
      {"option_no":5,"title":"Decidability, Argued","primary":"Take one decision problem, classify it (decidable/undecidable) and defend the classification with a construction or a reduction you built.","support":"~400 words reflect on what undecidability actually forbids.","llc":"Present and answer an examiner's 'why can't we just...' live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAE03'
  and is_latest = true and is_archived = false;

-- ── 26PMAE04 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
