  and is_latest = true and is_archived = false;

-- ── 26PMAE05 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Take a specific matrix Lie group (SO(2), SU(2), a chosen subgroup of GL_n) and verify the group axioms + describe it as a manifold by hand.","deliverable_notes":"The verified axioms + a one-line description of the group as a surface/manifold, for the named group."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Compute the matrix exponential exp(tX) for a chosen X by hand and identify the one-parameter subgroup it traces.","deliverable_notes":"The computed exp(tX) + the named subgroup, on paper."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Compute the Lie bracket of chosen matrices and verify the Jacobi identity by hand for a small algebra.","deliverable_notes":"The bracket table + the Jacobi verification, on paper."},
      {"sno":4,"unit":"IV","finks_dimension":"Foundational Knowledge","task":"Construct a small representation of a chosen Lie algebra and verify it respects the bracket.","deliverable_notes":"The representation matrices + the bracket-preservation check, by hand."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Decompose a chosen representation into irreducibles (for su(2), by highest weight) by hand.","deliverable_notes":"The decomposition + the highest-weight/dimension bookkeeping, on paper."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Lie Group I Understood as Symmetry","primary":"Choose one matrix Lie group and connect it to a REAL symmetry (rotations of an object you hold, SU(2) and spin, a symmetry in a physical/graphics setting), computing its algebra and exponential map by hand.","support":"~400 words reflect on how the algebra 'linearises' the group near the identity.","llc":"Demonstrate a rotation/symmetry live and answer how exp connects algebra to group."},
      {"option_no":2,"title":"The Exponential Map, Computed","primary":"Compute exp for several algebra elements by hand and verify they land in the group, mapping out one-parameter subgroups.","support":"~400 words reflect on where exp fails to be onto/one-to-one.","llc":"Reconstruct a computation live under a changed generator."},
      {"option_no":3,"title":"A Representation I Decomposed","primary":"Build a representation of su(2) (or another small algebra) and decompose it into irreducibles by hand via highest weights.","support":"~400 words reflect on why representation theory organises the structure.","llc":"Present the decomposition; faculty pick a rep and ask for its irreducible content."},
      {"option_no":4,"title":"Bracket and Structure Constants","primary":"For a chosen algebra, compute all structure constants by hand and verify the Jacobi identity, then interpret one relation.","support":"~400 words reflect on what the constants encode.","llc":"Defend the computation under a faculty-changed basis."},
      {"option_no":5,"title":"A Theorem I Proved","primary":"Select one result (closed-subgroup theorem statement/use, exp properties, a bracket identity) and give your own proof/derivation with an example.","support":"~400 words reflect on the tested step.","llc":"Present and answer questions live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAE05'
  and is_latest = true and is_archived = false;

-- ── 26PMAE06 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Model a REAL small allocation/scheduling problem you face as an integer/LP and solve it by hand (or with a solver you drive), interpreting the solution.","deliverable_notes":"The real problem, its LP model, and the solved optimum with interpretation."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Take a chosen non-linear objective from a real cost/profit setting and find its optimum via classical calculus (KKT/Lagrange) by hand.","deliverable_notes":"The Lagrange/KKT working + the optimum for your real objective."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Run the simplex method by hand on a chosen small LP, showing each pivot and reading the optimal tableau.","deliverable_notes":"The full simplex tableau sequence for the named LP."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Apply revised/bounded-variable simplex or duality to your LP and interpret the dual/shadow prices in real terms.","deliverable_notes":"The dual solution + a real-terms reading of the shadow prices."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Perform sensitivity analysis on your real LP — how far can a cost/RHS move before the optimum changes?","deliverable_notes":"The sensitivity ranges + one line on the real decision they inform."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"An Optimisation That Changed a Real Decision","primary":"Take a REAL allocation you or someone you know faces (a budget split, a route, a menu/production mix, a study-time plan), model it as a mathematical program, solve it, and act on / recommend the result to the real person.","support":"~400 words reflect on where the model simplified reality and whether the recommendation held.","llc":"Present the real problem and solution; faculty change a constraint and you re-optimise and re-interpret live."},
      {"option_no":2,"title":"Duality, Made Concrete","primary":"Solve one LP and its dual by hand, and explain the shadow prices to the real stakeholder of the primal problem.","support":"~400 words reflect on what duality reveals about the problem's economics.","llc":"Present primal+dual; faculty tighten a resource and you predict the objective change from the dual."},
      {"option_no":3,"title":"Simplex, Pivot by Pivot","primary":"Run simplex fully by hand on a real-data LP, documenting every pivot and degeneracy, then verify with a solver.","support":"~400 words reflect on why the algorithm terminates.","llc":"Reconstruct a pivot live under a changed cost coefficient."},
      {"option_no":4,"title":"Sensitivity of a Real Plan","primary":"Do a full sensitivity analysis on a real LP and report the robust ranges to the decision-maker.","support":"~400 words reflect on which parameter the plan is most fragile to.","llc":"Present the ranges; faculty push a parameter past its range and you show the basis change."},
      {"option_no":5,"title":"Non-linear Optimum, Certified","primary":"Find and certify (KKT / second-order) the optimum of a real non-linear objective you set up.","support":"~400 words reflect on why the KKT conditions are necessary here.","llc":"Defend optimality live under a faculty perturbation."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
