  and is_latest = true and is_archived = false;

-- ── 26PMAE07 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Model a REAL vague concept (a 'tall person', a 'warm day', a 'good' score in your context) as a fuzzy set with a membership function you justify from real data/observation.","deliverable_notes":"The membership function + the real observations that justify its shape."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"For your fuzzy set, compute alpha-cuts and contrast with the crisp-set boundary on the same real data.","deliverable_notes":"The alpha-cuts table + one line on what fuzziness captured that crisp missed."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Apply fuzzy operations (union/intersection/complement, a chosen t-norm) to two real fuzzy sets and interpret the result.","deliverable_notes":"The operation results on your two real fuzzy sets + interpretation."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Do fuzzy arithmetic on chosen fuzzy numbers modelling real imprecise quantities (a budget '~5000', a time '~2 hrs').","deliverable_notes":"The fuzzy-arithmetic result + its real meaning."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Construct a fuzzy set from real data by a chosen method (statistics/expert elicitation you actually run).","deliverable_notes":"The constructed membership function + the elicitation/data behind it."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Fuzzy Model of a Real Judgement","primary":"Take a REAL vague judgement people make (comfort, ripeness, risk, quality) and build a fuzzy inference model from real observations/elicitation, then test its verdicts against real cases.","support":"~400 words reflect on where fuzzy logic matched human judgement better than a crisp threshold.","llc":"Present the model; faculty give a new case and you compute and defend its fuzzy verdict live."},
      {"option_no":2,"title":"Fuzzy vs Crisp, on Real Data","primary":"Take one real classification (pass/fail, hot/cold, spam/not) and show a case where a crisp boundary misclassifies but a fuzzy model doesn't.","support":"~400 words reflect on the cost of the crisp boundary in the real setting.","llc":"Present both on faculty-chosen borderline cases."},
      {"option_no":3,"title":"A Fuzzy Controller I Designed","primary":"Design a simple fuzzy rule base for a real control task (fan speed vs temperature, watering vs soil), implement the inference, and demo it.","support":"~400 words reflect on how the rules encode expert intuition.","llc":"Live-demo the controller; faculty change an input and you trace the output."},
      {"option_no":4,"title":"Membership from Real Elicitation","primary":"Construct a membership function by actually eliciting judgements from real people (with consent) and fitting a function, documenting the process.","support":"~400 words reflect on the subjectivity and how you handled disagreement.","llc":"Present the elicitation and answer how a different panel would shift it."},
      {"option_no":5,"title":"Fuzzy Arithmetic for a Real Estimate","primary":"Use fuzzy numbers to propagate real imprecise quantities through a real calculation (a budget, a schedule) and report the fuzzy result to the stakeholder.","support":"~400 words reflect on what the fuzzy spread told the decision-maker.","llc":"Present the propagation; faculty widen one input's fuzziness and you recompute."}
    ]
