update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Take a real claim you can state precisely and give a rigorous proof (direct/contradiction/induction) that you construct.","deliverable_notes":"Your written proof of the named claim, by hand, with the method labelled."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Count a real configuration (arrangements/selections in a real situation you set up) using permutations/combinations and verify by a second method.","deliverable_notes":"The count by two methods for your real situation + agreement check."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Solve a real recurrence (a growth/tiling/counting pattern you observe) via a generating function or characteristic equation.","deliverable_notes":"The recurrence, its solution, and a check against actual counts."},
