  and is_latest = true and is_archived = false;

-- ── 26PMAE15 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Take a REAL small dataset YOU collected/sourced, frame a genuine ML task on it (predict/classify), and split it into train/test yourself.","deliverable_notes":"Your real dataset + the framed task + the train/test split, with your name in the code."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Train a neural net / a chosen learner on your real data and inspect what it learned (weights, errors).","deliverable_notes":"The trained model + its train/test error + one observation about what it learned."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Apply a Bayesian / probabilistic method to your task and compare its behaviour to the non-Bayesian one.","deliverable_notes":"The comparison of the two methods on your real data + one line on the difference."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Formulate a real problem as an AI search (state space, goal) and solve it with a chosen algorithm you code.","deliverable_notes":"The state-space formulation + the running search on a real instance."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Add planning under uncertainty (a small MDP / a rule with probabilities) to a real decision and reason about the policy.","deliverable_notes":"The MDP/policy + one line on the decision it recommends for your real case."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Model I Trained, Tested, and Distrust Correctly","primary":"Take a REAL dataset you sourced (with consent where personal), train an ML model to do a genuinely useful task, evaluate it honestly on held-out data, and then STRESS it — find the inputs where it fails and state clearly where it must not be deployed.","support":"~400 words reflect on the bias, leakage, or overfitting you found and what a naive user would miss.","llc":"Live-predict on faculty-supplied inputs, including an adversarial one, and explain each output and failure honestly."},
      {"option_no":2,"title":"What the Network Actually Learned","primary":"Train a model on real data and investigate what it learned (feature importance, a probed weight, a decision boundary), distinguishing genuine signal from artefact.","support":"~400 words reflect on a spurious correlation you had to rule out.","llc":"Show the probe; faculty perturb a feature and you predict the effect live."},
      {"option_no":3,"title":"Search That Solved a Real Puzzle","primary":"Formulate a real problem (a route, a schedule, a game) as AI search, implement an algorithm, and demo it solving a real instance, comparing to a baseline.","support":"~400 words reflect on the heuristic's effect on the search.","llc":"Live-solve a faculty-chosen instance and explain the expansion."},
      {"option_no":4,"title":"A Decision Under Uncertainty","primary":"Model a real sequential decision as a small MDP, compute a policy, and defend it against a simpler rule on real-ish scenarios.","support":"~400 words reflect on how uncertainty changed the best action.","llc":"Present the policy; faculty change a probability and you show the policy shift."},
      {"option_no":5,"title":"Bayesian vs Not, on My Data","primary":"Solve one task both a Bayesian and a non-Bayesian way on your real data and report where the uncertainty estimates changed the decision.","support":"~400 words reflect on when the prior mattered.","llc":"Present both and defend which you'd ship."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAE15'
  and is_latest = true and is_archived = false;

-- ── 26PMAE16 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"By hand, take a single McCulloch–Pitts / perceptron neuron with weights you choose and compute its output for four specific inputs; show the decision boundary you get.","deliverable_notes":"Your hand computation for all four inputs + the boundary line drawn on paper + 1 line stating which logic function your neuron realises."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Run the perceptron learning rule by hand on a small linearly separable set you invent (4–6 points), for at least three update steps, showing each weight change.","deliverable_notes":"Your step-by-step weight-update table by hand + the final separating line + 1 line on why it converged."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Apply the Hebb rule (or pseudo-inverse rule) by hand to build a linear associator for two pattern pairs you choose; then test recall on one pattern.","deliverable_notes":"Your weight-matrix construction by hand + the recall computation + 1 line on whether recall was exact and why."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Do ONE full backpropagation pass by hand through a tiny 2-2-1 network with weights and one training example you choose — forward pass, error, and at least one weight's gradient update.","deliverable_notes":"Your complete hand-worked forward and backward pass for that example + the updated weight value + 1 line naming where the chain rule entered."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"For a simple quadratic performance surface you write down, compute one step of steepest descent AND one Newton step by hand from the same starting point; compare where each lands.","deliverable_notes":"Both hand computations + the two resulting points marked on a sketch of the surface + 1 line on why Newton moved differently."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Network I Trained by Hand","primary":"Choose a tiny network and a small training set you design, and carry out several full backpropagation iterations ENTIRELY by hand until the error visibly falls; you may then confirm with your own code, but the hand-work is the deliverable.","support":"~400 words on the one gradient step you found hardest to trust.","llc":"Reproduce one iteration at the board while an examiner changes a weight."},
      {"option_no":2,"title":"Convergence: Proof, Not Faith","primary":"Take the perceptron convergence theorem and produce your OWN written proof plus a worked linearly-separable example where you count the actual number of updates to convergence.","support":"~400 words on what separability really guarantees.","llc":"Defend each step; faculty may make the data non-separable and ask what breaks."},
      {"option_no":3,"title":"Steepest Descent vs Newton, Measured","primary":"Pick a specific performance surface and, by hand and then by your own small program, trace steepest descent and Newton's method from identical starts, recording the path each takes.","support":"~400 words on curvature and why it matters.","llc":"Show both trajectories and predict, live, where a new start would go."},
      {"option_no":4,"title":"An Associator That Remembers","primary":"Construct a linear associator (Hebb and pseudo-inverse) for a pattern set you choose, test recall under a small perturbation, and characterise when recall fails — all with your own computation.","support":"~400 words on the capacity limit you observed.","llc":"Demonstrate a successful and a failed recall live."},
      {"option_no":5,"title":"The Optimisation Theorem I Own","primary":"Select one optimality result from Unit V (necessary conditions / quadratic optimisation) and give a complete hand proof with a constructed example verifying it.","support":"~400 words on where the condition is necessary but not sufficient.","llc":"Present the proof and answer 'why is this step valid?' unscripted."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAE16'
  and is_latest = true and is_archived = false;

-- ── 26PMAED1 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Grow a real culture you can observe (yeast in sugar water, or mould on bread, or a plant seedling) and record a size/quantity measure daily for 5 days; fit exponential growth by the method of least squares by hand.","deliverable_notes":"Your dated real measurements + the hand least-squares fit (growth rate) + 1 line on how well exponential growth described your organism."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Using your Unit-I data or a named public microbial-growth dataset, identify the phase where growth stops being exponential and estimate the limiting value; relate it to chemostat/logistic ideas.","deliverable_notes":"Your annotated growth curve marking the phases + the estimated carrying capacity + 2 sentences on what limited the growth."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Take real or textbook Michaelis–Menten data (substrate vs rate) and, by hand, linearise it (Lineweaver–Burk) to extract Vmax and Km.","deliverable_notes":"Your hand-drawn double-reciprocal plot + the Vmax and Km you extracted + 1 line on what Km means biologically."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"For a cooperative/allosteric enzyme case you pick, compute the Hill coefficient from given data by hand and state whether it shows positive cooperativity.","deliverable_notes":"Your hand computation of the Hill coefficient + the conclusion + 1 line on what cooperativity does for the organism."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Use the graph-theory / steady-state approach to write and solve (by hand) the rate equations for a simple 2-state enzyme–substrate scheme you draw.","deliverable_notes":"Your reaction diagram + the hand-solved steady-state expression + 1 line on the assumption steady-state makes."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Growth Curve I Grew","primary":"Culture a real living thing (named, safe, at home or in the lab), measure its growth over at least a week yourself, and fit the mathematical model (exponential then limited) by hand, extracting the rate and carrying capacity.","support":"~400 words on where the model fit and where biology defied it.","llc":"Present your real data and curve; faculty may ask you to predict day 10."},
      {"option_no":2,"title":"Enzyme Kinetics from Real Numbers","primary":"Take a real or named-source substrate–rate dataset and, by hand, extract Vmax and Km via linearisation, then interpret both quantities for the actual enzyme.","support":"~400 words on why Km, not Vmax, tells you about affinity.","llc":"Reconstruct the linearisation live and answer a 'what if Km doubled?' question."},
      {"option_no":3,"title":"When Exponential Growth Stops","primary":"Using your own or a named microbial dataset, model the full growth curve, identify mathematically where exponential breaks down, and estimate the limit with a hand method.","support":"~400 words on the biological causes of the ceiling.","llc":"Defend your phase boundaries with the data on screen."},
      {"option_no":4,"title":"Cooperativity, Quantified","primary":"For a named cooperative enzyme (e.g. haemoglobin oxygen binding) obtain data and compute the Hill coefficient by hand, arguing what it reveals about the molecule's behaviour.","support":"~400 words linking the number to physiology.","llc":"Present the computation and answer why the sigmoid shape matters."},
      {"option_no":5,"title":"A Model I Solved for a Living System","primary":"Choose one life-science process from the syllabus, draw its scheme, derive the governing equation, and solve it by hand for parameter values you justify from a real or named source.","support":"~400 words on the assumptions and their biological cost.","llc":"Defend the derivation step by step."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAED1'
  and is_latest = true and is_archived = false;

-- ── 26PMAED2 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Take one real argument from a named newspaper editorial or public speech; write it in propositional-logic form and test its validity by hand.","deliverable_notes":"The quoted argument (source named) + your symbolic translation + your validity check + 1 line on whether it was actually valid."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Model one real budgeting or break-even situation you know (a small shop, a household, an event) as a linear or quadratic equation and solve it by hand.","deliverable_notes":"The real situation named + your equation + the hand solution + 1 line on what the answer meant for the real case."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Take real paired data you gather (e.g. price vs quantity, or hours studied vs marks for people who consent) and fit a function; sketch and interpret its graph.","deliverable_notes":"Your real data + the fitted function + hand-drawn graph + 1 line interpreting the relationship."},
      {"sno":4,"unit":"IV","finks_dimension":"Integration","task":"Use a logarithmic or exponential model for a real social quantity (population, prices, social-media followers of a named account over time) and estimate its rate by hand.","deliverable_notes":"The real time-series (source named) + your log/exp fit + the growth rate + 1 line on what it predicts."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Set up a real small system (e.g. two goods, two constraints, from a scenario you describe) as a matrix and solve it by row-reduction to echelon form by hand.","deliverable_notes":"Your matrix from the real scenario + the hand row-reduction + the solution + 1 line on what it means."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"An Argument I Tested Logically","primary":"Collect three real public arguments (named editorials, ads, or speeches), formalise each in logic, and rule on their validity by hand — separating valid form from persuasive but invalid reasoning.","support":"~400 words on one argument that felt right but wasn't.","llc":"Present one and let the audience propose a counter-case to test live."},
      {"option_no":2,"title":"The Mathematics of a Real Local Decision","primary":"Take a genuine social or economic decision near you (pricing at a named shop, allocating an event budget, a household choice) and build and solve the equation or matrix system that captures it, by hand.","support":"~400 words on what the math showed that intuition missed.","llc":"Defend your model when a parameter is changed."},
      {"option_no":3,"title":"A Trend I Fitted and Projected","primary":"Gather a real social time-series (named source, 8+ points) and fit a log/exponential/polynomial model by hand, then make and justify a short projection.","support":"~400 words on the risk of extrapolation.","llc":"Present and answer 'what would change your projection?'"},
      {"option_no":4,"title":"Relationships in Data I Collected","primary":"Collect paired data from real, consenting people or named sources, fit and graph the relationship by hand, and interpret it honestly (including 'no clear relationship' if that's the truth).","support":"~400 words on correlation-not-causation in your own case.","llc":"Show the graph and defend your interpretation."},
      {"option_no":5,"title":"A System Solved for Society","primary":"Model a real allocation problem (resources, seats, goods) as a matrix system, solve it by hand row-reduction, and check the solution against the real situation.","support":"~400 words on the assumptions the model imposes.","llc":"Re-solve with one changed constraint live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAED2'
  and is_latest = true and is_archived = false;

-- ── 26PMAED3 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Design and run a tiny real data collection (survey or count) of at least 20 named-context observations you gather yourself; classify your variables.","deliverable_notes":"Your raw data with the collection context named + your classification of each variable (nominal/ordinal/etc.) + 1 line on one bias in your collection."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"From your Unit-I data (or a named dataset), build a frequency distribution and draw one chart BY HAND (bar/pie/histogram) that honestly represents it.","deliverable_notes":"Your frequency table + the hand-drawn chart + 1 line on why you chose that chart type."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Compute mean, median and mode of your real data by hand, and compute one probability from a real count in it.","deliverable_notes":"Your three hand-computed central-tendency values + the probability + 1 line on which measure best summarises YOUR data and why."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Work one permutation/combination and one binomial-distribution problem grounded in a real scenario you describe (e.g. arranging people, a pass/fail count).","deliverable_notes":"Your two hand computations with the real scenario stated + 1 line on what the binomial assumed."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Read one real published statistic in the news (named source) and critique it using the ideas of statistical inquiry and social-statistics concepts from Units IV–V.","deliverable_notes":"The quoted statistic (source named) + your 3–4 sentence critique naming one methodological concern."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Small Study I Ran End to End","primary":"Design, collect (real, consenting respondents or real counts you name), tabulate, chart-by-hand, and summarise a genuine small statistical study on a question you care about locally.","support":"~400 words on the sources of error you met.","llc":"Present your findings and defend one number against a 'could this be chance?' challenge."},
      {"option_no":2,"title":"The Honest Chart","primary":"Take one real dataset and produce, by hand, both an honest visualisation and a deliberately misleading one, explaining exactly what technique makes the second deceive.","support":"~400 words on how to read charts critically.","llc":"Show both and let the audience spot the trick."},
      {"option_no":3,"title":"Probability in a Real Situation","primary":"Identify a real repeatable situation (a game, a queue, a pass/fail process you can name) and compute its probabilities by hand, then test one prediction against actual observed frequency.","support":"~400 words on the gap between theoretical and observed.","llc":"Defend your model when the audience changes the setup."},
      {"option_no":4,"title":"A Statistic in the News, Interrogated","primary":"Pick a real, currently-circulating statistic (named source), reconstruct how it was likely computed, and write a rigorous critique of its method and presentation.","support":"~400 words on what a responsible version would report.","llc":"Present the critique and answer a defence of the original live."},
      {"option_no":5,"title":"Central Tendency That Tells the Truth","primary":"On a real skewed dataset you collect (incomes, prices, waiting times), compute mean/median/mode by hand and argue which one should be reported and why the others mislead.","support":"~400 words on where each measure is honest.","llc":"Defend your choice when an examiner proposes the misleading measure."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAED3'
  and is_latest = true and is_archived = false;

-- ── 26PMAED4 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Describe a real two-party strategic situation you have seen (a bargain at a named market, a sports tactic, a bidding) as a game: players, strategies, payoffs.","deliverable_notes":"Your payoff matrix for the real situation (parties named) + 1 line on what each player wanted."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"For a 2×2 or 3×3 game you build from a real scenario, find the saddle point by hand if one exists; state whether it is a game of perfect information.","deliverable_notes":"Your matrix + the hand search for a saddle point + the conclusion + 1 line on what the saddle point means for the players."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Take a game WITHOUT a saddle point and solve for the mixed strategy by hand (2×2 formula or graphical method).","deliverable_notes":"Your hand solution for the optimal mixed strategy + the game value + 1 line on what 'mixing' means in the real scenario."},
      {"sno":4,"unit":"IV","finks_dimension":"Integration","task":"Reduce a larger game by dominance by hand (eliminate dominated strategies) before solving; show each elimination step.","deliverable_notes":"Your dominance-elimination steps + the reduced game + its solution + 1 line on why the eliminated strategy was never worth playing."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Apply the mapping/graphical method by hand to solve one 3×n game or a constrained game you set up from a plausible real conflict.","deliverable_notes":"Your graphical construction + the optimal strategy read off it + 1 line connecting it back to the real conflict."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Real Rivalry, Modelled as a Game","primary":"Take a genuine competitive situation you can observe (two shops' pricing, a sport, an auction, a negotiation you witnessed) and build its game, solve for optimal strategies by hand, and compare the solution to what the real players actually did.","support":"~400 words on why reality did or didn't match theory.","llc":"Present and defend your payoffs when the audience disputes a number."},
      {"option_no":2,"title":"Saddle Point or Bluff?","primary":"Construct several games from real scenarios, determine by hand which have saddle points and which force mixed strategies, and explain what that structural difference means for how the players should behave.","support":"~400 words on pure vs mixed in everyday strategy.","llc":"Solve a fresh matrix live."},
      {"option_no":3,"title":"Mixing to Win","primary":"Find a real situation that has no pure-strategy solution, solve its mixed strategy by hand, and — if feasible — actually play it repeatedly against a willing partner to compare realised value with the theoretical value.","support":"~400 words on the experience of randomising.","llc":"Present the play-log and defend the value."},
      {"option_no":4,"title":"Dominance: Cutting a Game Down","primary":"Build a larger game (4×4 or bigger) from a real multi-option decision, reduce it fully by dominance by hand, and solve the residue — documenting why each removed strategy was dominated.","support":"~400 words on how dominance encodes rational elimination.","llc":"Reduce a fresh game live."},
      {"option_no":5,"title":"A Strategy Theorem I Can Defend","primary":"Take the minimax theorem or a property of optimal strategies from the course and produce your own explanation/proof plus a constructed game demonstrating it.","support":"~400 words on why the value of a game is well-defined.","llc":"Present and answer 'why must an optimal mixed strategy exist?'"}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAED4'
  and is_latest = true and is_archived = false;

-- ── 26PMAED5 · m-sc-mathematics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Find a real physical tally/counting artefact or practice near you (a shopkeeper's ledger notation, a temple inscription number, a traditional measuring method) and document it; compare with an ancient system studied.","deliverable_notes":"Your photo of the real artefact/practice (place named) + your comparison to one historical number system + 1 line on what is shared."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Reconstruct BY HAND one computation using an early-civilisation method (a Babylonian sexagesimal calculation, an Egyptian doubling multiplication, or an Indian method) — not modern arithmetic.","deliverable_notes":"Your hand computation done in the historical method + the same result in modern form + 1 line on what the old method makes easy or hard."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Produce your own complete proof of the Pythagorean theorem using one method attributed to the period (dissection/geometric), drawn and argued by hand.","deliverable_notes":"Your hand-drawn geometric proof + the argument in your words + 1 line on why the Greeks valued proof over calculation."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Take one proposition from Euclid's Elements (name the book and number) and reconstruct its proof from the axioms by hand, in your own words.","deliverable_notes":"The named proposition + your hand-written reconstruction of its proof + 1 line on which postulate did the crucial work."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Solve one Diophantine problem by hand in the spirit of the Arithmetica, showing the reasoning, not just the answer.","deliverable_notes":"The problem + your hand solution with reasoning + 1 line on what algebraic notation (absent then) would have made easier."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"An Old Method, Worked by My Hand","primary":"Choose one historical computational method (Babylonian, Egyptian, Greek, or classical Indian) and carry out several non-trivial calculations in it entirely by hand, documenting how the method thinks differently from modern arithmetic.","support":"~400 words on what you understood about the mathematicians by working as they did.","llc":"Perform one calculation in the old method live at the board."},
      {"option_no":2,"title":"A Proof I Rebuilt from the Axioms","primary":"Select a Euclidean proposition and reconstruct its full proof from the postulates by hand, then present a clear modern restatement — showing you can move between the two.","support":"~400 words on the idea of the axiomatic method and why it was revolutionary.","llc":"Defend each step; faculty may question which postulate a step relies on."},
      {"option_no":3,"title":"Mathematics in My Own Region's Past","primary":"Investigate a real local mathematical heritage — temple geometry, traditional measurement, ledger/accounting notation, calendar computation — through a named site, artefact, or a consented interview with an elder or craftsperson, and connect it to a tradition in the syllabus.","support":"~400 words on the living link between formal and folk mathematics.","llc":"Present your evidence (photos/quotes) and answer questions on the connection."},
      {"option_no":4,"title":"The Pythagorean Theorem, Three Ways","primary":"Produce, by hand, three genuinely different proofs of the Pythagorean theorem drawn from different traditions/periods, and compare what each reveals.","support":"~400 words on why one theorem attracted so many proofs.","llc":"Draw one proof live when the examiner names it."},
      {"option_no":5,"title":"From Diophantus to Algebra","primary":"Solve a set of Diophantine problems by hand in the pre-notation style, then rewrite your solutions in modern algebraic symbolism, making the historical leap explicit.","support":"~400 words on what notation did for mathematical power.","llc":"Solve a fresh problem both ways live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26PMAED5'
  and is_latest = true and is_archived = false;

-- ── 26UBAC01 · bachelor-of-business-administration ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Stand for 30 minutes inside ONE real business you can name (a Kavandampatti provision store, a Komarapalayam power-loom shed, an Erode tea stall) and watch the owner or manager work. Spot the five management functions happening in front of you and note which 'level' of management this person sits at.","deliverable_notes":"One filled-in table: the shop's name and owner, plus one real thing you SAW for each of Planning, Organizing, Staffing, Directing, Controlling. Add 3-4 sentences naming the manager's level and one Scientific-Management idea (division of work, standard task) you actually saw."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Plan one real small task that will actually happen this week (a class function, a hostel outing, restocking a home shop). Write your objective, list 2 alternatives you considered, and record the ONE decision you finally took and why.","deliverable_notes":"Your hand-written planning sheet (objective, steps, the 2 rejected options, the chosen option) + a photo of the task actually done. Add 3-4 sentences on which type of decision it was (programmed / non-programmed) and one step of the decision process you skipped."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Interview the owner of ONE real firm with at least 4 workers (a bakery, a garment unit, a lorry-transport office in Sankari) and ask who reports to whom. Draw their real organization structure BY HAND showing span of control and one line of delegation.","deliverable_notes":"The hand-drawn org chart of the real firm (with the firm's name) + 3-4 sentences: is it line or line-and-staff, what is the owner's span of control, and one task they delegate versus one they never let go of."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Talk to ONE real supervisor who directs a team every day (a loom-shed maistri, a hotel captain, a site mason-head) about how they keep people coordinated and how they know when something is going wrong.","deliverable_notes":"A short quote in their own words (Tamil is fine, with translation) + their name and phone-verifiable contact + 3-4 sentences linking what they said to Direction, Co-ordination and the Control process (how they detect and correct a deviation)."},
      {"sno":5,"unit":"V","finks_dimension":"Caring","task":"Find ONE real ethical or environmental choice a nearby business faced (a dyeing unit's effluent, a shop over-charging, a mill's worker safety). Ask one insider or observe it yourself.","deliverable_notes":"A photo or a dated note of the real situation + 3-4 sentences: what the ethical issue was, whether the business acted responsibly toward workers/customers/environment, and one change you would make if you owned it. No preaching — describe what you actually found."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Boss I Watched for a Day","primary":"Shadow ONE real owner/manager you can name for a half-day (a Komarapalayam loom owner, an Erode textile-shop manager). Keep a live timed log of every act and sort each into Planning/Organizing/Staffing/Directing/Controlling. Bring the raw hand-written log with times.","support":"~400 words connecting your log to the manager's functions, level, and one school-of-thought approach you saw.","llc":"Show your timed log to the cohort and name the ONE moment that taught you what management really is."},
      {"option_no":2,"title":"How My Chettikadai Runs","primary":"Audit ONE real provision/kirana shop end to end: interview the owner, map how they plan stock, organize the shelves, direct any helper, and control cash and pilferage. Bring photos of the shop and your hand-written audit sheet.","support":"~400 words on how a tiny shop performs all five management functions without ever naming them.","llc":"Present the shop (named, with photos) and defend where its management is strong and where it is weak."},
      {"option_no":3,"title":"The Decision That Cost Money","primary":"Interview ONE real business owner about a genuine decision that went wrong or right (a wrong purchase, a new location, a hire). Capture their own words, the alternatives they had, and the outcome. Get a phone-verifiable contact.","support":"~400 words mapping their story onto the decision-making process and decision types from Unit II.","llc":"Play or read their quote and tell the cohort which step of the decision process, if followed, would have changed the outcome."},
      {"option_no":4,"title":"Who Answers to Whom","primary":"Build the real org chart of ONE named local firm with 5+ people by interviewing at least two workers at different levels. Show span of control, delegation, and any informal organization (who really gets things done off the chart).","support":"~400 words on authority vs power, centralization vs decentralization as you saw them in this real firm.","llc":"Show the hand-drawn chart and point to the one informal relationship no formal chart would ever reveal."},
      {"option_no":5,"title":"The Ethics Test on the Shop Floor","primary":"Document ONE real ethical situation in a nearby business (environment, worker, or customer) through your own observation plus one insider conversation. Bring dated evidence — a photo, a note, a quote — not a downloaded case.","support":"~400 words on business ethics, internal vs external ethics, and responsibilities of business, grounded only in what you found.","llc":"Describe the real situation to the cohort and take a stand on whether the business acted responsibly."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UBAC01'
  and is_latest = true and is_archived = false;

-- ── 26UBAC02 · bachelor-of-business-administration ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Sit at ONE real small shop (a tea kadai, a stationery shop) for one hour with the owner's permission and write down every real transaction that happens. Journalise at least 8 of them and post two to ledger accounts.","deliverable_notes":"Your hand-written journal of the real transactions (with the shop's name and date) + two ledger accounts + a 3-4 sentence note on which accounting concept (dual aspect, money measurement) each entry shows."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Take ONE real bank passbook or statement (your own, a parent's, or a shopkeeper's with permission) and one cash record for the same period. Prepare a Bank Reconciliation Statement for the real closing dates.","deliverable_notes":"The hand-prepared BRS with the two real balances + 3-4 sentences on the actual reasons for the difference you found (cheque not cleared, bank charges, direct credit). Mask account numbers for privacy."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Get ONE real small trader's rough figures (opening stock, purchases, sales, one expense) and their year-end details (closing stock they physically counted, one outstanding bill). Prepare their Trading and Profit & Loss account with at least two adjustments.","deliverable_notes":"The hand-prepared final accounts using the trader's real numbers + 3-4 sentences explaining the two adjustments you made (closing stock, outstanding/prepaid) and how each changed the profit."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Find ONE real person who bought something on hire-purchase or EMI (a bike, a fridge, a phone). Interview them: down payment, instalment, total paid, and how they felt about the interest.","deliverable_notes":"Their real figures written out + your calculation of total interest actually paid + a one-line quote in their words + 3-4 sentences on hire-purchase vs instalment and what repossession would have meant for them."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Find ONE real trader who does NOT keep proper double-entry books (a vegetable vendor, a small caterer). Watch/ask how they actually track money owed, cash, and stock without a ledger.","deliverable_notes":"A photo of their real record (notebook, diary, chalk board) + 3-4 sentences on the defects of single entry you saw firsthand, and how you would convert their figures using the Statement of Affairs method."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"One Day in the Cash Box","primary":"With permission, record EVERY real transaction of one named shop for a full working day, then journalise, post to ledgers, and draw the trial balance from your own data. Bring the raw day-log in your handwriting.","support":"~400 words on which basic concepts and conventions the shop's real transactions demonstrated.","llc":"Show your trial balance and prove it ties, then take one question on any entry the cohort points to."},
      {"option_no":2,"title":"Reconciling My Own Passbook","primary":"Reconcile a real bank passbook against a real cash record for one month. Bring both (numbers masked) and your hand-prepared BRS explaining every single difference you found.","support":"~400 words on why cash book and bank balance differ and what each reconciling item really was.","llc":"Walk the cohort through your two balances and defend each reconciling item as genuine, not assumed."},
      {"option_no":3,"title":"The Trader Who Keeps It All in His Head","primary":"Find a real single-entry trader, capture their actual opening and closing positions, and reconstruct their profit using the Statement of Affairs method. Get a phone-verifiable contact and a photo of their informal record.","support":"~400 words comparing single vs double entry and the defects you personally saw in their system.","llc":"Show their real notebook and explain how you turned scattered notes into a profit figure."},
      {"option_no":4,"title":"The Bike on Instalments","primary":"Interview a real person mid-way through a hire-purchase or EMI. Collect the exact figures, compute the true interest burden, and build the hire-purchase account. Quote them on the cost of buying on credit.","support":"~400 words on hire-purchase vs instalment systems and the real cost of default and repossession.","llc":"Read their quote and show the cohort how much more than the cash price they will actually pay."},
      {"option_no":5,"title":"Final Accounts of a Real Small Shop","primary":"Get one named small business's real year figures and prepare full final accounts with at least three adjustments (closing stock, depreciation, bad debts, outstanding). The stock figure must come from a real physical count you saw or the owner reported.","support":"~400 words on how each adjustment changed the true profit and why final accounts matter to this owner.","llc":"Present the profit figure and defend each adjustment when the cohort challenges it."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UBAC02'
  and is_latest = true and is_archived = false;

-- ── 26UBAC03 · bachelor-of-business-administration ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Walk into ONE real shop or brand outlet you can name (a Chennimalai handloom showroom, a local bakery, a mobile shop) and spot its Marketing Mix. Identify the actual Product, Price, Place and Promotion you can see with your eyes.","deliverable_notes":"A photo of the shop + a filled 4Ps table with the REAL product, real price tag, real location advantage and one real promotion you saw + 3-4 sentences on one environmental factor (competition, local income, festival season) affecting this shop right now."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Pick ONE real branded product in your home (a soap, a snack, a phone). Hold the actual package and read every claim, symbol and design choice on it. Judge where it sits in its Product Life Cycle.","deliverable_notes":"The real package (or clear photos of all sides) + 3-4 sentences integrating brand, packaging function, and your reasoned PLC stage (introduction / growth / maturity / decline) with the real market clue that told you so."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Trace ONE real product from where it is made to the shelf you buy it from (Erode turmeric, local milk, Salem mango, a power-loom towel). Ask the shopkeeper or a middleman how it reached them and at what price at each hop.","deliverable_notes":"A hand-drawn distribution channel with the real names and prices at each stage + 3-4 sentences on the channel type (direct / one-level / two-level) and one distribution problem the seller actually mentioned."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Collect real advertisements for ONE product category (say, jewellery or coaching centres) across at least three media you actually encounter this week — a newspaper insert, an FM/TV spot, a hoarding, a phone pop-up.","deliverable_notes":"Photos/clippings of the 3+ real ads (with where and when you saw each) + 3-4 sentences classifying each medium's characteristics and which one you think works best for this product and why."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Interview ONE real salesperson who sells face-to-face (a textile-shop salesman, an insurance agent, a two-wheeler showroom rep) about how they actually close a sale and stay motivated.","deliverable_notes":"A quote in their own words + their name and phone-verifiable contact + 3-4 sentences mapping their story to the personal-selling process steps and one motivation/compensation factor they mentioned."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Four Ps of One Real Shop","primary":"Do a full marketing-mix audit of ONE named local business by interviewing the owner and observing customers. Document its real Product, Price, Place, Promotion, plus its segmentation and one environmental threat. Bring photos and the owner's phone-verifiable contact.","support":"~400 words on how this real shop's 4Ps fit together and where the mix is weakest.","llc":"Present the shop with photos and recommend one concrete mix change, defending it to the cohort."},
      {"option_no":2,"title":"From Field to Shelf","primary":"Trace one real product's full journey from producer to you, hop by hop, by talking to at least two people in the chain (a farmer/weaver and a shopkeeper). Record the real price at each stage and the margin added.","support":"~400 words on the distribution channel, the margins, and one real problem in physical distribution you found.","llc":"Draw the live channel on the board and reveal how much of the final price is margin, not making-cost."},
      {"option_no":3,"title":"The Salesman's Playbook","primary":"Interview one real face-to-face salesperson in depth about their selling process, objections they hear, and how they are paid and motivated. Get a phone-verifiable contact and capture at least two direct quotes.","support":"~400 words connecting their real methods to the personal-selling process and sales-force motivation and control.","llc":"Play or read their quotes and teach the cohort the one selling move you did not learn from any textbook."},
      {"option_no":4,"title":"Why This Package Made Me Buy","primary":"Choose one real product and dissect its branding and packaging decisions from the physical package, then place it accurately in its Product Life Cycle using real market evidence (shelf space, discounts, new variants).","support":"~400 words on branding, packaging, and PLC stage evidence for this exact product.","llc":"Hold up the real package and defend your PLC verdict when the cohort argues for a different stage."},
      {"option_no":5,"title":"The Ad Wall","primary":"Build a real collection of at least six advertisements you personally encountered in one week across print, electronic, outdoor and internet media. Photograph each with where/when you saw it and analyse the communication and sales-promotion tools used.","support":"~400 words on the communication mix, media characteristics, and which ad you judge most effective and why.","llc":"Show your ad wall and rank the ads live, defending your top pick against the cohort's."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UBAC03'
  and is_latest = true and is_archived = false;

-- ── 26UBAC04 · bachelor-of-business-administration ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Pick ONE real product someone actually makes near you (100 idlis at a mess, a batch of jamakkalam at a Bhavani loom, 50 school bags at a small unit). Get the real material, labour and overhead figures and build a cost sheet.","deliverable_notes":"The hand-prepared cost sheet with real figures (name the maker) + 3-4 sentences classifying the costs (direct/indirect, fixed/variable) and stating the cost per unit you calculated."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Get ONE real company's published financials — take a listed company's two most recent years from its annual report or a screenshot from a finance site. Prepare a Comparative Statement or Common-Size statement by hand.","deliverable_notes":"Your hand-prepared comparative/common-size statement with the real figures and company name + 3-4 sentences on the biggest year-on-year change you found and what it might mean for the business."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"From ONE real company's published balance sheet and profit statement, compute at least four ratios by hand — one liquidity, one profitability, one turnover, plus one more of your choice.","deliverable_notes":"The four computed ratios shown with the real figures plugged in (name the company and year) + 3-4 sentences interpreting whether each ratio is healthy and the one ratio that worries you most."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Prepare ONE real budget vs actual for a real unit of spending you can access — your own month, a hostel mess, a family shop. Set the budgeted figures, then record what was actually spent.","deliverable_notes":"The hand-written budget-vs-actual table with real numbers + 3-4 sentences on the largest variance, whether it was favourable or adverse, and what budgetary-control action you would take next month."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Find ONE real small venture you understand (a juice stall, a photocopy shop) and estimate its real fixed cost per month, variable cost per unit, and selling price. Compute its break-even point in units.","deliverable_notes":"The break-even calculation with the venture's real figures (name it) + a hand-drawn break-even chart + 3-4 sentences on how many units a day they must sell to survive and their margin of safety."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"What It Really Costs to Make 100 of These","primary":"Build a full cost sheet for one real product a named maker actually produces, from real material/labour/overhead figures you collected on site. Bring the raw figures in the maker's or your handwriting and the product itself or a photo.","support":"~400 words on cost classification, cost per unit, and how a tender/quotation price would be set from it.","llc":"Show the product and reveal its true cost per unit, then defend one overhead you had to estimate."},
      {"option_no":2,"title":"Reading a Real Company's Health","primary":"Take one real listed company's latest annual report and compute a full set of ratios (liquidity, profitability, turnover) by hand from the actual figures. Bring the report pages you used.","support":"~400 words interpreting the ratios and delivering a verdict on the company's financial health.","llc":"Give your verdict to the cohort and defend it against the one ratio someone uses to argue back."},
      {"option_no":3,"title":"The Break-Even of a Roadside Venture","primary":"Study one real micro-venture, collect its genuine fixed cost, variable cost per unit and price, and compute break-even and margin of safety. Name the venture and photograph it operating.","support":"~400 words on CVP relationships and what the break-even means for this real owner's daily survival.","llc":"Draw the break-even chart live and tell the cohort exactly how many sales a day keep this venture alive."},
      {"option_no":4,"title":"A Family Budget vs What Actually Happened","primary":"Set a real monthly budget for a real spending unit, then track actual spending for the month and analyse every major variance. Bring the real receipts or log that back your actual figures.","support":"~400 words on budgetary control, favourable vs adverse variances, and the control action each variance demands.","llc":"Present your biggest variance and the control decision it forced, and take the cohort's challenge on it."},
      {"option_no":5,"title":"Two Years, Side by Side","primary":"Do a comparative and trend analysis of one real business across two or more years using published or owner-provided figures. Show what grew, what shrank, and what it signals. Cite your real source.","support":"~400 words on comparative/common-size/trend analysis and the story the numbers tell about this business.","llc":"Show your side-by-side statement and name the single trend you would warn this owner about."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UBAC04'
  and is_latest = true and is_archived = false;

-- ── 26UBANM1 · bachelor-of-business-administration ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Attend or recall one real event you have seen (a named college function, temple festival, wedding, shop opening) and list every management activity you can identify behind it.","deliverable_notes":"The named event + your activity list + 1 line on the activity you think was hardest to organise."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Design the concept for a small real event you could actually run (e.g. a class farewell, a street awareness drive) — theme, flow, and one evaluation criterion.","deliverable_notes":"Your one-page concept + design sketch + 1 line on the audience you designed it for."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Do a real SWOT analysis for your Unit-II event concept, grounded in actual resources you have or lack.","deliverable_notes":"Your SWOT grid with real, specific entries + 1 line on the one weakness that could sink the event."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Build the marketing plan for your event using the 5 Ps, naming real channels available to you (a specific WhatsApp group, notice board, local shop).","deliverable_notes":"Your 5-Ps plan with named real channels + 1 line on the cheapest high-reach channel you found."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Prepare a realistic line-item budget for your event with real quantities and looked-up local prices, and identify one possible sponsor.","deliverable_notes":"Your itemised budget (real prices, source noted) + the named potential sponsor + 1 line on your break-even."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"An Event I Planned for Real","primary":"Produce a complete, executable plan for a REAL small event you could actually run (named audience, venue, date-window) — concept, feasibility (SWOT), 5-Ps promotion with real channels, and a line-item budget with looked-up local prices. If you can, actually run a scaled-down version and capture evidence.","support":"~400 words on the gap between plan and reality.","llc":"Pitch your event and defend the budget when a cost is challenged."},
      {"option_no":2,"title":"The Budget That Has to Balance","primary":"Build a rigorous, real-priced budget for an event, sourcing every figure from an actual vendor/shop you name, and find the sponsorship or pricing that makes it break even.","support":"~400 words on the hardest cost to control.","llc":"Defend your numbers when an examiner adds an unexpected expense."},
      {"option_no":3,"title":"Marketing on a Student's Budget","primary":"Design and, if possible, run a real low-cost promotion for an actual event/cause using named local channels, and measure the reach or response you actually got.","support":"~400 words on which of the 5 Ps mattered most for you.","llc":"Present your reach evidence and answer 'how would you double it?'"},
      {"option_no":4,"title":"Feasibility: Would It Actually Work?","primary":"Take an event idea and stress-test it with a real, evidence-based feasibility study — actual resources, real constraints, a genuine SWOT with named specifics — and give an honest go/no-go verdict.","support":"~400 words on the assumption you were most wrong about.","llc":"Defend your verdict against a 'but what if...' challenge."},
      {"option_no":5,"title":"Behind One Real Event","primary":"Study a real event that already happened near you by interviewing (with consent) one person who organised it, and reconstruct its management story — activities, budget scale, what went wrong.","support":"~400 words on what the organiser knew that no textbook says.","llc":"Present the story and the lessons, answering questions on the choices made."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UBANM1'
  and is_latest = true and is_archived = false;

-- ── 26UBANM2 · bachelor-of-business-administration ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Human Dimension","task":"Do an honest self-assessment of your own core competencies and learning style using a structured method from Unit I; get one piece of feedback from a named person who knows you.","deliverable_notes":"Your self-assessment + the named person's one feedback point + 1 line on a gap between how you and they see you."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Take a real self-esteem or personality-mapping instrument, complete it honestly, and reflect on one specific result with a real example from your life.","deliverable_notes":"Your result + the real personal example that supports or contradicts it + 1 line on one thing you'll act on."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Record one real situation this week where you managed (or failed to manage) an emotion; analyse it with the emotional-intelligence components.","deliverable_notes":"Your account of the real situation + your EI analysis + 1 line on what you'd do differently."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Apply a critical-thinking or creative-thinking technique to a real decision you actually face, and document the reasoning steps.","deliverable_notes":"The real decision + your step-by-step reasoning using the named technique + 1 line on whether it changed your choice."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Deliver one real short oral presentation OR conduct one real meeting/role-play with named peers, and collect their honest feedback.","deliverable_notes":"Evidence it happened (photo/peer sign-off) + the feedback you received + 1 line on your biggest delivery weakness."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Skill I Actually Built","primary":"Choose one managerial/interpersonal skill (public speaking, emotional regulation, critical decision-making), set a concrete goal, practise it over the semester with REAL evidence (recorded talks, a decision log, peer feedback from named people), and document your measurable change.","support":"~400 words honestly assessing how far you moved and what's still hard.","llc":"Demonstrate the skill live and answer questions on your growth process."},
      {"option_no":2,"title":"My Emotional-Intelligence Log","primary":"Keep a real, dated log over several weeks of situations where you observed and managed your emotions, analyse the patterns with EI theory, and identify one concrete trigger you learned to handle.","support":"~400 words on the hardest entry to write honestly.","llc":"Present one anonymised situation and answer how you'd coach a peer through it."},
      {"option_no":3,"title":"A Real Decision, Reasoned Through","primary":"Take an actual decision you face (course, work, money, relationship — your choice) and apply structured critical- and creative-thinking tools to it, documenting every step and the option you rejected.","support":"~400 words on whether the structure improved on gut instinct.","llc":"Walk the cohort through your reasoning and defend it under questioning."},
      {"option_no":4,"title":"Feedback That Changed Me","primary":"Seek genuine, structured feedback from three named people on one aspect of how you work with others, act on it, and gather evidence of the change over time.","support":"~400 words on the feedback that was hardest to hear.","llc":"Share the feedback loop and answer 'what did you do about it?'"},
      {"option_no":5,"title":"Leading a Real Small Task","primary":"Take responsibility for a real small group task (a class activity, a family event, a team assignment), apply the managerial skills of the course, and capture what actually happened including the friction.","support":"~400 words on the gap between managing yourself and managing others.","llc":"Present the experience and answer a 'what would you do differently?' challenge."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UBANM2'
  and is_latest = true and is_archived = false;

-- ── 26UBAS01 · bachelor-of-business-administration ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Human Dimension","task":"Watch ONE real conversation where a message did NOT get through cleanly — a customer and shopkeeper misunderstanding a price, a parent and child, two people across a language gap. Note exactly where the barrier appeared.","deliverable_notes":"A short dated description of the real exchange (who, where) + 3-4 sentences naming the barrier (language, noise, perception, emotional) and one communication-etiquette fix that would have prevented it. Do not invent the dialogue — report what you heard."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Write ONE real business letter you actually need — a genuine enquiry, complaint, or request to a real shop, office or supplier. Follow correct layout and send or hand it over.","deliverable_notes":"A photo/scan of your hand-written or typed letter with correct layout (name the real recipient) + proof you sent it (photo of envelope, screenshot, or delivery note) + 3-4 sentences on the letter type and the tone you chose."},
      {"sno":3,"unit":"III","finks_dimension":"Human Dimension","task":"Conduct ONE real 5-minute mock interview with a classmate or elder as the candidate. As you ask questions, watch and note their body language — eye contact, hands, posture — and your own.","deliverable_notes":"Your hand-written interviewer notes + a body-language observation list of at least four real signals you saw and what each suggested + 3-4 sentences on how body language changed your read of the answers."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Attend ONE real meeting you are part of (a class committee, a club, a family function planning, a hostel meeting) and take the Minutes as it happens.","deliverable_notes":"The actual Minutes you wrote (date, attendees present, decisions, action points with names) + 3-4 sentences on what was hard to capture live and how you decided what to record versus leave out."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Build ONE real modern-communication artefact from scratch: record a 60-second voice podcast on a topic you know, OR create a real professional networking profile, OR run/join a real virtual meeting and note its etiquette.","deliverable_notes":"The real artefact (audio file, profile screenshot, or meeting notes with date) + 3-4 sentences on what you had to learn to make it, and one etiquette rule of that medium you discovered by doing it."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Letter That Got a Reply","primary":"Write and actually send a real business letter to a real recipient for a genuine purpose, then capture whatever reply or response you receive. Bring both your letter and the real reply (or proof of non-reply).","support":"~400 words on letter layout, tone, letter type, and what the reply taught you about business communication.","llc":"Read your letter and the real reply aloud and tell the cohort what you would rewrite now."},
      {"option_no":2,"title":"Reading the Room","primary":"Conduct a real recorded or witnessed mock interview and produce a detailed body-language and communication analysis of the candidate. Get the candidate's consent and name them. Capture at least six real non-verbal signals.","support":"~400 words on interviews, body language, and communication barriers you observed live.","llc":"Replay or describe one real moment and teach the cohort what the body said that the words did not."},
      {"option_no":3,"title":"Minutes of a Meeting I Sat In","primary":"Take live Minutes of a real meeting you attend, then convert them into a clean formal record and one follow-up email/report. Name the meeting, date and attendees; bring your raw live notes too.","support":"~400 words on report/minutes writing and the discipline of recording a live meeting accurately.","llc":"Show your raw notes beside the clean Minutes and explain one judgement call you made about what to record."},
      {"option_no":4,"title":"My First Podcast","primary":"Produce one real modern-communication artefact end to end — a 2-3 minute podcast, a professional networking profile, or a hosted virtual meeting with an agenda — and document what you built and learned.","support":"~400 words on the chosen modern medium, its etiquette, and the skills you had to teach yourself.","llc":"Play or demo your real artefact to the cohort and take one question on why you made a key choice."},
      {"option_no":5,"title":"The Barrier I Watched Break Down","primary":"Document one real communication breakdown you witnessed over several days, trace exactly what caused it, and design the etiquette or channel fix that would have solved it. Report only real observed exchanges.","support":"~400 words on barriers to communication and communication etiquette, grounded in your real observations.","llc":"Tell the cohort the real story and defend your one-line fix against their doubts."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UBAS01'
  and is_latest = true and is_archived = false;

-- ── 26UBAS02 · bachelor-of-business-administration ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Human Dimension","task":"Practise a real professional greeting-and-introduction with THREE different real people this week (a shopkeeper, a senior, a stranger at an office). Vary the handshake/namaskaram, eye contact and opening line, and note how each reacted.","deliverable_notes":"A short log of the 3 real greetings (who, where, how they responded) + a photo or a witness name for at least one + 3-4 sentences on the ABCs of etiquette and what personal-spacing or manners lesson each reaction taught you."},
      {"sno":2,"unit":"II","finks_dimension":"Caring","task":"Find out ONE real workplace's actual rule for handling conflict or preventing harassment — ask a working relative, an intern-senior, or read a real office's displayed policy. Do not use a generic internet policy.","deliverable_notes":"A photo or written note of the real policy/rule with the workplace named + 3-4 sentences on why this rule protects people, how hierarchy and protocol support it, and one conflict-resolution step it prescribes."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Make ONE real professional phone call and write ONE real professional email/chat message for a genuine purpose (booking, enquiry, follow-up). Apply telephone courtesy and email-etiquette rules deliberately.","deliverable_notes":"A screenshot of the real email/chat you sent (recipient named) + a 3-4 line script of how your real call opened and closed + 3-4 sentences on the courtesy rules you used and one you saw others break."},
      {"sno":4,"unit":"IV","finks_dimension":"Integration","task":"Interview ONE real person from a different region, religion or culture than yours about a workplace taboo, custom or greeting that outsiders often get wrong. Get their name and phone-verifiable contact.","deliverable_notes":"A quote in their words + their name/contact + 3-4 sentences integrating cultural sensitivity, one taboo you learned, and how inter-cultural awareness would change your behaviour at a diverse workplace."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Assemble ONE real head-to-toe business-appropriate outfit from clothes you actually own or borrow, following a specific dress-code guideline (formal / business-casual). Groom fully and get someone to photograph you.","deliverable_notes":"A full-length photo of you in the real outfit + a labelled note on each choice (attire, footwear, grooming) against the dress code + 3-4 sentences on what your appearance signals to an employer and one thing you would upgrade."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Greeting Experiment","primary":"Practise professional greetings and introductions with at least six real people across a week, filming or logging each with consent, and analyse how manners, spacing and confidence changed the response you got.","support":"~400 words on the ABCs of etiquette, professional conduct, and personal spacing from your real trials.","llc":"Demonstrate your best and worst real greeting to the cohort and explain what made the difference."},
      {"option_no":2,"title":"Handling the Rude Caller","primary":"Build a real telephone-and-email etiquette kit: make and log at least three genuine professional calls (including one difficult one) and send three real professional emails, then extract the rules that worked.","support":"~400 words on telephone courtesy, email etiquette, and handling rude or impatient clients.","llc":"Role-play your hardest real call for the cohort and defend how you kept it courteous."},
      {"option_no":3,"title":"Dressed for the Job","primary":"Assemble and photograph two real business outfits (one formal, one business-casual) for a specific job you might apply to, fully groomed, and justify every element against a real dress code. Use only clothes you can actually wear.","support":"~400 words on business attire, professional image, and grooming for success.","llc":"Present both real looks to the cohort and take their verdict on which fits the target job better."},
      {"option_no":4,"title":"Across the Culture Line","primary":"Interview two real people from cultures different from yours about workplace taboos, greetings and sensitivities, and produce a practical do/don't guide for a diverse office. Get phone-verifiable contacts.","support":"~400 words on diversity, cultural sensitivity, taboos and inter-cultural communication from real voices.","llc":"Share the most surprising real taboo you learned and explain how it would change your workplace behaviour."},
      {"option_no":5,"title":"The Etiquette Audit of a Real Workplace","primary":"Spend time observing one real workplace (a bank branch, a showroom, a clinic) and score its etiquette — greetings, courtesy, phone handling, dress, accessibility — against the module's standards. Bring dated observation notes.","support":"~400 words on professional conduct, disability etiquette and company etiquette policy from what you saw.","llc":"Present your real scorecard and name the one etiquette gap that most hurt this workplace's image."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UBAS02'
  and is_latest = true and is_archived = false;

-- ── 26UCAC01 · bachelor-of-computer-applications ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Go to ONE named local shop or vendor (e.g. the vegetable seller at Kavandampatti weekly sandhai, or your neighbourhood Amman Stores) and note the real price of 5 items. Write a Python program that stores each price in a correctly-typed variable and prints the total and average using operators and the print function.","deliverable_notes":"A screenshot of your code running on your own laptop, with your name and roll number in a comment line, plus the hand-written slip showing the shop's name, its location and the 5 real prices you noted. Write 3-4 sentences: which data type you chose for each value and why, and one operator you used."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Walk your own street or hostel floor and collect the real first names of 15 people. Store them in a Python list, then use string methods plus a dictionary or set to count how many names start with each letter and to find any duplicate names.","deliverable_notes":"The running-code screenshot plus the hand-written list of the 15 real names with your street or hostel name written at the top. Write 3-4 sentences on which data structure removed the duplicates and one string method you used and why."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Model ONE real local thing as a Python class - the auto-rickshaw you take, your family's two-wheeler, or a named tea stall. Give it real attributes (owner's name, last 4 digits of the number plate, the real fare or price) and one method that computes something real.","deliverable_notes":"Running code that creates at least two real objects (for example two named autos at your stand) plus a hand-drawn sketch of the class showing its attributes and one method. Write 3-4 sentences on how the class ties data and behaviour together for the real thing you chose."},
      {"sno":4,"unit":"IV","finks_dimension":"Learning How to Learn","task":"Take the real prices or names you collected earlier, write them to a CSV file with Python, close the program, then write a SECOND program that reads the CSV back and prints one summary. Notice what breaks when a value is missing.","deliverable_notes":"The two running-code screenshots plus the actual CSV file opened in a viewer with your real data visible, and one sentence naming a bug you hit and how you found it. Write 3-4 sentences on why saving to a file behaves differently from holding a value in a variable."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Build a tiny Tkinter window (or a Django form) that does ONE arithmetic job a real named person needs - a shopkeeper's bill total, or your mother's monthly milk tally. Sit with that person and let THEM click it once.","deliverable_notes":"A photo of the real person using your program on your screen (their hand or face in frame, with consent) plus one quoted sentence of what they said and a screenshot of the working interface. Write 3-4 sentences on one thing you changed after watching them use it."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Shopkeeper Who Adds Faster Than My Code","primary":"Interview ONE named local shopkeeper or vendor (phone-verifiable) who totals bills by mental maths. Time them against your Python billing script on 10 real items and record their voice, with consent, explaining one trick they use.","support":"~400 words linking their method to variables, loops and functions from Units I-II.","llc":"Play their voice, show your code, and tell the cohort who was faster and why. AI cannot interview YOUR shopkeeper."},
      {"option_no":2,"title":"My Family Ledger, Now in Code","primary":"Borrow ONE real handwritten register from home or a named shop - a kirana tally, a milk book, a chit-fund sheet. Write Python to read the entries and compute real totals per person and per month.","support":"~400 words on the data structures you chose and one entry that broke your first attempt.","llc":"Hold up the real register and demo your code live against it. AI cannot read YOUR register."},
      {"option_no":3,"title":"A Tool for One Real Person","primary":"Find ONE named person with a repeating calculation - a tailor pricing stitches, an auto driver logging trips, a grandmother tracking medicines. Build a Python program that does it for them and let them actually use it; capture a photo and one quoted reaction.","support":"~400 words on requirements you learned only by watching them.","llc":"Demo the tool and share what they taught you that no tutorial did."},
      {"option_no":4,"title":"Thirty Days of One Real Number","primary":"Log ONE real measurement by hand every day for 20-30 days - bus arrival time at a named stop, the tomato price, your town's temperature. Write Python to load your hand-log and find the maximum, minimum, average and biggest jump.","support":"~400 words on what the code revealed that the raw sheet hid.","llc":"Show the hand-written log and the chart your code produced from it."},
      {"option_no":5,"title":"The Class That Is My Street","primary":"Model 8-10 REAL houses and shops on your own street as Python objects with real, verifiable attributes. Use inheritance to separate houses from shops and a method that answers one real question (nearest shop, total shops).","support":"~400 words on your class design and where reality resisted it.","llc":"Walk the cohort down your street through your objects and defend the design under questions."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCAC01'
  and is_latest = true and is_archived = false;

-- ── 26UCAC02 · bachelor-of-computer-applications ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Pick ONE real repeated calculation from your day - auto fare by distance, recharge validity, a cricket run-rate. Write a C++ program with an OVERLOADED function (same name, e.g. fare or area) that handles the two real cases you actually face, using loops and conditionals.","deliverable_notes":"A running-code screenshot on your machine (your name in a comment) plus a hand-written note of the two real cases with their real numbers and your two function signatures. Write 3-4 sentences on why function overloading suited these two real cases better than two differently-named functions."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Create a C++ class for a real category of object you can physically see five or more of - the books on your shelf, the shirts in your almirah, the bats in the sports room. Make an array of objects holding REAL data (title, real price, real count) and a static member that counts how many objects were created.","deliverable_notes":"A running-code screenshot printing your real array plus a photo of the actual objects you modelled, with your hand in frame, and a note of the real data. Write 3-4 sentences on what the static member counted and the job the constructor did."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Model a REAL hierarchy you know - vehicles at a named stand (base Vehicle to Auto and Bus), or staff at a named shop. Use inheritance and overload ONE operator (for example + to combine two real fares or two real bills).","deliverable_notes":"Running code plus a hand-drawn inheritance tree of the real hierarchy with the real names labelled, and the real numbers your overloaded operator combined. Write 3-4 sentences on which inheritance type (single, hierarchical, hybrid) matched the reality and why."},
      {"sno":4,"unit":"IV","finks_dimension":"Learning How to Learn","task":"BEFORE you compile, hand-trace on paper how a pointer and a virtual-function call move through memory for a tiny two-class polymorphism example. Then run the program and compare the real output with your paper trace.","deliverable_notes":"A photo of your hand-drawn box-and-arrow memory trace plus the running-code screenshot, and one sentence naming where your trace was wrong and what corrected it. Write 3-4 sentences on what pointers let you do that plain variables could not."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Ask ONE real named person for 5 real records - classmates' names plus a number they consent to share, or a shopkeeper's 5 items. Write a C++ program that writes them to a file and reads them back, with exception handling for one bad input that person might actually give.","deliverable_notes":"The data file with the real records visible plus a running-code screenshot and one quoted line from the person about sharing their data. Write 3-4 sentences on the bad input you guarded against and why a file outlasts the running program."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Fare Machine at My Auto Stand","primary":"Visit a named auto or bus stand and get the real fare rules from ONE named driver (phone-verifiable). Build a C++ program with classes and function overloading that reproduces his fare logic for 10 real routes, and record him stating one rule.","support":"~400 words mapping his spoken rules onto your classes and functions.","llc":"Play his voice and demo your fare machine against his real numbers."},
      {"option_no":2,"title":"Everything on My Shelf, as Objects","primary":"Model 10 REAL physical objects you own (books, tools, clothes) as a C++ class with an array of objects and a static count, and overload one operator to combine two of them (total price or weight). Bring the real objects and your data sheet.","support":"~400 words on class design and the roles of constructor and destructor.","llc":"Lay out the real objects and run your program against them live."},
      {"option_no":3,"title":"The Inheritance Tree of a Real Workplace","primary":"Interview someone at a NAMED shop or office about their staff roles or product categories, then model it in C++ using inheritance and an abstract base class. Bring a photo of the place and your hand-drawn tree.","support":"~400 words on why each inheritance choice matched their real structure.","llc":"Present the tree and defend it under the cohort's 'but what about...' questions."},
      {"option_no":4,"title":"I Traced the Memory by Hand","primary":"Take a real small C++ program using pointers, new/delete and virtual functions. Hand-trace every pointer and memory box on paper across its whole run, then verify against the actual output. Bring the hand-trace sheets.","support":"~400 words on where your mental model was wrong and what corrected it.","llc":"Walk the cohort through your trace and the bug it revealed. AI can write the code; it cannot do YOUR trace."},
      {"option_no":5,"title":"The Record Book That Won't Lose Data","primary":"Collect 15 real records from named consenting people (classmates, a shopkeeper's items). Build a C++ file-based store using templates and exception handling that survives one deliberately bad entry. Bring the file and the real data.","support":"~400 words on the file modes you used and the exceptions you handled.","llc":"Demo live, feed it a bad input in front of the cohort, and show it recover."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCAC02'
  and is_latest = true and is_archived = false;

-- ── 26UCACP01 · bachelor-of-computer-applications ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Foundational Knowledge","task":"Using the variables, I/O and operator programs, feed your program REAL numbers from your life - your actual monthly pocket money and 4 real expenses - and compute the balance.","deliverable_notes":"A running-code screenshot (name and roll in a comment, terminal timestamp visible) plus a hand-written slip of the 5 real amounts and a hand-traced calculation of the balance you did BEFORE running the code. Write 3-4 sentences comparing your hand answer with the program's answer."},
      {"sno":2,"unit":"Lab 3-5","finks_dimension":"Application","task":"Take a REAL word that matters to you - your full name, your town's name (Kavandampatti), a family member's name - and run your string programs to reverse it, check if it is a palindrome, and count each character. Then use a loop to build a number pattern from your date-of-birth digits.","deliverable_notes":"A running-code screenshot on the real inputs plus the real word and DOB written by hand and the pattern output. Write 3-4 sentences on which loop built the pattern and one string method you used."},
      {"sno":3,"unit":"Lab 6-7","finks_dimension":"Integration","task":"Collect ONE real messy list - 20 subject marks from your own marksheets, or 20 item prices with duplicates from a named shop. Use sets and dictionaries to remove duplicates and a list/tuple program to sort the data and find the top 3.","deliverable_notes":"A running-code screenshot plus the real source (a marksheet photo or shop slip with your hand in frame) and the sorted output. Write 3-4 sentences on how a set removed the duplicates and why you used a tuple or a list."},
      {"sno":4,"unit":"Lab 8-10","finks_dimension":"Learning How to Learn","task":"Build the calendar-without-module program for the REAL current month, then deliberately feed your arithmetic GUI or exception program ONE bad input (letters where a number belongs) and make your user-defined exception catch it.","deliverable_notes":"Running-code screenshots of the real month's calendar AND the caught exception message, plus one sentence on the error you first got before you handled it. Write 3-4 sentences on what you learned about failing safely."},
      {"sno":5,"unit":"Lab 11-12","finks_dimension":"Human Dimension","task":"Sit ONE real named person (a friend, a shopkeeper) in front of your GUI calculator or your Flask/Django CRUD form and have them enter one real record or one real sum.","deliverable_notes":"A photo of the real person using it (hand or face in frame, with consent) plus a screenshot of the record saved in MySQL or the result shown, and one quoted sentence from them. Write 3-4 sentences on one thing you fixed after watching a real person struggle with it."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"My Real Month, Built From Scratch","primary":"Build a working Python program (no calendar module) that prints the REAL current month correctly and marks 5 real dates that matter to you - a festival, a birthday, an exam, each verifiable. Bring the offset logic worked out on paper.","support":"~400 words on the loop and day-offset logic.","llc":"Run it live for the current month and let the cohort check a real date against a printed calendar."},
      {"option_no":2,"title":"The CRUD App a Real Person Used","primary":"Build a Flask or Django plus MySQL CRUD app for ONE real small need - a friend's book-lending list, a hostel laundry tally. Have a NAMED person add one real record while you watch, and capture a photo and a quote.","support":"~400 words on the four CRUD operations in your own code.","llc":"Demo live, adding and deleting a real record in front of the cohort."},
      {"option_no":3,"title":"Cleaning My Own Messy Data","primary":"Take a genuinely messy real dataset you own - your marks across terms, a shop's price slips with duplicates and typos. Write Python using sets, dicts, lists and functions to clean, de-duplicate, sort and summarise it. Bring the raw source.","support":"~400 words on each structure's job in your pipeline.","llc":"Show the messy input and the clean output side by side and defend your choices."},
      {"option_no":4,"title":"The Calculator I Watched Someone Break","primary":"Build a Tkinter arithmetic GUI, then hand it to 3 real named people and log every way they broke or got confused by it. Add user-defined exceptions to guard the top 2 failures. Bring your hand-written bug log.","support":"~400 words on the exceptions you added and why.","llc":"Invite a cohort member to try to break it live and show how it now holds."},
      {"option_no":5,"title":"From Hand-Trace to Running Code","primary":"Pick 3 lab programs (a pattern, a GCD, an inheritance demo). For each, hand-trace the full execution on paper FIRST, predict the output, then run and compare. Bring all three hand-traces.","support":"~400 words on where your prediction and reality differed.","llc":"Present one trace where you were wrong and explain what you now understand. AI cannot produce YOUR paper traces."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCACP01'
  and is_latest = true and is_archived = false;

-- ── 26UCACP02 · bachelor-of-computer-applications ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-3","finks_dimension":"Foundational Knowledge","task":"Using the function-overloading, class-and-objects and passing-objects programs, model ONE real object you can hold - your water bottle, your calculator - as a C++ class with real MEASURED attributes (real capacity in ml, real price) and overload one function for two real cases.","deliverable_notes":"A running-code screenshot (your name in a comment) plus a photo of the real object with your ruler or label showing the measurement, and your two overloaded signatures. Write 3-4 sentences on the difference between default arguments and overloading in your program."},
      {"sno":2,"unit":"Lab 4-6","finks_dimension":"Application","task":"Use friend functions and passing-objects to combine data from TWO real objects you own - add the prices of two real books, or compare two real cricket scores you noted down. The values must be real and verifiable.","deliverable_notes":"A running-code screenshot plus the two real objects or values photographed or slipped, and one sentence on why a friend function was allowed to reach inside both objects. Write 3-4 sentences on how the objects were passed to the function."},
      {"sno":3,"unit":"Lab 7-9","finks_dimension":"Integration","task":"Overload the binary + operator to add two real quantities (two real bills, two match scores) and build an inheritance chain for a REAL category you know - base Person to Student and Teacher at your college - using real names.","deliverable_notes":"A running-code screenshot showing the overloaded add on real numbers plus a hand-drawn inheritance tree with the real names, and the real bills or scores you used. Write 3-4 sentences on how operator overloading made the real quantities add naturally."},
      {"sno":4,"unit":"Lab 10-13","finks_dimension":"Human Dimension","task":"Get 8 real records from named consenting classmates (a name plus one number they agree to share). Write them to a text file with your C++ program, read them back sequentially, and pass one real value in through a command-line argument.","deliverable_notes":"The data file with the real records visible plus a running-code screenshot, the exact command line you ran, and a note of who consented. Write 3-4 sentences on the file modes you used and what a command-line argument let a real user control."},
      {"sno":5,"unit":"Lab 14-16","finks_dimension":"Learning How to Learn","task":"Write a class or function template that works for BOTH int and double using real data - integer counts and decimal prices from a named shop - then deliberately feed it one bad value and catch it with exception handling.","deliverable_notes":"A running-code screenshot showing the template working on both the real int and the real double data AND the caught exception, plus one sentence on the error before you handled it. Write 3-4 sentences on why a template saved you from rewriting the same code twice."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"One Real Object, Fully Modelled","primary":"Choose ONE real object you can measure - a bottle, a bat, a lamp. Build a complete C++ class with a constructor, overloaded functions and an operator, all driven by your REAL measurements. Bring the object and your measurement sheet.","support":"~400 words on your class design and the constructor/destructor.","llc":"Place the real object on the table and run your program against its real numbers in front of the cohort."},
      {"option_no":2,"title":"The File That Holds My Classmates","primary":"Collect 10 real records from named consenting classmates. Build a C++ program using files (sequential and random access) and exception handling that stores, searches and safely handles bad input. Bring the file and the consent notes.","support":"~400 words on file modes and the exceptions you handled.","llc":"Demo live - search for a real classmate, feed a bad input, show the recovery."},
      {"option_no":3,"title":"The Family Tree That Compiles","primary":"Map a REAL hierarchy you know - your family, your college staff, a shop's roles - using C++ inheritance (single to multilevel to hybrid) with real names and one virtual function. Bring a hand-drawn tree and be ready to verify the names.","support":"~400 words on binding and virtual functions.","llc":"Present the real tree and defend which inheritance type each level used."},
      {"option_no":4,"title":"One Template, Many Real Types","primary":"Build a class and a function template that solve ONE real task - totalling a bill, finding a maximum - for both whole counts and decimal prices from a NAMED shop. Bring the real price slips.","support":"~400 words on how generics avoided duplicate code and where exceptions guarded bad data.","llc":"Run the same template live on the real ints and real doubles from the slip."},
      {"option_no":5,"title":"I Overloaded the Operator for a Real Bill","primary":"Take two REAL bills or receipts you can show. Build a C++ class where the + operator adds two bill objects into a combined total that matches the real handwritten sum. Bring both receipts.","support":"~400 words on operator overloading and type conversion.","llc":"Hold up the receipts, run the code, and prove the totals match. AI cannot produce YOUR receipts."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCACP02'
  and is_latest = true and is_archived = false;

-- ── 26UCAS01 · bachelor-of-computer-applications ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Note or measure 5 real numbers from ONE real thing - your bicycle (wheel count, tyre pressure, weight if known) or 5 grocery prices from a named shop. Write a C program that declares each with the right data type and constant, and prints one expression that combines them.","deliverable_notes":"A running-code screenshot (your name in a comment) plus a hand-written slip of the 5 real values with the source named, and the one expression you evaluated. Write 3-4 sentences on why you chose int versus float for each value and one operator you used."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Take the REAL marks from your last exam (or a named friend's, with consent) and write a C program using an if-else / else-if ladder to print the grade, plus a loop to count how many subjects were passed.","deliverable_notes":"A running-code screenshot on the real marks plus the real marksheet photo (or a hand-copy with the source named) and the output. Write 3-4 sentences on the branching path your real marks took and which loop counted the passes."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Build a REAL 2D array - your week's class timetable (days by periods), or the temperature you logged for 5 days. Write a C program to store it and compute one row or column total (the busiest day, the hottest day).","deliverable_notes":"A running-code screenshot plus the real timetable or log written by hand and the computed answer. Write 3-4 sentences on how the 2D array mapped onto the real grid and which index moved for rows versus columns."},
      {"sno":4,"unit":"IV","finks_dimension":"Caring","task":"Find ONE real person who needs a small repeated calculation done kindly - a grandparent's daily medicine count, a fair split of a shared auto fare among named friends, a tally for a temple or NGO collection. Write a C function (using arrays or recursion) that does it for them.","deliverable_notes":"A running-code screenshot plus the real names and real numbers, and one sentence from or about the person on why this calculation matters to them. Write 3-4 sentences on how you broke the job into a function and why it mattered to a real person."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"BEFORE compiling, hand-draw on paper how a pointer holds an address and changes a variable through call-by-reference. Then write the C program (swap two real values, e.g. two friends' seat numbers) and compare it with your drawing.","deliverable_notes":"A photo of your hand-drawn pointer-and-address diagram plus a running-code screenshot, and one sentence naming where your drawing was wrong. Write 3-4 sentences on what call-by-reference did that call-by-value could not."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Calculation My Grandparent Does Daily","primary":"Interview ONE named elder (phone-verifiable) about a real daily count they keep - medicines, prayers, coins, measures - and record their voice with consent. Write a C program that reproduces their count using loops or recursion.","support":"~400 words linking their method to your control structures.","llc":"Play their words and run your program against the real count they described. AI can summarise the genre; it cannot interview YOUR elder."},
      {"option_no":2,"title":"My Real Timetable in a Grid","primary":"Encode your college's REAL weekly timetable as a 2D array in C and compute real answers - busiest day, free periods, subject frequency. Bring the official timetable to verify against.","support":"~400 words on array indexing and the loops that scanned rows and columns.","llc":"Show the real timetable, run the code, and answer a cohort member's live query about a real day."},
      {"option_no":3,"title":"A Fair Split, Proven in C","primary":"Take a REAL shared expense among named friends - an auto fare, a group snack bill. Write a C program using functions to split it fairly, handling the leftover rupee. Bring the real bill and the friends' names.","support":"~400 words on functions, call-by-reference and your rounding decision.","llc":"Run it live for the real amount and let the named friends confirm the split is fair."},
      {"option_no":4,"title":"I Drew the Pointer Before I Wrote It","primary":"Pick a real small C task using pointers - swap two real seat numbers, reverse a short real list of names. Hand-draw every address and arrow on paper first, then code it and verify. Bring the hand-drawings.","support":"~400 words on where your mental model of pointers was wrong and what fixed it.","llc":"Walk the cohort through your drawing and the running code together."},
      {"option_no":5,"title":"The Grade Machine for Real Marks","primary":"Collect REAL marks for 5 subjects for 5 named consenting classmates. Write a C program using branching, loops and arrays to compute each grade, the class average and the topper. Bring the real, consented marks.","support":"~400 words on your branching logic and array scans.","llc":"Run it live and let a named classmate verify that their own grade came out right."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCAS01'
  and is_latest = true and is_archived = false;

-- ── 26UCCC01 · b-com-computer-application ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Take ONE month of a real bank passbook or bank-SMS list (yours or a family member's, account number covered) and the same month's cash notebook they actually keep. Sit with both and tick off every entry that matches.","deliverable_notes":"The hand-written Bank Reconciliation Statement you prepared + a photo of the two source records with the account number masked, your hand in frame. Write 3-4 sentences: the biggest difference you found (uncleared cheque, bank charge, ATM entry), what caused it, and the final reconciled balance."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Visit ONE small sole-trader shop you can name (a Kumarapalayam kirana store, a Komarapalayam tea stall, a mobile-recharge shop). Ask the owner for one week's sales, purchases, and three expenses (rent, power, wages).","deliverable_notes":"A hand-drawn Trading and Profit & Loss Account for that week using the shop's real figures + the shop name and owner's first name. Write 3-4 sentences: did the week show a profit, and one adjustment (closing stock, unpaid wage) you had to bring in."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Find ONE real business asset you can photograph — a shop's weighing scale, a tailor's sewing machine, an auto-rickshaw, a mill motor. Ask the owner when it was bought and its cost.","deliverable_notes":"The asset photo (your hand in frame) + a hand-worked depreciation table for 3 years by BOTH the Straight Line and Diminishing Balance methods using its real cost. Write 3-4 sentences on which method fits this asset better and why."},
      {"sno":4,"unit":"IV","finks_dimension":"Learning How to Learn","task":"Find ONE tiny trader who keeps NO proper books — only a rough idea of what he owns and owes (a vegetable seller, a flower vendor at the local market). Note his assets and liabilities at two dates a fortnight apart.","deliverable_notes":"Two hand-made Statements of Affairs (opening and closing) + the vendor's first name and the market. Write 3-4 sentences estimating his profit by the net-worth method and naming the ONE piece of data you wished you had — the real lesson of incomplete records."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Talk to ONE named person who has either received/paid a royalty (a local author, a quarry or land lessor) OR made a fire/theft/flood insurance claim on stock (a shop, a godown). Ask what happened and how the amount was settled.","deliverable_notes":"Your written notes + the person's first name and a phone-verifiable contact (with consent). Write 3-4 sentences: the claim or royalty figure, whether the average clause cut it down, and how they felt about the final settlement."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Shop Whose Books I Balanced","primary":"Adopt ONE real small trader you can name for two weeks and keep their books BY HAND — journal, ledger, trial balance, and a simple Trading, P&L and Balance Sheet. Bring the actual bills and notebook you worked from.","support":"~400 words linking your entries to Units I-II and one error you rectified.","llc":"Show the trial balance to the cohort and defend one rectification and the closing stock adjustment. ChatGPT cannot keep YOUR trader's real books."},
      {"option_no":2,"title":"What My Grandparent's Ledger Taught Me","primary":"Interview ONE named elder who kept accounts by hand before computers — a retired shopkeeper, a temple hundial keeper, a chit-fund runner. Record their voice with consent, get a phone-verifiable contact, and photograph one page of their old book.","support":"~400 words connecting their method to double-entry and the trial balance.","llc":"Play or read their words and tell the cohort what their hand-knowledge holds that software does not."},
      {"option_no":3,"title":"One Machine, Two Depreciation Stories","primary":"Choose ONE real named asset you can measure and photograph — a sewing machine, mill motor, auto. Get its real cost and age, then compute its book value over 3 years by both Straight Line and Diminishing Balance. Bring the asset or its photo and your full workings.","support":"~400 words on which method the owner should use.","llc":"Show the two curves and defend your recommendation under questioning."},
      {"option_no":4,"title":"Profit Without Books","primary":"Find ONE real trader who keeps incomplete records (a vendor, a small eatery). Over three weeks, reconstruct their profit by both the Statement of Affairs and, where possible, the conversion method. Bring your dated statements and notes.","support":"~400 words on the limitations of single entry you hit in practice.","llc":"Present the two profit figures and explain why they differ."},
      {"option_no":5,"title":"The Claim That the Average Clause Cut","primary":"Find ONE real insurance stock-loss story — a shop, godown or home that filed a fire/theft/flood claim. Interview the claimant (named, consented, contactable) and reconstruct the claim with the average clause arithmetic.","support":"~400 words on how under-insurance reduced the payout.","llc":"Present the numbers and the human story of the loss and settlement to the cohort."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCCC01'
  and is_latest = true and is_archived = false;

-- ── 26UCCC02 · b-com-computer-application ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Visit ONE workplace you can name (a supermarket, a rice mill, a clinic, a bank branch) and find out who sits at each of the three levels of management — top, middle, supervisory.","deliverable_notes":"A hand-drawn three-level pyramid with the REAL job titles (and first names where you can get them) at each level + the workplace name. Write 3-4 sentences on which management function — planning, organising, or controlling — you actually saw one of those people doing."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Pick ONE real task happening in the next month (a family function, a class event, restocking a shop) and write a plan for it using the planning steps — objective, alternatives, chosen course, schedule.","deliverable_notes":"The hand-written one-page plan + the real task named. Write 3-4 sentences describing one decision you had to make between two alternatives and why you chose one — your decision-making step in action."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Choose ONE real organisation you can access (your college department, a shop chain, a bank branch, an SHG federation) and map who reports to whom.","deliverable_notes":"A hand-drawn organisation chart with real designations + a label saying whether it is line/functional and centralised/decentralised. Write 3-4 sentences on the span of management you saw — how many people one boss actually handles — and whether it looked workable."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Interview ONE named working person about how they were recruited into their job and how their performance is judged today.","deliverable_notes":"Your notes + the person's first name, job, and a phone-verifiable contact (with consent). Write 3-4 sentences comparing the recruitment source they came through (advertisement, referral, campus, walk-in) with one thing they told you about their appraisal."},
      {"sno":5,"unit":"V","finks_dimension":"Caring","task":"Sit with ONE named worker or a woman who leads a team (a self-help-group leader, a shop supervisor, a panchayat ward member) and ask what keeps them going at work and what holds them back.","deliverable_notes":"Their words quoted in their own language + their first name and contact (with consent). Write 3-4 sentences linking what they said to one motivation theory, and — if it is a woman leader — one workforce challenge she named."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Real Manager for a Day","primary":"Shadow ONE named manager of a real local business for a few hours and record, minute by minute, the management functions you watch them perform. Bring your timed observation sheet and one photo (with consent).","support":"~400 words mapping what you saw to planning, organising, staffing, directing and controlling.","llc":"Present your timeline and defend which function dominated their day. AI cannot watch YOUR manager's real hours."},
      {"option_no":2,"title":"The Leader Nobody Wrote About","primary":"Interview ONE named local leader who is not in any textbook — an SHG head, a panchayat member, a small-business owner, a temple committee lead. Record their voice with consent and get a phone-verifiable contact.","support":"~400 words matching their style to a leadership theory.","llc":"Play their words and tell the cohort what kind of leader they are and why."},
      {"option_no":3,"title":"The Org Chart I Drew From Life","primary":"Pick ONE real organisation and map its full structure — every level, department, and reporting line — from firsthand access, not a website. Bring your hand-drawn chart signed by someone inside.","support":"~400 words on its type, centralisation, and span of management.","llc":"Present the chart and defend one thing you would restructure and why."},
      {"option_no":4,"title":"How This Shop Hires","primary":"Study ONE real business's full staffing cycle — how they source, select, train, and appraise people — by interviewing the owner or manager (named, consented, contactable). Bring the recruitment notice or form they use.","support":"~400 words on their staffing process versus the textbook steps.","llc":"Present their real hiring story and where it departs from theory."},
      {"option_no":5,"title":"What Actually Motivates the People Who Serve Me","primary":"Interview three named frontline workers you meet weekly (a bus conductor, a canteen cook, a delivery rider) about what motivates them. Record consented voice notes and contacts.","support":"~400 words testing their answers against Maslow/Herzberg and one motivation myth you had.","llc":"Play one voice clip and present what really moves the people around you."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCCC02'
  and is_latest = true and is_archived = false;

-- ── 26UCCC03 · b-com-computer-application ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Find ONE real thing bought on hire-purchase or EMI that you can see — a two-wheeler, fridge, smartphone, sewing machine. Get the cash price, down payment, number of instalments and instalment amount from the buyer or the bill.","deliverable_notes":"A hand-worked table showing the total interest and how it splits across the instalments + a photo of the item or its EMI bill (figures visible, name masked). Write 3-4 sentences on how much extra was paid over the cash price and whether it was worth it."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Visit ONE shop with two or more clear sections (a supermarket with grocery + cosmetics, a textile shop with sarees + readymades). Ask roughly what each section sells and one shared expense such as rent or power.","deliverable_notes":"A hand-made departmental income statement that splits the shared expense on a fair basis (floor area or sales) + the shop name. Write 3-4 sentences on which section earns more and whether your basis of allocation was fair to both."},
      {"sno":3,"unit":"III","finks_dimension":"Human Dimension","task":"Find ONE real partnership business you can name (a two-brother provision store, a partner-run coaching centre, a small workshop). Ask how they share profit and what they would do if a new partner joined or one left.","deliverable_notes":"Your notes on their profit-sharing ratio + the partners' first names and a contact (with consent). Write 3-4 sentences on how they would value goodwill on an admission or retirement — even the rough way they described it."},
      {"sno":4,"unit":"IV","finks_dimension":"Caring","task":"Talk to ONE named person who has seen a partnership, firm, or chit-fund wind up or a partner default. Ask who got paid first and who lost money.","deliverable_notes":"Your written account + the person's first name and contact (with consent). Write 3-4 sentences linking what you heard to the dissolution order of payment (outside creditors first) and why the Garner vs Murray idea of protecting the solvent partner is about fairness."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Pick ONE Indian company you know (a listed bank, an FMCG brand, a cement or auto firm) and open its latest annual report online. Find the note that says which accounting standards (Ind AS) it follows.","deliverable_notes":"A screenshot or copied line naming the standard and the report year + the company name. Write 3-4 sentences, in your own words, on one difference between Ind AS and IFRS you found and how you would keep learning as these standards change."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The EMI That Cost More Than Cash","primary":"Take ONE real named purchase bought on hire-purchase/EMI — get the actual bill or loan schedule (name masked). Rebuild the full interest calculation and hire-purchase entries by hand and bring the document.","support":"~400 words on the true cost of buying on instalments for this buyer.","llc":"Show the bill and your workings and defend the total extra paid. AI cannot reconstruct YOUR neighbour's real EMI schedule."},
      {"option_no":2,"title":"Two Partners, One Handshake","primary":"Interview a REAL partnership firm you can name about how they split profit, value goodwill, and would settle a retirement. Record consented voice and a phone-verifiable contact.","support":"~400 words on their goodwill and profit-sharing versus the textbook treatment.","llc":"Play their words and present how you would draft their admission/retirement entries."},
      {"option_no":3,"title":"The Department That Carried the Shop","primary":"Study ONE real multi-section shop and build its departmental accounts from figures the owner gives you, splitting shared costs on a defensible basis. Bring the shop name and your allocation workings.","support":"~400 words on which section subsidises which and whether inter-departmental transfers happen.","llc":"Present the department-wise profit and defend your basis of allocation."},
      {"option_no":4,"title":"When a Firm Comes Apart","primary":"Find ONE real dissolution, default, or wind-up story near you and interview someone who lived it (named, consented, contactable). Reconstruct the order of settlement and any insolvency treatment.","support":"~400 words on realisation and the Garner vs Murray fairness rule as it played out.","llc":"Present the human story and the settlement order to the cohort."},
      {"option_no":5,"title":"Reading a Real Company's Standards","primary":"Take ONE real company's latest annual report AND ask a named commerce lecturer or practising accountant one question about Ind AS adoption (consented, contactable). Bring the annual-report note and your interview record.","support":"~400 words decoding the Ind AS vs IFRS gap for that company.","llc":"Present the report's standards note and what the expert told you."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCCC03'
  and is_latest = true and is_archived = false;

-- ── 26UCCC04 · b-com-computer-application ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Get ONE real everyday agreement you can hold — a mobile SIM form, a rental agreement, a warranty card, a gym membership slip. Read it against the six essentials of a valid contract.","deliverable_notes":"The document (or a photo, personal details masked) + a hand-written checklist ticking which essentials you can spot — offer, acceptance, consideration, capacity, free consent, lawful object. Write 3-4 sentences on the one essential that was hardest to find in the paper."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Find ONE real case where a deal was broken near you — an undelivered online order, a tailor who missed a wedding deadline, a cancelled hall booking. Ask the affected person what they did.","deliverable_notes":"Your written account + the person's first name and contact (with consent). Write 3-4 sentences naming the remedy they used or could have used (damages, refund, specific performance, cancellation) and whether the contract was legally discharged."},
      {"sno":3,"unit":"III","finks_dimension":"Human Dimension","task":"Talk to ONE named person who has stood guarantee for someone — a loan guarantor, someone who signed as surety for a job, a rental co-signer. Ask why they agreed and what risk they carry.","deliverable_notes":"Their words quoted + their first name and contact (with consent). Write 3-4 sentences on the extent of the surety's liability they described and whether they knew the ways a surety can be discharged."},
      {"sno":4,"unit":"IV","finks_dimension":"Caring","task":"Visit or talk to ONE named pawnbroker OR a gold-loan borrower (a Muthoot/Manappuram branch, a local pledge shop). Ask how the pledged item is stored and returned and what happens on default.","deliverable_notes":"Your notes + the shop or person's name. Write 3-4 sentences on the rights of the pawner and the pawnee you observed and one way the borrower is protected — or left exposed — in a pledge."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Buy or examine ONE real purchase that has a bill (a phone, a pressure cooker, cloth by the metre). Read the bill and any warranty for conditions versus warranties.","deliverable_notes":"The bill + a hand-written note separating one CONDITION from one WARRANTY in that sale and stating when ownership (property) passed. Write 3-4 sentences on what the unpaid-seller's rights would be if you had not paid."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Contract in My Pocket","primary":"Take ONE real agreement you personally signed or hold (details masked) and dissect all six essentials of a valid contract against its actual clauses. Bring the physical document.","support":"~400 words on which clauses protect you and which favour the other party.","llc":"Show the document and walk the cohort through where each essential lives in it. AI cannot read YOUR specific signed paper."},
      {"option_no":2,"title":"The Person Who Signed as Surety","primary":"Interview ONE named person who has actually stood guarantee for a loan, job, or lease. Record consented voice and a phone-verifiable contact.","support":"~400 words on the surety's liability and discharge rules as they apply to that person's real exposure.","llc":"Play their words and present what you would warn a future guarantor about."},
      {"option_no":3,"title":"Behind the Pawnshop Counter","primary":"Study ONE real pledge or gold-loan transaction — interview a named pawnbroker or borrower about storage, interest, default, and return. Bring the pledge receipt format (details masked).","support":"~400 words on pawner and pawnee rights and where the vulnerable borrower stands.","llc":"Present the real terms and one reform you would suggest for fairness."},
      {"option_no":4,"title":"The Deal That Broke","primary":"Find ONE real breach-of-contract case near you and interview the affected party (named, consented, contactable). Reconstruct the breach, the remedy pursued, and how the contract ended.","support":"~400 words on the remedies available under the Contract Act for that case.","llc":"Present the story and defend which remedy was best."},
      {"option_no":5,"title":"One Bill, The Whole Sale of Goods Act","primary":"Take ONE real purchase bill and use it to trace every Sale of Goods concept — conditions, warranties, transfer of property, and unpaid-seller rights. Bring the actual bill and warranty.","support":"~400 words applying each provision to that transaction.","llc":"Hold up the bill and show the cohort where the Act lives inside an everyday purchase."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCCC04'
  and is_latest = true and is_archived = false;

