update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Human Dimension","task":"Talk to ONE real business owner near you — a named shop, workshop, tea-stall — about why they started and what responsibility they feel to customers.","deliverable_notes":"The name of the business + owner + one ethical choice they described, in their words. Two sentences max. Bring a photo of the shopfront."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Point at ONE sole trader, ONE partnership, ONE company you actually pass daily (a named vendor, a two-partner workshop, a branded store).","deliverable_notes":"The three named businesses + one observed advantage/limitation of each. A photo of each shopfront is stronger than prose."},
