update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Word Tasks 1-2","finks_dimension":"Foundational Knowledge","task":"Do Word Tasks 1 and 2 with YOUR real content — make a project certificate for a real event you attended, and type your own one-page bio-data as the abstract document.","deliverable_notes":"The printed or PDF certificate and bio-data + a screenshot showing you used drop cap, header/footer, a table, and track changes. Write 3-4 sentences naming which two features were hardest and exactly where you would use each document in real life."},
      {"sno":2,"unit":"Word Task 3","finks_dimension":"Caring","task":"Make a ONE-page newsletter about a REAL person or cause in your community worth celebrating — a hard-working teacher, a self-help group, a clean-up drive. Use your own photos and words.","deliverable_notes":"The newsletter file with newspaper columns, a real photo, and a WordArt title + the person or cause named. Write 3-4 sentences on why you chose them and which layout features (columns, textbox, table of contents) you used to give them dignity on the page."},
      {"sno":3,"unit":"Excel Tasks 1-2","finks_dimension":"Application","task":"Build an Excel scheduler and a calculation sheet on YOUR real data — your weekly class timetable, and your real monthly pocket-money and expense figures. Use SUM, AVERAGE, and a chart.","deliverable_notes":"A screenshot of both sheets with your real numbers, the average, and one chart. Write 3-4 sentences on what the chart of your spending revealed and one formula (VLOOKUP or COUNT) you used and why."},
      {"sno":4,"unit":"Excel Task 3","finks_dimension":"Integration","task":"Take a REAL small dataset you can collect — your lab batch's marks or heights, or a shop's week of daily sales — and run a performance analysis with sorting, conditional formatting to flag highs and lows, and freeze panes.","deliverable_notes":"A screenshot showing the sorted, conditionally-formatted sheet + where the data came from. Write 3-4 sentences on the top and bottom of the data and how conditional formatting let you see the pattern faster than reading the raw numbers."},
      {"sno":5,"unit":"PowerPoint Tasks 1-3","finks_dimension":"Human Dimension","task":"Build a 5-slide PowerPoint about YOURSELF — your background, your goals, and why you chose B.Com Computer Application — using slide layouts, a real photo of yourself, one animation and one transition.","deliverable_notes":"The .pptx file + a screenshot of the slide-master or animation view. Write 3-4 sentences on the one design choice (colour, animation, layout) you made to hold attention and which slide you are most nervous to present live."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Document Kit for a Real Event","primary":"Pick ONE real upcoming event — a family function, a college fest, an SHG meeting — and produce its full document kit: a Word invitation/certificate, an Excel budget with working formulas, and a PowerPoint deck — all with real names, dates, figures, and your own photos. Demo the files live.","support":"~400 words on your choices.","llc":"Open the files and show one formula and one animation working. AI cannot make YOUR event's real kit with YOUR photos."},
      {"option_no":2,"title":"My Family Budget, In Excel","primary":"Build a real, working monthly budget of your own household in Excel — real income and expense heads, live formulas, a chart, and conditional formatting. Bring the file.","support":"~400 words on what the numbers revealed about your household's money.","llc":"Open the sheet, change one real figure, and show every dependent total and the chart updating live."},
      {"option_no":3,"title":"The Newsletter That Honoured Someone Real","primary":"Make a community newsletter in Word about ONE named real person or cause, using your own photos and interview. Bring the printed newsletter.","support":"~400 words on the story behind them and the layout choices you made.","llc":"Present the newsletter and tell the cohort why that person deserved a page. AI cannot photograph or interview YOUR real subject."},
      {"option_no":4,"title":"Presenting Me","primary":"Build and DELIVER a self-introduction PowerPoint to the cohort — your real background, goals, and a real photo, with master layouts, transitions, and animation. Bring the .pptx.","support":"~400 words on your design and delivery choices.","llc":"Present it live to the cohort and faculty and take questions on both your content and your slide design."},
      {"option_no":5,"title":"The Formula I Can Explain","primary":"Take ONE real Excel sheet you built (marks, sales, or budget) and prove you own every formula by rebuilding any of them live when the faculty changes a value. Bring the file.","support":"~400 words explaining VLOOKUP, AVERAGE, and conditional formatting in your own words.","llc":"The faculty edits a cell and you explain and, if needed, repair the formula chain live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCSGEP05'
  and is_latest = true and is_archived = false;

-- ── 26UCSS01 · b-sc-computer-science ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Find a REAL computer you can access — at home, the college lab, or a named cyber cafe in Kavandampatti/Erode. Open the case OR the System Information screen and identify the real parts: the actual CPU, the RAM size, one input device and one output device in front of you.","deliverable_notes":"A photo of the real machine (its System-info screen or opened case) with a hand-labelled sketch naming the CPU, memory and one input/output device. 3-4 sentences: the real processor and RAM you found, whether it is a PC/workstation, and one real limitation you noticed (slow, low storage)."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Pick a REAL everyday process you do — making filter coffee, catching the 8am bus, or withdrawing money at a named ATM. Write its algorithm as numbered steps AND draw the flowchart BY HAND using proper symbols (start/end, process box, decision diamond).","deliverable_notes":"The hand-drawn flowchart of YOUR real process (with at least one decision diamond) plus the numbered algorithm. 3-4 sentences: where the flow branches on a decision, one place it loops back, and one edge case (the bus is late) that your flowchart handles."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Find a REAL rule needing BOTH a decision and repetition — grading a stack of real answer sheets (loop plus pass/fail), sorting real coins by value, or checking a real name list against a condition. Write pseudocode combining a loop with relational/logical operators.","deliverable_notes":"The hand-written pseudocode, a photo of the real items you looped over (answer sheets, coins, list), and a filled trace table for 4 real inputs. 3-4 sentences: the loop condition, the relational operator you used, and one input where two conditions combined with AND/OR."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Collect a REAL 2D grid of data about people or places you know — your class's weekly timetable (days x periods), a real seating chart, or 5 classmates x 3 subjects' marks. Represent it as a 2D array on paper and write pseudocode to read one cell and one whole row.","deliverable_notes":"The hand-drawn 2D array filled with REAL data (name the source), plus pseudocode accessing array[row][col]. 3-4 sentences: what a row means and what a column means in your grid, and one real question your array answers (who has maths on Monday)."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Pick a REAL system you interact with — your college's fee/admission process, a shop's billing, or hostel mess coupons. Based on what you actually observed or asked, draw a Level-0 Data Flow Diagram: the external entity, the process, a data store, and the data flows between them.","deliverable_notes":"The hand-drawn DFD with real named entities, plus a one-line note of who you asked or observed. 3-4 sentences: name one data store and one data flow, and point out where a reusable module or subprogram would fit in the system."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Algorithm Behind a Real Chore","primary":"Take one real daily chore and fully specify it — algorithm, hand-drawn flowchart, pseudocode, and a trace table on real inputs. Then have a named classmate follow YOUR flowchart exactly and record every point where it breaks or is unclear.","support":"~400 words on what the test exposed and how you fixed the logic.","llc":"Show the flowchart and report where your tester got stuck. AI cannot have YOUR classmate walk your steps."},
      {"option_no":2,"title":"How My Town's System Really Works","primary":"Interview a NAMED person running a real process — shop billing, ration distribution, bus scheduling (phone-verifiable). From what they tell you, draw the DFD and identify the modules and data stores.","support":"~400 words linking their real workflow to the concepts.","llc":"Quote the person and present the DFD to the cohort. AI can invent a generic diagram; it cannot interview YOUR named operator."},
      {"option_no":3,"title":"The Machine on My Desk","primary":"Open or examine a real computer you can access, document its true parts and specs (photograph the System-info or the opened case), and explain the hardware-to-software-to-language-to-translator chain for THAT specific machine.","support":"~400 words connecting the real specs to what the machine can and cannot do.","llc":"Show your photos and walk the cohort through your machine's chain. AI cannot see YOUR actual computer."},
      {"option_no":4,"title":"Decision and Repetition, By Hand","primary":"Find a real rule that needs loops plus conditions (grading, coin-sorting, eligibility checking), build the full pseudocode, and trace it on real inputs you collected — bring the physical items.","support":"~400 words defending your edge cases and where AND/OR mattered.","llc":"Run your trace table live on a fresh input the cohort supplies. AI cannot sort YOUR real coins or grade YOUR real sheets."},
      {"option_no":5,"title":"My Data in a Grid","primary":"Collect a real 2D dataset about your cohort (timetable, marks grid, seating), model it as a 2D array, and write the access logic to answer real questions. Bring the collected grid.","support":"~400 words on how rows and columns mapped to reality and one query that was awkward.","llc":"Answer live questions from the cohort using your array logic. AI cannot collect YOUR cohort's real grid."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCSS01'
  and is_latest = true and is_archived = false;

-- ── 26UCYC01 · b-sc-computer-science-cyber-security ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Type and compile your FIRST C program yourself on a lab machine: read real facts about your own family — how many members, and each person's age — then print the total and the average age.","deliverable_notes":"A photo of YOUR program running on screen with your real family numbers visible, plus the output copied by hand. Write 3-4 sentences naming which data types you used (int for count, float for average) and why, and one compile error you fixed."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Write a C program that stores the marks YOU actually scored in your last 5 school or college tests in an array, then uses a loop and an if to count how many you passed (>= 40) and print the highest.","deliverable_notes":"A photo of the running program with your real marks on screen, plus the hand-drawn flowchart you made BEFORE coding. Write 2-3 sentences on what the loop did each pass and what the if checked."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Write a C program with your OWN function that computes a real amount — e.g. bill(units) using the real slab rates on your family's latest TNEB electricity bill, or fare(distance) using real town-bus slabs.","deliverable_notes":"A photo of the program computing the amount, placed next to the REAL bill/ticket, plus a line comparing your program's output to the real printed amount. Write 2-3 sentences naming the function's parameter and its return value."},
      {"sno":4,"unit":"IV","finks_dimension":"Integration","task":"Design a C struct for a real thing you can physically hold — a book from your bag (title, pages, price), a grocery packet (name, weight, MRP, expiry), or a bus ticket. Enter 5 REAL ones you collected.","deliverable_notes":"A photo of the 5 real objects/labels/tickets you used, plus a photo of your program printing their struct data. Write 2-3 sentences on why one struct fits these better than 4 separate parallel arrays."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Write a C program that saves a real list you care about — your class phone directory, your book list, or a month of your expenses — to a file, then reopens the file and displays it back.","deliverable_notes":"A photo of the program running, plus the actual data file it created opened in a text editor (screenshot). Write 3-4 sentences: what a file pointer is in your own words, and one thing about pointers/files that confused you and how you worked it out."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Bill My Program Checks","primary":"Pick a real paper bill you can bring — your family's EB, water, phone, or a shop credit slip. Build a C program (functions + arrays + if/loop) that reproduces its total from the actual slab rates.","support":"~400 words on your data types, function design and how you validated it.","llc":"Run it live and let the audience change one input (units used) while you defend that the new total is correct against the printed rules."},
      {"option_no":2,"title":"A Record for a Real Register","primary":"Borrow ONE real handwritten register (a shop's credit book, an SHG savings sheet, a mess headcount) with consent. Build a C program using structs + file I/O to store and retrieve its entries. Bring the original.","support":"~400 words on your struct fields and the create/read/modify file operations.","llc":"Enter one live record from the audience and read it back from the file, naming the register's real keeper."},
      {"option_no":3,"title":"The Program That Counts My Street","primary":"Walk one real street or your own colony and count something by hand — houses, shops, two-wheelers, or trees. Write a C program (arrays + loops + a function) that computes real statistics (total, average, max) on YOUR count.","support":"~400 words connecting the code to the walk.","llc":"Show the hand-count sheet and defend one number your program produced under a changed input."},
      {"option_no":4,"title":"Teaching C to a Classmate","primary":"Teach ONE named classmate to write and run a single C program from scratch. Keep a handwritten log of the exact errors they hit and how you helped fix each. Both of you demo the final program.","support":"~400 words on the concepts (data types, I/O, if/loop) the errors revealed.","llc":"Name your classmate, show the error log, and explain the one mistake that taught you the most."},
      {"option_no":5,"title":"My First Useful Tool","primary":"Find ONE real repetitive calculation a named family member does by hand — loan interest, tailoring measurements, recipe scaling, daily shop totals. Build a C program that does it, and have that person test it on their own numbers and sign/approve.","support":"~400 words on the function and control structures used.","llc":"Run it on the person's real numbers live and defend the output against how they do it by hand."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCYC01'
  and is_latest = true and is_archived = false;

-- ── 26UCYC02 · b-sc-computer-science-cyber-security ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Stand in ONE real queue (college canteen, bank, temple darshan line, bus stop) and watch how it moves. Then find ONE real stack (plates at the mess, a pile of your notebooks, stacked bricks).","deliverable_notes":"A photo of the real queue AND the real stack (you in frame), plus a hand-drawn diagram marking front/rear (enqueue/dequeue) on the queue and top (push/pop) on the stack. Write 3-4 sentences on why one is FIFO and the other LIFO, using what you saw."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Draw your REAL family tree across 3 generations using real names, as a tree data structure. Then draw a graph of the real road/bus links between 5 named places near you (e.g. Kavandampatti, Salem, Erode, your village, your college).","deliverable_notes":"The hand-drawn tree (real names, parent→child edges) AND the hand-drawn graph (real places as nodes, roads as edges with rough distances). Write 2-3 sentences on the difference between a tree and a graph using YOUR two examples."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Take a real physical set to sort — paper slips with 20 classmates' roll numbers, or 15 grocery items by price. Sort them BY HAND using bubble or selection sort, counting your swaps. Then write the same sort in Python.","deliverable_notes":"A photo of your slips mid-sort, your hand-count of swaps/comparisons, and a screenshot of your Python program sorting the SAME data. Write 2-3 sentences comparing your hand-count to what the code reported."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Model ONE real 'limited capacity, pick the best' choice from your life — packing a trip bag under a weight limit, spending a fixed ₹200 on maximum-value snacks, or fitting subjects into limited study hours. List the real items with real weights/values.","deliverable_notes":"Your real item list with weights and values, your hand-worked greedy solution, and a Python knapsack/greedy program run on the SAME data. Write 2-3 sentences on whether greedy gave the best answer or missed a better mix."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Find ONE real 'try, fail, back up, try again' situation — seating real named relatives so feuding pairs don't clash (graph colouring), or a route that visits 5 real shops once and returns home (TSP/Hamiltonian). Solve it by hand, showing one dead-end you backtracked from.","deliverable_notes":"Your hand-worked attempt with a crossed-out dead-end and the backtrack step visible, plus the real constraint named (people/places). Write 3-4 sentences: what backtracking means in your own words and where exactly you got stuck."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Queue I Timed","primary":"With a stopwatch, measure ONE real queue (canteen, bank, temple, bus stop) for 20 minutes — record arrival times, service times and line length on a timestamped sheet. Implement it as a Queue ADT in Python and replay your data.","support":"~400 words on FIFO behaviour, enqueue/dequeue and what your numbers showed.","llc":"Show the timestamped sheet and run the queue live for the cohort."},
      {"option_no":2,"title":"My Village as a Graph","primary":"Map 8-10 real named places near you as a graph, with real distances you measured, walked, or read off signboards. Implement shortest-path (Dijkstra/Floyd) in Python and verify ONE computed route against the real road.","support":"~400 words on graph representation and the traversal.","llc":"Show the map, name the places, and defend the route the code chose versus the one locals actually take."},
      {"option_no":3,"title":"Sorting Something Real, Two Ways","primary":"Collect a real dataset of 15+ named people (test marks, cricket scores, heights you measured). Sort it in Python with TWO algorithms and count operations on the SAME data.","support":"~400 words comparing the two methods' behaviour and complexity on your real numbers.","llc":"Show the raw data, name the people, and defend which sort you'd use for a class of 500 and why."},
      {"option_no":4,"title":"The Family Tree That Runs","primary":"Build your real 3-generation family tree (real names) as a Python tree with insert and traversal (pre/in/post-order). Have a NAMED elder verify the names and relationships (phone-verifiable, with consent).","support":"~400 words on tree structure and what each traversal order printed.","llc":"Run a traversal live and explain which real relative each node is."},
      {"option_no":5,"title":"The Best Choice Under a Limit","primary":"Take ONE real constrained decision with real items, weights and values (trip packing, a fixed budget, study hours vs subjects). Solve it BY HAND greedily, then in Python.","support":"~400 words on the greedy method and whether it was optimal for your case (Unit IV).","llc":"Present the real items, show both solutions, and defend whether greedy was safe here or would fail on a tweaked set."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCYC02'
  and is_latest = true and is_archived = false;

-- ── 26UCYCP01 · b-sc-computer-science-cyber-security ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Foundational Knowledge","task":"Write and run a C program that reads a real classmate's name and age with scanf and prints whether they can vote (>= 18) using if/else. Test it with 3 REAL classmates' actual ages.","deliverable_notes":"A photo of the program running on the lab machine for all 3 real classmates (their names visible on screen), plus the hand-copied outputs. Write 2 sentences on the condition you used and one input where the answer flipped."},
      {"sno":2,"unit":"Lab 3-4","finks_dimension":"Application","task":"Write a C program that takes 5 REAL numbers you collected (your last 5 phone-recharge amounts, or 5 classmates' heights you measured) into an array, then finds the max, min and average.","deliverable_notes":"The real data written down, a photo of the program running on that data, and the hand-copied output. Write 2 sentences on how your loop 'walked' the array to find the maximum."},
      {"sno":3,"unit":"Lab 5-6","finks_dimension":"Application","task":"Write a C program with your OWN function that takes a real name (yours or a classmate's) as a string and does one real job — count vowels, reverse it, or check if it is a palindrome. Run it on 3 real names.","deliverable_notes":"A photo of the program running on the 3 real names, plus the outputs. Write 2 sentences on what your string function received and returned."},
      {"sno":4,"unit":"Lab 7-8","finks_dimension":"Integration","task":"Write a recursive C function for a real counting problem — factorial for the number of ways to line up your 5 family members for a photo (5!), or the sum of a real series. Also write a small pointer program that swaps two real values.","deliverable_notes":"A photo of BOTH programs running with your real numbers, plus the hand-copied output. Write 3 sentences: how the recursive function called itself, and what the pointer actually pointed to."},
      {"sno":5,"unit":"Lab 9-10","finks_dimension":"Learning How to Learn","task":"Write a C program using a struct to store 5 REAL items (books in your bag, groceries with MRP, or classmate details), SAVE them to a file, then read the file back and display them.","deliverable_notes":"A photo of the 5 real items, a photo of the program running, and the actual data file it created (opened in an editor). Write 2 sentences on the struct fields and the file operations, and one bug you fixed while getting the file to save."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"One Real Tool, Fully Working","primary":"Build ONE complete C program that solves a real problem for a NAMED person — a shopkeeper's daily total, a family's split-bill, a hostel-mess headcount — using I/O + arrays + a function + file storage. That person tests it on their real inputs.","support":"~400 words on how the pieces fit and how you tested it.","llc":"Run it live, name the person it helps, and take one changed input from the audience."},
      {"option_no":2,"title":"My Program's Error Diary","primary":"While building ONE real C program, keep a handwritten diary of EVERY compile and runtime error you hit and exactly how you fixed each. Bring the diary and the final working program.","support":"~400 words grouping your errors by cause (syntax, type, logic) and what each taught you.","llc":"Show the diary in your handwriting and demo the program that survived them. Your real error trail is something AI cannot invent."},
      {"option_no":3,"title":"The Register in C","primary":"Borrow ONE real handwritten register (temple donations, SHG savings, milk record) with consent and digitize it into a C struct + file program. Bring the original register.","support":"~400 words on your struct design and the create/read/modify operations.","llc":"Show the real register, name its keeper, enter one live entry and read it back from the file."},
      {"option_no":4,"title":"Names I Processed","primary":"Collect 15 real classmate names on paper, then build a C string-processing tool that sorts them alphabetically, counts them by first letter, and searches for one.","support":"~400 words on string handling, arrays and the function you wrote.","llc":"Show the paper list of real names and run a live search the audience picks. AI cannot know YOUR 15 classmates."},
      {"option_no":5,"title":"The Recursion I Can Show","primary":"Pick a real nested or repeating physical thing — a rangoli pattern, a stack of ladoos, a family lineage, a nested set of boxes — and write a recursive C program that models or counts it. Bring the object or a clear photo.","support":"~400 words on the base case and recursive case tied to your real object.","llc":"Hold up the object and trace how the recursion unwinds."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCYCP01'
  and is_latest = true and is_archived = false;

-- ── 26UCYCP02 · b-sc-computer-science-cyber-security ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Foundational Knowledge","task":"Implement a stack and a queue in Python. Model a REAL stack (your notebooks piled on the desk) and a REAL queue (the canteen line you actually stood in). Push/pop your real notebook titles; enqueue/dequeue real classmate names in the exact order they lined up.","deliverable_notes":"A photo of the real pile AND the real line, plus a screenshot of your Python stack and queue running with that real data. Write 2-3 sentences on FIFO vs LIFO from what you observed in the line and the pile."},
      {"sno":2,"unit":"Lab 3-5","finks_dimension":"Application","task":"Build a real tree (your family or a real club/class org chart) and traverse it in Python. Then take a real list (your class attendance register, 20 real roll numbers) and run BOTH linear and binary search to find one real classmate.","deliverable_notes":"A photo or sketch of the real tree, a screenshot of the traversal output, and screenshots of both searches finding the real roll number. Write 2-3 sentences on why binary search needed the roll numbers sorted first."},
      {"sno":3,"unit":"Lab 6-8","finks_dimension":"Application","task":"Take ONE real dataset (marks of 15 named classmates, or prices at your kirana shop) and sort it three ways in Python — merge sort, quick sort, selection sort.","deliverable_notes":"The real data written down, plus screenshots of all three sorts producing the SAME sorted order, and your note of which felt fastest. Write 2-3 sentences on why the outputs match but the methods differ."},
      {"sno":4,"unit":"Lab 9-11","finks_dimension":"Integration","task":"Model ONE real optimization: pack a real bag under a weight limit (knapsack) with real item weights/values, OR find the shortest route between 5 real named places (all-pairs / TSP) with real distances.","deliverable_notes":"The real items/places with real numbers, a screenshot of the Python program's answer, and a hand-check of one choice/route against reality. Write 3 sentences on what 'optimal' meant in your case and whether the code agreed with your intuition."},
      {"sno":5,"unit":"Lab 12-13","finks_dimension":"Learning How to Learn","task":"Solve ONE real placement/routing puzzle with backtracking — seat real named relatives so feuding pairs don't clash, or plan a route visiting 5 real shops once. Run the N-Queen or Hamiltonian-cycle Python program, then map its logic onto your real puzzle.","deliverable_notes":"Your hand-worked real puzzle showing at least one backtrack (a crossed-out dead-end), plus a screenshot of the program running. Write 3-4 sentences: what backtracking does when it hits a dead end, in your own words, tied to your real puzzle."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Queue I Measured, Coded, and Defended","primary":"With a stopwatch, time ONE real queue (canteen, bank, temple) for 20 minutes — record arrival times, service times and line length on a timestamped sheet. Implement it as a queue in Python and replay your real data.","support":"~400 words on the queue ADT and what your measurements revealed.","llc":"Show the timestamped sheet and run the code live for the cohort."},
      {"option_no":2,"title":"Sorting My Class Three Ways","primary":"Collect real scores/marks of 15+ NAMED classmates. Implement merge, quick and selection sort in Python and count the operations each takes on the SAME data.","support":"~400 words comparing the three on your real numbers and their complexity.","llc":"Show the raw data, name the people, and defend which sort scales best to 500 students."},
      {"option_no":3,"title":"The Shortest Way Home","primary":"Map 6-8 real named places with real distances (measured, walked, or from signboards). Implement shortest-path in Python and verify ONE route by actually checking the road.","support":"~400 words on graph representation and the algorithm.","llc":"Show the real map, name the places, and defend the code's route against the one people actually walk."},
      {"option_no":4,"title":"The Seating That Took Backtracking","primary":"Get a real constraint puzzle from a NAMED source — a wedding seating with real feuding pairs an elder names (phone-verifiable, with consent), or a real timetable clash. Solve it with backtracking code (colouring / N-Queen style).","support":"~400 words on the backtracking method and the dead-ends it hit.","llc":"Name the source, show the constraints, and run the solver live."},
      {"option_no":5,"title":"My Algorithm Error Logbook","primary":"While implementing THREE of these labs, keep a handwritten logbook of every bug and its fix, dated. Bring the logbook and the three working programs.","support":"~400 words grouping your bugs by cause (index, base-case, comparison) and what each taught you.","llc":"Show the handwritten log and defend the single hardest bug live. Your real debugging trail cannot be fabricated."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UCYCP02'
  and is_latest = true and is_archived = false;

-- ── 26UMBC01 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Caring","task":"Walk to ONE named microbe-rich spot near you - the Cauvery riverbank at Komarapalayam, a compost pit, a paddy-field bund, or a cattle-shed floor - and notice where life is thickest (slime, smell, rotting matter).","deliverable_notes":"One photo of the spot with your hand or foot in frame + the exact place name. Write 3-4 sentences: what signs of microbial life you saw or smelled, which kingdom(s) likely live there, and one reason this hidden habitat is worth protecting."},
      {"sno":2,"unit":"II","finks_dimension":"Foundational Knowledge","task":"Collect real yeast and mould from your own kitchen - froth from fermenting idli/dosa batter or toddy (yeast), and fuzzy growth on old bread, orange, or leftover rice (mould).","deliverable_notes":"A hand-drawn labelled sketch of BOTH (yeast budding cells + mould hyphae and spore heads as you observe them) beside a photo of your actual samples. Write 3-4 sentences naming the structures (cell wall, bud, hypha, spore) and one visible difference between yeast and mould."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Make a simple nutrient medium at home (boiled rice-water or potato water in a clean lidded glass), expose it to ONE source - your unwashed thumb, a coin, pond water - then keep it warm for 3-4 days.","deliverable_notes":"A daily photo series (day 0 to day 3) showing colonies appearing + a count of visible colonies each day. Write 3-4 sentences on how growth changed over time and why a warm, nutrient-rich medium let it happen."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Using the college microscope, examine ONE real specimen yourself (a curd smear, pond water, or a stained bacterial slide), focusing from low to high power on your own.","deliverable_notes":"A hand-drawn sketch of exactly what YOU saw down the eyepiece (not a textbook image) + the magnification used. Write 3-4 sentences: which microscope type and stain, what shapes and arrangements you saw, and one thing the stain made visible that was invisible before."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Find ONE named person who kills germs for their work - a nurse at Komarapalayam PHC, a hostel-mess cook, a dairy worker, or a beautician - and ask exactly how they sterilise their tools.","deliverable_notes":"The person's name + role + phone-verifiable contact and one quoted sentence in their words. Write 3-4 sentences linking their method (boiling, flame, spirit, autoclave, bleach) to a sterilisation principle from Unit V and whether it truly achieves sterility."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Habitat Under My Feet","primary":"Choose ONE real local niche - a Cauvery backwater, a compost heap, a cowshed - and document its microbial life across a week with dated photos, a smell/colour log, and a hand-drawn food-web of who eats what.","support":"~400 words linking your niche to classification and biodiversity (Units I-II).","llc":"Bring your photo-log and defend which kingdoms rule your spot before the cohort and faculty. An AI can describe a niche; it cannot log YOURS."},
      {"option_no":2,"title":"I Grew It Myself","primary":"Culture microbes from ONE named local source (well water, street food, your phone screen) on a homemade medium; keep dated photos, colony counts, and a growth graph you plot by hand.","support":"~400 words on media, growth phases, and asepsis (Unit III).","llc":"Show the plates/photos and defend your counts under questions. An AI cannot grow your colonies."},
      {"option_no":3,"title":"Seen With My Own Eye","primary":"Over three microscope sessions, examine three real specimens you collected; hand-draw each field-of-view with the magnification and stain noted, exactly as you saw it.","support":"~400 words comparing microscope types and stains (Unit IV).","llc":"Present your three sketches and explain what each technique revealed. AI generates textbook images; it cannot draw YOUR eyepiece view."},
      {"option_no":4,"title":"How My People Kill Germs","primary":"Interview THREE named local workers (nurse, cook, dairy hand) about sterilisation; record their voices with consent, get phone-verifiable contacts, and quote each in their own language.","support":"~400 words mapping each method to Unit V principles.","llc":"Play or read their words and rank whose method is truly sterile. An AI cannot interview your three people."},
      {"option_no":5,"title":"The Kingdom Map of My Street","primary":"Survey ONE 100-metre stretch you name (your lane, a market row) and photograph or collect signs of every major microbial group - fermented food, mould, wall algae, a fungus-infected plant.","support":"~400 words placing each in the kingdom system (Units I-II).","llc":"Display your street-map of kingdoms and defend each placement. An AI cannot walk your street."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UMBC01'
  and is_latest = true and is_archived = false;

-- ── 26UMBCP01 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"In the lab, sterilise a set of glassware yourself by autoclave or hot-air oven, and set up a sterility check - an uninoculated medium plate incubated alongside your work.","deliverable_notes":"A photo of your labelled sterility-check plate after incubation (your initials + date on the lid) + a yes/no on whether it stayed clear. Write 3-4 sentences: which method and settings (temperature/time/pressure) you used and what a contaminated control plate would have told you."},
      {"sno":2,"unit":"II","finks_dimension":"Learning How to Learn","task":"Prepare one solid (agar plate), one semi-solid (agar deep), and one slant yourself, and note anything that went wrong - agar not setting, bubbles, an uneven slant.","deliverable_notes":"A photo of your three actual tubes/plates side by side + a short 'what I would fix next time' note. Write 3-4 sentences on the agar concentration and cooling angle that control setting, and one troubleshooting lesson you learned by doing, not by reading."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Streak a plate for isolated colonies from ONE real source you choose (curd, garden soil, tap water) using the four-quadrant method, on your own.","deliverable_notes":"A photo of your streaked plate after incubation showing (or not showing) isolated single colonies + your initials and date. Write 3-4 sentences: your source, whether you achieved isolation, and what the streak pattern tells you about diluting cells across the agar."},
      {"sno":4,"unit":"IV","finks_dimension":"Integration","task":"Pick THREE different colonies from any plate you grew and describe each by real observation - size, shape, margin, elevation, colour, opacity, and any pigment.","deliverable_notes":"A hand-drawn table of your three colonies with all six characters filled from what you actually see + a photo. Write 3-4 sentences on how careful colony description helps tell organisms apart even before any staining or biochemical test."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Do a Gram stain on ONE smear yourself, AND set up a hay-infusion from a named local water source (a Kavandampatti pond, a temple tank) to view live microbes by wet mount.","deliverable_notes":"Your hand-drawn sketch of the Gram result (purple/pink + cell shape) + a sketch of the moving organisms in your hay-infusion drop, with the water source named. Write 3-4 sentences on what the Gram colour told you about the cell wall and what living diversity you saw."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"My Sterile Field, Proven","primary":"Run a full sterilisation cycle and PROVE it worked with paired control plates (sterile vs deliberately exposed), dated photos, and your logged autoclave settings.","support":"~400 words on sterilisation methods and quality control (Unit I).","llc":"Show both plates to cohort and faculty and defend why one stayed clear. An AI cannot run your autoclave or grow your control."},
      {"option_no":2,"title":"From Muddy Water to Single Colony","primary":"Take ONE named local water/soil source and carry it through media prep, streaking, and isolation to a pure culture; keep every dated plate photo.","support":"~400 words on media and pure-culture technique (Units II-III).","llc":"Present your plate series and defend that your final colony is pure. An AI cannot isolate your organism."},
      {"option_no":3,"title":"The Colony Catalogue of Komarapalayam","primary":"Build a hand-drawn catalogue of at least six real colonies you grew from named local sources, each described by all standard characters with a photo.","support":"~400 words on cultural characteristics and description (Unit IV).","llc":"Display your catalogue and identify an unknown colony live from its features. An AI cannot observe your plates."},
      {"option_no":4,"title":"Purple or Pink - I Decided","primary":"Gram-stain five real smears (curd, tooth plaque, pond, soil, spoiled food) yourself; hand-draw each result and record shape and arrangement.","support":"~400 words on smear prep, staining, and the cell-wall basis of the result (Unit V).","llc":"Show your five sketches and defend each Gram call. An AI generates stain images; it cannot stain YOUR smears."},
      {"option_no":5,"title":"A Drop of Living Water","primary":"From ONE named local water body, set up a hay-infusion and track the changing microbial community over a week with dated wet-mount sketches and counts.","support":"~400 words on microbial diversity and wet-mount methods (Unit V).","llc":"Present your week-long sketch series and defend what shifted and why. An AI cannot watch your drop."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UMBCP01'
  and is_latest = true and is_archived = false;

-- ── 26UMBCP02 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Test ONE real culture (or a curd/pond organism) for motility by hanging drop or semi-solid stab, AND perform a capsular or acid-fast stain yourself.","deliverable_notes":"A hand-drawn sketch of the motility you saw (true darting vs Brownian jiggle) + your stain result, with the method named. Write 3-4 sentences on how you told real motility from random movement and what the stain revealed about the cell surface."},
      {"sno":2,"unit":"II","finks_dimension":"Learning How to Learn","task":"Follow ONE broth culture over several hours, reading turbidity (Petroff-Hausser count or OD/turbidometer) at set intervals, and plot your OWN growth curve BY HAND before touching any software.","deliverable_notes":"The hand-plotted curve itself (time vs count/OD) with the four phases marked where you see them + your raw data table. Write 3-4 sentences on where lag, log, stationary, and death appear and what a single end-point reading would have hidden."},
      {"sno":3,"unit":"III","finks_dimension":"Caring","task":"Set up a disc-diffusion (Kirby-Bauer) test on ONE isolate against real antibiotic discs and measure each zone of inhibition in millimetres yourself with a ruler.","deliverable_notes":"A photo of your plate with zones + your mm measurement for each disc, and one line on which drug worked best. Write 3-4 sentences linking your zones to sensitive/resistant, and why careless antibiotic use in your town could make these zones shrink over time."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Calibrate a micrometer on your microscope and measure the REAL size of yeast cells, a fungal-filament width, or a protozoan you have on a slide.","deliverable_notes":"Your calibration calculation + at least five real measurements in micrometres with a hand-drawn scaled sketch. Write 3-4 sentences on how you converted eyepiece divisions to microns and how your measured size compares to the textbook range."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Run a set of biochemical tests (IMViC, catalase, oxidase, urease, TSI or carbohydrate fermentation) on ONE unknown bacterium and read each result yourself.","deliverable_notes":"A filled results table (test -> your observed colour/gas -> interpretation) + a photo of at least two tubes, leading to your best-guess genus. Write 3-4 sentences on how you combined several test results to narrow the identity, rather than relying on one test alone."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"Alive or Just Jiggling","primary":"Test motility in five real organisms by two methods (hanging drop + semi-solid), hand-draw each, and decide true motility vs Brownian motion for every one.","support":"~400 words on motility methods and their flagellar basis (Unit I).","llc":"Present your sketches to cohort and faculty and defend each motility call. An AI cannot watch your drops move."},
      {"option_no":2,"title":"The Curve Only I Could Draw","primary":"Track ONE broth culture's growth across a full session, hand-plot the curve from your own turbidity/count data, and mark all four phases.","support":"~400 words on growth phases and counting methods (Unit II).","llc":"Show your hand-plotted curve and defend where each phase begins. An AI cannot generate your real time-series."},
      {"option_no":3,"title":"The Shrinking Zone","primary":"Run disc-diffusion on ONE local isolate against several antibiotics, measure every zone in mm, and photograph the plate.","support":"~400 words connecting your zones to sensitivity and to antibiotic misuse in your community (Unit III).","llc":"Display your plate, rank the drugs, and argue what resistance means for your town. An AI cannot measure your zones."},
      {"option_no":4,"title":"How Big Is Small - Measured by Me","primary":"Calibrate a micrometer and measure the real sizes of yeast, a mould filament, and a protozoan across many cells; keep your calculations and scaled sketches.","support":"~400 words on micrometry and morphological variation (Unit IV).","llc":"Present your measurements and defend your calibration under questions. An AI cannot calibrate YOUR eyepiece."},
      {"option_no":5,"title":"Naming the Unknown","primary":"Identify ONE unknown bacterium end-to-end using morphology plus a full biochemical panel you run yourself; keep the results table and tube photos.","support":"~400 words on how biochemical tests discriminate genera (Unit V).","llc":"Reveal your unknown's identity and defend the test-chain that got you there. An AI cannot run your tubes."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UMBCP02'
  and is_latest = true and is_archived = false;

-- ── 26UMBDE01 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Measure the pH of at least four REAL water sources you can name - a Komarapalayam borewell, an RO can, Cauvery/tap water, and rain or pond water - using a pH meter or pH strips.","deliverable_notes":"A data table of source -> pH + a photo of one reading in progress. Write 3-4 sentences on which source was most acidic/alkaline, why calibrating a pH meter with standard buffers matters, and what your readings suggest about drinking safety."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Make a dilution series of ONE real coloured local liquid (turmeric water, tea, beetroot juice) and read each on a colorimeter/spectrophotometer, or rank colour depth by eye against known dilutions.","deliverable_notes":"A table of concentration vs absorbance (or colour rank) + a hand-drawn graph. Write 3-4 sentences on how absorbance changed with concentration (Beer-Lambert), which wavelength you chose and why, and what a colorimeter measures that your eye cannot."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Run a paper chromatogram yourself of ONE real mixture - spinach or drumstick-leaf extract, a sketch-pen ink dot, or turmeric - in a solvent, and let the spots separate.","deliverable_notes":"The actual chromatography paper (or a clear photo) with your measured Rf value for each spot. Write 3-4 sentences on how you calculated Rf, why different pigments travelled different distances, and how this same idea scales up to TLC or HPLC."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Visit a named local diagnostic centre or hospital (Komarapalayam/Erode/Salem) and ask a technician about ONE imaging test they run - ECG, CT, or MRI - and how the machine works.","deliverable_notes":"The technician's name + centre + one quoted sentence, plus a note of the machine seen. Write 3-4 sentences linking what they told you to the Unit IV principle of that scan and one thing that surprised you about its real clinical use."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Over a stove or spirit flame at home, burn small pinches of common salts you can name - table salt (sodium), a copper-object edge, a low-sodium 'salt substitute' (potassium) - and watch the flame colour.","deliverable_notes":"Photos of each flame colour + a table of salt -> colour seen. Write 3-4 sentences on how a flame photometer turns this colour into a number, why each metal gives its own colour, and what this taught you about instruments extending your senses."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The pH Map of My Water","primary":"Measure and log the pH of at least six named local water sources over a week with a calibrated meter or strips, plus one photo per reading.","support":"~400 words on pH measurement, buffers, and calibration (Unit I).","llc":"Present your water-pH map to cohort and faculty and flag any unsafe source. An AI cannot test your wells."},
      {"option_no":2,"title":"Colour Into Numbers","primary":"Build a full concentration-vs-absorbance series for ONE real local pigment on a colorimeter, hand-plot the Beer-Lambert line, and read an unknown off it.","support":"~400 words on spectroscopy principles (Unit II).","llc":"Show your graph and estimate an unknown's concentration live. An AI cannot run your samples."},
      {"option_no":3,"title":"What the Paper Separated","primary":"Run three real chromatograms (leaf pigments, ink, spice) yourself, keep the papers, and calculate every Rf value.","support":"~400 words connecting paper chromatography to TLC, column, and HPLC (Unit III).","llc":"Display your papers and defend your Rf calculations. An AI cannot run your solvent front."},
      {"option_no":4,"title":"Inside the Scan Room","primary":"Interview TWO named technicians at local diagnostic centres about the imaging machines they run; record consented voices, get phone-verifiable contacts, and note each machine.","support":"~400 words mapping their work to Unit IV imaging principles.","llc":"Play their words and explain how one scan actually forms an image. An AI cannot visit your scan room."},
      {"option_no":5,"title":"The Colours of the Elements","primary":"Photograph flame-test colours of at least five real salts you source locally, match each to its metal, then explain how a flame photometer or spectrofluorimeter quantifies it.","support":"~400 words on fluorescence and flame-based instruments (Unit V).","llc":"Show your flame photos and defend each element call. An AI cannot light your flame."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UMBDE01'
  and is_latest = true and is_archived = false;

-- ── 26UMBFC1 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Set curd at home from fresh milk with a spoon of starter curd, and note the time, the warmth of the spot, and how the milk changes into curd.","deliverable_notes":"Photos of milk (start) and set curd (end) + the hours it took and where you kept it. Write 3-4 sentences naming the bacterium (Lactobacillus), the acid it makes, why warmth speeds it, and one other food your family ferments the same way."},
      {"sno":2,"unit":"II","finks_dimension":"Foundational Knowledge","task":"Leave a slice of bread or a piece of chapati slightly damp in a covered box for 4-5 days and watch mould appear and change colour.","deliverable_notes":"A dated photo series (day 1 to day 5) + a hand-drawn sketch of the mould's fuzzy hyphae and coloured spore heads. Write 3-4 sentences naming what you see (mycelium, spores), how the colour changed, and whether it looks like Rhizopus, Aspergillus, or Penicillium."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Visit ONE named local water body - a Kavandampatti pond, a temple tank, a stagnant canal - and look for green algal scum or bloom, especially where waste water enters.","deliverable_notes":"A photo of the water with the algae + the place name and how green it was near the inlet vs the middle. Write 3-4 sentences naming the likely algae, explaining eutrophication from fertiliser or sewage, and why a green bloom can harm fish and people."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Interview ONE named elder or parent about a vaccine they or their child received - polio drops, rabies shots after a dog bite, or a COVID jab - and what they remember about it.","deliverable_notes":"The person's name + relationship + phone-verifiable contact and one quoted line. Write 3-4 sentences linking their story to how a vaccine uses a weakened or killed virus to train immunity, and why the rabies or polio programme mattered locally."},
      {"sno":5,"unit":"V","finks_dimension":"Caring","task":"Ask ONE named person in your household or street who once had loose motions or a 'stomach infection' about what they drank or ate, and check how your own home stores and treats drinking water.","deliverable_notes":"The person's account (named) + a photo of your home's water pot, filter, or RO unit. Write 3-4 sentences on how protozoa like Entamoeba or Giardia spread through unclean water, one thing your family does right, and one thing you could improve."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Ferment in My Kitchen","primary":"Document ONE real fermentation your family does (curd, idli batter, pickle, palm toddy) across its full cycle with dated photos, timings, taste/smell notes, and the named person who taught you.","support":"~400 words on the microbes and their economic importance (Unit I).","llc":"Bring your notes (and, if safe, a sample) and defend which microbe did the work before cohort and faculty. An AI cannot ferment your kitchen."},
      {"option_no":2,"title":"Watching Mould Grow","primary":"Grow mould on three different local foods, photograph each daily for a week, and hand-draw the structures and colour changes.","support":"~400 words on fungal features and their helpful and harmful roles (Unit II).","llc":"Display your photo-and-sketch series and name your moulds. An AI cannot grow your mould."},
      {"option_no":3,"title":"The Green in Our Water","primary":"Survey ONE named local water body over two visits for algae, photograph the inlet vs open water, and note colour, smell, and any dead fish.","support":"~400 words on algae's benefits and on eutrophication (Unit III).","llc":"Present your two-visit comparison and argue what is polluting your water. An AI cannot visit your pond."},
      {"option_no":4,"title":"The Shot That Saved Us","primary":"Interview THREE named people across generations about vaccines they received; record consented voices, get phone-verifiable contacts, and quote each.","support":"~400 words on viruses, vaccines, and their economic importance (Unit IV).","llc":"Play their voices and tell the cohort how one vaccine changed a life. An AI cannot interview your family."},
      {"option_no":5,"title":"Is Our Water Safe?","primary":"Audit your own street's drinking-water handling - interview at least three named households on source, storage, and any past stomach illness, with photos of their pots or filters.","support":"~400 words on waterborne protozoa and sanitation (Unit V).","llc":"Present your street water-audit and one practical fix. An AI cannot audit your street."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
