  and is_latest = true and is_archived = false;

-- ── 26UMBGE01 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Using a drop of iodine (tincture from a medical shop) test at least five real local foods for starch - cooked rice, raw potato, banana, bread, and sugar - watching for a blue-black colour.","deliverable_notes":"A photo of your tested samples + a table of food -> colour -> starch present/absent. Write 3-4 sentences on why starch turns iodine blue-black, which of your foods are polysaccharide-rich vs sugar-rich, and how this links carbohydrate structure to what you actually eat."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Take ONE fresh egg (Namakkal, nearby, is the egg capital) or fresh milk and denature its protein three ways - by heat, by lemon/vinegar acid, and by salt - watching what happens each time.","deliverable_notes":"A photo of the three results (cooked white, curdled milk, and so on) + notes on what changed. Write 3-4 sentences naming the protein (albumin or casein), what denaturation does to its folded shape, and why both heat and acid make it clump."},
      {"sno":3,"unit":"III","finks_dimension":"Human Dimension","task":"Interview ONE named person you know who lives with diabetes about how they check their sugar, what they eat, and what the doctor has told them.","deliverable_notes":"The person's name + phone-verifiable contact + one quoted line, and their fasting-sugar range if they will share it. Write 3-4 sentences linking their daily management to disordered glucose metabolism (insulin, hyperglycaemia) from Unit III and one lifestyle factor that helps them."},
      {"sno":4,"unit":"IV","finks_dimension":"Caring","task":"Visit or phone a named local hospital or PHC and ask whether they do newborn screening (the heel-prick) for metabolic disorders like PKU or galactosemia, and who to talk to about it.","deliverable_notes":"The named contact + what screening (if any) is done locally. Write 3-4 sentences on why catching an inborn error of amino-acid metabolism early (Unit IV) can prevent lifelong harm, and how you felt learning whether your own area screens its babies."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"With consent, get a REAL blood-test report from your family (LFT, RFT, or a routine panel) and find the enzyme and organ markers - SGPT/ALT, SGOT/AST, urea, creatinine.","deliverable_notes":"A photo of the report with values circled (hide the person's name) + which markers were high, low, or normal. Write 3-4 sentences on what each enzyme or marker tells about liver or kidney function (Unit V) and why a doctor reads several together, not one alone."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"What My Plate Is Made Of","primary":"Chemically test at least eight real local foods for starch and sugar (and, if possible, protein and fat) with iodine and simple tests, photographing every result into a food-composition chart.","support":"~400 words on carbohydrate and lipid structure and function (Unit I).","llc":"Present your food chart to cohort and faculty and defend each classification. An AI cannot test your foods."},
      {"option_no":2,"title":"The Shape That Broke","primary":"Denature egg or milk protein by five real methods (heat, acid, alcohol, salt, metal ion), photograph each, and rank which clumped fastest.","support":"~400 words on protein structure and denaturation (Unit II).","llc":"Show your five results and explain what denaturation did to the molecule. An AI cannot curdle your milk."},
      {"option_no":3,"title":"Living With Sugar","primary":"Interview THREE named people managing diabetes about diet, testing, and treatment; record consented voices, get phone-verifiable contacts, and quote each.","support":"~400 words on glucose-metabolism disorders (Unit III).","llc":"Play their words and explain the biochemistry behind one piece of their doctor's advice. An AI cannot interview your neighbours."},
      {"option_no":4,"title":"Caught at Birth","primary":"Investigate newborn metabolic screening in your area by interviewing TWO named hospital/PHC staff and one parent, documenting what is tested and what it costs.","support":"~400 words on inborn errors of amino-acid metabolism (Unit IV).","llc":"Present your local-screening finding and argue for or against wider screening. An AI cannot survey your hospitals."},
      {"option_no":5,"title":"Reading the Blood","primary":"Collect (with consent) three real lab reports from your family or community, map every enzyme and organ marker to its meaning, and flag values outside the normal range.","support":"~400 words on organ-function tests and diagnostic enzymes (Unit V).","llc":"Present one de-identified report and interpret it live under questions. An AI cannot read YOUR family's reports."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UMBGE01'
  and is_latest = true and is_archived = false;

-- ── 26UMBNM01 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Human Dimension","task":"Interview (with consent) one older person in your named locality about how health and disease were understood and handled in their youth; note the social determinants at work.","deliverable_notes":"3–4 quoted sentences from the named person + your list of social determinants you can identify in their story."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Find one real government or community health/nutrition programme operating in your area (a named PHC scheme, anganwadi, water/sanitation effort) and document what it actually does.","deliverable_notes":"The named programme + what you observed of it + 1 line on who it reaches and who it misses."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Visit or describe from real observation one community health service near you (a PHC, a school health check, a maternal-child service) and map its role in the community.","deliverable_notes":"The named service + your observation notes + 2 sentences on one gap you noticed."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Pick one preventable disease relevant to your area and lay out the three levels of prevention with concrete local actions for each.","deliverable_notes":"The disease + your three-level prevention plan with locally-specific actions + 1 line on the cheapest high-impact action."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Study one real outbreak case (SARS/MERS/Ebola/COVID or a local one) from named sources and extract two preventive lessons that apply to your own community.","deliverable_notes":"The outbreak + named sources + your two locally-applicable lessons."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Health Story from My Community","primary":"Through consented interviews and real observation in a NAMED locality, document how one health issue (nutrition, sanitation, a common disease, maternal care) actually plays out there — the social determinants, the services that exist, and the gaps — grounded in real voices and sights, not statistics alone.","support":"~400 words on what surprised you about health where you live.","llc":"Present the story (with photos/quotes) and answer questions on the determinants."},
      {"option_no":2,"title":"A Real Programme, Assessed on the Ground","primary":"Choose one actual public-health or nutrition programme running in your area, observe or interview about how it truly operates, and honestly assess its reach and gaps against its stated aims.","support":"~400 words on the gap between policy and delivery.","llc":"Present your assessment and defend one recommendation."},
      {"option_no":3,"title":"Three Levels of Prevention, Made Local","primary":"Take one preventable condition that matters in your locality and build a concrete, costed, three-level prevention plan using real local resources and named services.","support":"~400 words on why prevention is cheaper than cure here.","llc":"Present the plan and answer a 'what would you do first with limited money?' challenge."},
      {"option_no":4,"title":"Lessons an Outbreak Left Us","primary":"Study one real disease outbreak from named, credible sources, reconstruct how it spread and was controlled, and translate two lessons into specific actions your own community could take.","support":"~400 words on what preparedness really requires.","llc":"Present and defend your community-action proposal."},
      {"option_no":5,"title":"The Elder Who Remembers","primary":"Conduct a deeper consented oral history with one or two elders in a named place about health, disease, and care across their lifetime, and analyse the changes through the social-medicine concepts of the course.","support":"~400 words on the shift you traced.","llc":"Present the voices and connect them to health transitions live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UMBNM01'
  and is_latest = true and is_archived = false;

-- ── 26UMBNM02 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Record everything you actually eat for two full days and assess it against balanced-diet principles; identify what's missing or excess.","deliverable_notes":"Your real 2-day food log + your balance assessment + 1 line on your single biggest dietary gap."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Plan a real balanced day's meals for one specific group (a pregnant woman, a young child, an elderly relative you name, with consent) using locally available, affordable foods.","deliverable_notes":"Your meal plan with real local foods and rough costs + who it's for + 1 line on the nutrient you prioritised."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Identify, in your real community (respectfully, without naming individuals publicly), one likely sign of a nutrition problem (under- or over-nutrition) and connect it to its dietary cause.","deliverable_notes":"Your observation (kept anonymous) + the nutritional analysis + 1 line on a realistic dietary correction."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Design one simple, real health-education message on a nutrition or hygiene topic for a specific local audience, and test it on two named people for clarity.","deliverable_notes":"Your message/poster + the two people's reactions + 1 line on what you changed after their feedback."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Audit the real WASH (water, sanitation, hygiene) situation in one named setting (your home, a hostel, a shop) against good-practice checklists.","deliverable_notes":"Your WASH checklist filled for the real setting + 1 line on the most fixable weakness you found."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"My Own Plate, Honestly Assessed","primary":"Track your real diet over at least a week, analyse it rigorously against nutritional science, identify your genuine deficiencies or excesses, and design AND actually trial a realistic improvement using affordable local foods.","support":"~400 words on what changed and what was hard to change.","llc":"Present your before/after and defend your plan's practicality."},
      {"option_no":2,"title":"A Balanced Diet for Someone Real","primary":"Choose a real person from a specific nutritional group (with consent — a pregnant relative, a child, an elder) and design a genuinely usable balanced-diet plan from locally available, affordable foods, checking it against their real preferences and constraints.","support":"~400 words on affordability vs nutrition trade-offs.","llc":"Present the plan and answer 'why this food, not that?'"},
      {"option_no":3,"title":"A Health Message That Actually Lands","primary":"Create a real nutrition or hygiene education message for a specific local audience, test it on real people, iterate on their feedback, and — if possible — deliver it for real.","support":"~400 words on what makes health messaging work or fail here.","llc":"Deliver the message live and answer how you'd reach a resistant audience."},
      {"option_no":4,"title":"A WASH Audit of a Real Place","primary":"Conduct a thorough water-sanitation-hygiene audit of a named real setting, document specific findings with evidence, and propose realistic, low-cost improvements.","support":"~400 words on the link between WASH and disease you observed.","llc":"Present findings and defend your top improvement."},
      {"option_no":5,"title":"Malnutrition, Understood Locally","primary":"Investigate one form of malnutrition relevant to your area (using respectful observation and named public-health sources, never shaming individuals), analyse its dietary and social causes, and outline a community-level response.","support":"~400 words on why the problem persists despite food being available.","llc":"Present your analysis and answer questions on the causes."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UMBNM02'
  and is_latest = true and is_archived = false;

-- ── 26UMBSE01 · b-sc-microbiology ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Find a real mulberry (Morus) plant - in a garden, a hedge, a sericulture farm, or at the nearest agriculture/sericulture office around Salem-Dharmapuri - and examine its leaves closely.","deliverable_notes":"A photo of you beside the plant + measurements of three leaves (length and width in cm) and a note of the variety if anyone knows it. Write 3-4 sentences on why leaf size and quality matter for silkworm feed and which mulberry features you observed (leaf shape, texture, colour)."},
      {"sno":2,"unit":"II","finks_dimension":"Foundational Knowledge","task":"Visit a named local rearing unit, sericulture centre, or agri-college around Salem/Dharmapuri and observe as many real silkworm stages as you can - eggs, larvae, cocoon, moth.","deliverable_notes":"Dated photos of each stage you saw + a hand-drawn life-cycle wheel labelling egg -> larva -> pupa -> moth. Write 3-4 sentences on which stage/instar you actually observed, how the larva changes as it grows, and roughly how many days each stage takes."},
      {"sno":3,"unit":"III","finks_dimension":"Human Dimension","task":"Interview ONE named silkworm rearer or a sericulture officer about a disease outbreak (Pebrine, Grasserie, Muscardine, or Flacherie) that hit their crop and what they did about it.","deliverable_notes":"The person's name + village + phone-verifiable contact and one quoted line. Write 3-4 sentences linking their described symptoms and losses to the specific disease and its pathogen from Unit III, and the prevention they now practise."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Get ONE real silk cocoon (from a rearer, a cocoon market, or the college) and measure it - weight in grams, length, shell - or observe reeling at a Salem-area unit.","deliverable_notes":"A photo of the cocoon in your hand + its weight and size, or your reeling notes. Write 3-4 sentences on cocoon assessment (shell ratio, filament), what stifling and reeling do, and one value-added product that could come from it."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Collect REAL local numbers for a small sericulture unit - the cost of mulberry saplings, of disease-free layings (dfls), and the current cocoon price at a named market (for example the Dharmapuri or Hosur cocoon market) - by asking a shop, an officer, or a rearer.","deliverable_notes":"A one-page hand-made cost sheet: inputs, their real prices with sources named, and a rough profit guess. Write 3-4 sentences on whether a small unit looks viable in your area and which cost or risk (Unit V, or disease) worries you most."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Leaf That Feeds the Silk","primary":"Locate and study real mulberry plants at a named site, measuring leaves, photographing varieties, and interviewing one grower about leaf quality; keep dated evidence.","support":"~400 words on mulberry cultivation and varieties (Unit I).","llc":"Present your leaf data to cohort and faculty and defend which plant would feed silkworms best. An AI cannot measure your mulberry."},
      {"option_no":2,"title":"The Five Lives of the Silkworm","primary":"Document as many real silkworm life stages as you can access at a named rearing unit, with dated photos and a hand-drawn labelled life cycle.","support":"~400 words on silkworm biology and its life cycle (Unit II).","llc":"Show your stage photos and walk the cohort through the metamorphosis. An AI cannot photograph your rearing tray."},
      {"option_no":3,"title":"When the Crop Fell Sick","primary":"Interview TWO named rearers or officers about silkworm disease outbreaks; record consented voices, get phone-verifiable contacts, and gather any photos of affected worms.","support":"~400 words on the four major diseases and their control (Unit III).","llc":"Play their accounts and diagnose which disease struck from the symptoms. An AI cannot interview your rearers."},
      {"option_no":4,"title":"From Cocoon to Thread","primary":"Obtain real cocoons, measure them (weight, shell ratio, filament length where possible), and if you can, observe or photograph reeling at a named Salem-area unit.","support":"~400 words on cocoon assessment, stifling, and reeling (Unit IV).","llc":"Bring your cocoons and defend your quality assessment. An AI cannot weigh your cocoon."},
      {"option_no":5,"title":"Could I Run a Silk Unit?","primary":"Build a real costed mini-plan for a small sericulture enterprise using named local prices (saplings, dfls, cocoon rate) gathered from real sources, plus one interview with an EDP or agriculture officer.","support":"~400 words on EDP, project formulation, and marketing (Unit V).","llc":"Pitch your one-page plan to the cohort and defend your numbers. An AI cannot gather your local prices."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UMBSE01'
  and is_latest = true and is_archived = false;

-- ── 26UPHC01 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Find one everyday object that stretches, bends, or springs back (clothes-line wire, cot-spring, cycle brake cable). Load it with a known weight and watch what happens.","deliverable_notes":"Bring the object (or a photo of it under load, your hand in frame) + a hand-drawn stress-vs-stretch sketch. Write 3-4 sentences: what you loaded, whether it returned to shape, which elastic idea it shows."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Find one real beam or cantilever near you — a shop awning, temple mandapam slab, hostel balcony, bus-stand roof — and see where it sags and where it is held.","deliverable_notes":"A photo of the exact structure with the point of maximum bending marked by your own hand. Two sentences naming the place and why the builder put the support where they did. No essay."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Count drops from a dropper of water vs. cooking oil vs. buttermilk in the same vessel, OR time a steel ball / seed sinking through each.","deliverable_notes":"Your own data table (three liquids, your counts/times) + one line naming which is more viscous and where the liquids came from. The table is the deliverable, not prose."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Build a simple pendulum or stretch a string (rubber band on a tin, a relative's veena/guitar string) and change ONE thing — length or tension. Watch the period or pitch shift.","deliverable_notes":"A short dated observation table (what you changed → what happened) + one sentence linking it to SHM/resonance. Demonstrate it live at the LLC if you can bring it."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Go to ONE room where sound matters — a named temple hall, classroom, cinema, marriage-hall. Clap once and count how long the sound lingers.","deliverable_notes":"One number (your clap-echo count) + the named room + two sentences on whether it is built well for sound and one change you'd make. Bring a phone recording of the clap if you can."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Object That Would Not Break","primary":"Choose ONE real load-bearing object you can name and reach — a well rope, a two-wheeler suspension, a temple-car wheel, a hostel cot. Measure or test one property yourself (how far it bends, how it springs back) and bring the object or your own photos + a hand-drawn load sketch.","support":"~400 words on how its shape carries load, what would make it fail, and one named person who depends on it.","llc":"Show the object, walk the cohort through your sketch, answer their questions."},
      {"option_no":2,"title":"The Sound of One Place","primary":"Pick ONE named acoustic space near you. Measure its reverberation yourself — clap-echo timings at three spots, a phone recording. Bring your data and the recording.","support":"~400 words on why it sounds as it does (Sabine) and what you'd change.","llc":"Play your recording, show your timings, take questions. The measurement and the recording are the proof AI cannot generate."},
      {"option_no":3,"title":"A Liquid I Watched All Semester","primary":"Choose ONE fluid in your household or town — buttermilk a relative sets, oil at a named shop, tank water. Measure its surface tension/viscosity yourself across the semester (drop-counts, sink-times), and how temperature or dilution changed it. Bring your data table.","support":"~400 words on what the person who handles it daily already knows that the physics now explains.","llc":"Show your data, demonstrate a drop-test live if you can."},
      {"option_no":4,"title":"The Experiment My Grandparent Already Knew","primary":"Interview ONE named elder who judges a material by feel — testing rope, judging oil, tuning a drum, checking a beam. Record their voice (with consent), get a phone-verifiable contact, quote them in their own language.","support":"~400 words connecting their hand-knowledge to Units I-V.","llc":"Play or read their words, tell the cohort what they taught you, answer questions. AI can summarise the genre; it cannot interview YOUR elder."},
      {"option_no":5,"title":"Measuring What I Was Told to Trust","primary":"Pick ONE claim you were told to believe — 'this wire is strong enough', 'this hall has good sound', 'this oil is pure'. Test it yourself with this course's physics; bring your measurements and the named source of the claim.","support":"~400 words on whether the claim held and what it changed about how you judge such claims.","llc":"Present your test, your result, and defend it under questions."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHC01'
  and is_latest = true and is_archived = false;

-- ── 26UPHC02 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Measure how a real hot liquid cools — a tumbler of tea/coffee/rasam. Note the temperature (or how hot it feels, timed) every two minutes.","deliverable_notes":"Your own cooling table + a hand-drawn cooling curve. One line naming the liquid, the vessel, and where the curve is steepest. The graph is the deliverable."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Find ONE real heat engine or heat-work device you can point to — a pressure cooker, a two-wheeler engine, a steam iron, a kerosene stove — and trace where heat becomes work or motion.","deliverable_notes":"A photo of the named device + a hand-drawn P–V-style sketch of its cycle + two sentences on where heat goes in and work comes out."},
      {"sno":3,"unit":"III","finks_dimension":"Human Dimension","task":"Spot ONE everyday irreversible process where disorder increases — ice melting in a glass, sugar dissolving, smoke spreading, a room cooling. Watch it and time it.","deliverable_notes":"A short before/after photo pair or note + one line on why it never runs backward on its own (entropy). No essay — the observation is the point."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Compare heat transfer in TWO real vessels or materials — a mud pot vs a steel tumbler, a wooden vs metal spoon in hot water. Feel or time how fast each heats.","deliverable_notes":"Your own timing/observation table for the two materials + one line naming which conducts faster and why it matters in a real kitchen or home."},
      {"sno":5,"unit":"V","finks_dimension":"Foundational Knowledge","task":"Find ONE real situation with a huge number of particles behaving as a predictable average — a crowd at a bus-stand, rice boiling, a queue — and think about how the average is steady though each unit is random.","deliverable_notes":"3-4 sentences naming the real situation and connecting the many-random-units-give-a-steady-average idea to Maxwell–Boltzmann statistics. A photo of the crowd/pot strengthens it."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Cooling Curve of One Real Thing","primary":"Pick ONE real hot object you can measure repeatedly — a clay water-pot, a tumbler of filter coffee, a cooked pot of rice. Measure its cooling across the semester (your own timed temperature readings, a hand-drawn curve). Bring the data and the object.","support":"~400 words on what the cooling rate reveals (Newton's cooling, the vessel's material) and who benefits from it (why a clay pot keeps water cool).","llc":"Show your curve, demonstrate the cooling live if you can."},
      {"option_no":2,"title":"A Heat Engine in My Life","primary":"Choose ONE real heat-to-work device — a pressure cooker, a two-wheeler engine, a solar water heater. Study it yourself: photograph it, sketch its cycle by hand, measure what you can (pressure-cooker whistle timing, engine warmth). Bring your evidence.","support":"~400 words on its efficiency and losses (Carnot ideas).","llc":"Show the device or your sketch and defend where the energy is wasted."},
      {"option_no":3,"title":"The Process That Won't Run Backward","primary":"Document ONE real irreversible process across days — a clay pot slowly seeping, food spoiling, a dye spreading, metal rusting. Bring your dated photo series.","support":"~400 words on why entropy makes it one-way and what it would take to reverse it.","llc":"Show your photo series and explain irreversibility to the cohort. AI cannot produce YOUR dated observation of a real process."},
      {"option_no":4,"title":"Which Vessel My Grandmother Chose and Why","primary":"Interview ONE elder about why they use a particular vessel/material for a particular job — clay for water, iron for cooking, brass for storage. Record them (consent + phone-verifiable), then test the heat-transfer claim yourself. Bring their words + your measurement.","support":"~400 words connecting their choice to conduction/radiation.","llc":"Play their voice, show your test."},
      {"option_no":5,"title":"The Physics of Keeping Something Warm or Cold","primary":"Solve ONE real thermal problem in your home — keep tea hot longer, keep water cool, cook with less fuel. Try a real intervention, measure the before/after yourself. Bring your data.","support":"~400 words on the heat-transfer physics you used.","llc":"Present your problem, your measured improvement, and take questions on why it worked."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHC02'
  and is_latest = true and is_archived = false;

-- ── 26UPHCP01 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Application","task":"In the torsional-pendulum experiments (rigidity modulus), keep a personal error log — after each trial write the one thing you changed that moved the reading.","deliverable_notes":"Your actual error log (a photo of the page is fine) + your top three error sources in one line each. The log is the evidence."},
      {"sno":2,"unit":"Lab 3-6","finks_dimension":"Integration","task":"Take ONE real irregular object from home (grinding stone, spanner, temple bell) and estimate its moment of inertia by the lab method.","deliverable_notes":"The object (or a photo) + your measured numbers + one line on where your estimate is weakest. Bring the object to the LLC."},
      {"sno":3,"unit":"Lab 7-9","finks_dimension":"Application","task":"In the Young's-modulus experiments, plot your OWN load-vs-depression graph BY HAND before touching a calculator; mark where linearity breaks.","deliverable_notes":"The hand-plotted graph itself + the Young's modulus you read off + one sentence on what the graph's shape told you a single number could not."},
      {"sno":4,"unit":"Lab 10-12","finks_dimension":"Learning How to Learn","task":"Measure the SAME quantity (Young's modulus) by TWO different lab methods; record which gave a more reproducible answer.","deliverable_notes":"Your two results side by side + the % difference + one line on which method you'd trust for a real decision and why. Numbers, not prose."},
      {"sno":5,"unit":"Lab 13+","finks_dimension":"Caring","task":"Teach ONE named younger person to take ONE reading correctly on an instrument you used (vernier, screw gauge). Watch their first mistake.","deliverable_notes":"The name of who you taught + the instrument + one line on their first error and how you fixed it. Have them confirm it at the LLC if they can come."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Property of One Real Object, Measured by Me","primary":"Choose ONE real object you can name — a well rope, cot spring, temple bell, farm tool. Measure one mechanical property (rigidity, moment of inertia, or Young's modulus) using the lab methods, adapting the apparatus. Bring the object + your full data + your own error analysis.","support":"~400 words on what the number means for how the object is actually used.","llc":"Show the object and your measurements; defend your error bars under questions."},
      {"option_no":2,"title":"The Same Quantity, Three Ways","primary":"Measure ONE quantity (Young's modulus OR moment of inertia) by THREE different lab methods on the same specimen. Bring all three results, your hand-drawn graphs, and your honest error analysis.","support":"~400 words on why they differ and which you'd trust.","llc":"Present all three, let the cohort probe your discrepancies. The point is trustworthy measurement, not the number."},
      {"option_no":3,"title":"My Error Log Became My Teacher","primary":"Keep a rigorous measurement-error log across every experiment this semester — bring the actual log.","support":"~400 words tracing how your measurement discipline changed from Lab 1 to the last lab, with dated excerpts, and one experiment where technique changed your result.","llc":"Show your log's evolution. AI cannot fabricate a semester of your own dated mistakes."},
      {"option_no":4,"title":"Teaching an Instrument to Someone","primary":"Teach ONE named younger person to use one instrument (vernier, screw gauge, travelling microscope) from first wrong reading to reliable reading. Document their journey; have them present WITH you if possible.","support":"~400 words on what teaching revealed about your own gaps.","llc":"The two of you demonstrate; the cohort watches them take a correct reading."},
      {"option_no":5,"title":"What the Textbook Number Hides","primary":"Measure ONE 'standard' constant yourself (Young's modulus of steel, rigidity of brass) on a real named specimen. Bring your value + the specimen.","support":"~400 words comparing your value to the book's and analysing every reason they differ.","llc":"Show your specimen and defend why your messy real number is more honest than the clean textbook one."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHCP01'
  and is_latest = true and is_archived = false;

