-- ── 26UPHF01 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Map one real journey you took this week (hostel→class, home→bus-stand) as vectors — direction and distance per leg.","deliverable_notes":"A hand-drawn vector diagram of the named journey + one line: resultant displacement vs. total distance walked. The drawing is the deliverable."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Point at ONE ordinary scene and name every force in it — a bullock cart on a slope, a bucket drawn from a well, a two-wheeler on a banked curve.","deliverable_notes":"A photo or quick sketch of the named scene with force-arrows drawn by your own hand + two sentences on which force does the useful work."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Watch one real collision or energy transfer — a carrom strike, a cricket hit, a grinding stone. Note energy before and after.","deliverable_notes":"3-4 sentences (or a labelled photo) tracing where the energy went (kinetic, sound, heat) and whether momentum looked conserved. One dated observation."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Find linear, circular, and oscillatory motion near you (a bus, a ceiling fan, a swinging temple bell). Time one of them.","deliverable_notes":"One measurement (fan period, bell swing-time) + a photo or quick note naming each moving object and its motion type. Number first, words minimal."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Watch ONE everyday act using surface tension/viscosity/capillarity — a lamp wick drawing oil, cloth soaking water, a relative pouring ghee.","deliverable_notes":"A short note naming the act and the person doing it + one line on the property of matter at work. Bring a photo or a 10-second video to the LLC."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Physics of One Morning","primary":"Document ONE real morning of your life in photos/video — waking, cooking, travelling to JKKN.","support":"~400 words pointing at eight distinct physics ideas in those real moments (vectors, forces, energy, motion, matter).","llc":"Show your morning to the cohort and name the physics live. The photos of YOUR morning are what AI cannot produce."},
      {"option_no":2,"title":"A Machine in My Home","primary":"Choose ONE simple machine in your household — a well pulley, grinding stone, bicycle, hand-pump. Take it apart or measure how it moves; bring it or your photos + a hand-drawn diagram of the forces.","support":"~400 words on how it works and who in your family uses it.","llc":"Demonstrate it, answer questions on why it works."},
      {"option_no":3,"title":"The Force I Never Noticed","primary":"Pick ONE force (friction, tension, centripetal, cohesion) and photograph/log every real place it helped or fought you for a week — named roads, named tools, named tasks. Bring the log.","support":"~400 words on how noticing it changed how you move.","llc":"Walk the cohort through your week of evidence."},
      {"option_no":4,"title":"What My Elder Measures by Hand","primary":"Interview ONE named elder who estimates physical quantities without instruments — a farmer judging a load, a cook judging heat, a mason checking level. Record them (consent + phone-verifiable contact), quote their words.","support":"~400 words connecting their estimation to vectors/forces/energy.","llc":"Play their voice, tell what they taught you."},
      {"option_no":5,"title":"From School Answer to Real Question","primary":"Take ONE physics 'fact' you memorised without understanding, find it happening in your real surroundings, and observe/measure it yourself. Bring the evidence (photo, measurement) from the named real situation.","support":"~400 words on what changed between reciting the answer and seeing it.","llc":"Show where you finally saw it."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHF01'
  and is_latest = true and is_archived = false;

