update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Build a simple pendulum or a loaded spring at home and measure its time period for five different lengths/masses; check whether your data follows the SHM relation.","deliverable_notes":"Your five timed measurements (with the object described) + a hand plot + 1 line on how well SHM predicted your results."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Find a real cantilever or beam near you (a ruler clamped on a desk, a diving-board-like object) and measure how its free-end sags with added load; relate to bending theory.","deliverable_notes":"Your load-vs-depression readings + 1 line estimating stiffness + 1 line on what Young's modulus governs here."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Observe one real thermodynamic process at home (a pressure cooker, a refrigerator's back coil, ice melting) and identify the first-law energy flows in it by hand.","deliverable_notes":"The named process + your energy-flow sketch (heat in/out, work) + 2 sentences applying the first law."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Using a real magnet and a compass (or a phone magnetometer app), map the field direction at several points around a straight current-carrying wire or a coil you rig safely.","deliverable_notes":"Your point-by-point field readings/directions + 1 line comparing to Biot–Savart's prediction."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Build the truth table of at least two logic gates using a simple simulator or real ICs/switches, and verify one by your own testing.","deliverable_notes":"Your tested truth tables (photo of the setup or simulator) + 1 line on one gate combination that surprised you."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"An Oscillation I Measured","primary":"Construct a real oscillating system (pendulum, spring, torsion) and take enough of your own measurements to extract a physical constant (g, spring constant, or a modulus) with an error estimate.","support":"~400 words on your sources of error and how you reduced them.","llc":"Show your apparatus/data and predict, live, what changing one parameter does."},
      {"option_no":2,"title":"The Bending of a Real Beam","primary":"Measure the load–depression behaviour of a real beam/cantilever you set up, extract Young's modulus (or a stiffness), and compare to a known value for the material.","support":"~400 words on why your value differs from the book.","llc":"Defend your method when an examiner questions a measurement."},
      {"option_no":3,"title":"Thermodynamics in My Kitchen","primary":"Pick one real household thermal device or process, measure something about it (temperature vs time, cooling curve), and analyse it with the thermodynamic ideas of Unit III.","support":"~400 words on the first/second-law story of your device.","llc":"Present the curve and answer 'where does the energy go?'"},
      {"option_no":4,"title":"Mapping a Magnetic Field by Hand","primary":"Safely set up a current-carrying conductor or coil and map its magnetic field experimentally at many points, comparing the pattern to Biot–Savart / axial-field theory.","support":"~400 words on the match and mismatch.","llc":"Show your field map and predict the field at a new point."},
      {"option_no":5,"title":"Logic Gates I Built and Tested","primary":"Implement a small useful logic circuit (with real ICs, switches, or a simulator you drive yourself) — e.g. a two-input decision — verify all its truth-table rows by testing, and show NAND as a universal block.","support":"~400 words on how gates compose into decisions.","llc":"Demonstrate the circuit and add an input live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
