update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Observe a real interference/diffraction effect (a soap film's colours, a CD acting as a grating, light through a fine cloth) and record what you see; relate to thin-film or diffraction theory.","deliverable_notes":"Your photo of the real effect + 2 sentences explaining the colours/pattern with the physics of Unit I."},
      {"sno":2,"unit":"II","finks_dimension":"Foundational Knowledge","task":"For one element you choose, work out by hand the quantum numbers of its outer electrons and the applicable coupling/exclusion facts from the vector-atom model.","deliverable_notes":"Your hand-worked quantum-number assignment for the element + 1 line on what Pauli's principle forbade."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Using the semi-empirical mass formula, compute by hand the binding energy per nucleon for one named nuclide and compare with the published value.","deliverable_notes":"Your hand computation + the published value + 1 line on why they differ + 1 line on stability."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Work one special-relativity numerical (length contraction OR time dilation) by hand for a scenario you set up (a fast traveller you describe), showing the factor.","deliverable_notes":"Your hand computation with the scenario stated + 1 line on how large the effect is and why we don't notice it daily."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Examine a real diode or rectifier (from a discarded charger/adapter you open safely, or a simulator) and sketch its I–V behaviour; identify forward/reverse regions.","deliverable_notes":"Your sketch/observation of the real component + 1 line on where the diode conducts and where it blocks."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"Colours With No Pigment","primary":"Find and document several real structural-colour / interference / diffraction phenomena around you (soap films, oil sheens, CDs, insect wings), photograph them, and explain each quantitatively with wave optics.","support":"~400 words on why these colours aren't dyes.","llc":"Present your gallery and predict the effect of a change (film thickness, angle)."},
      {"option_no":2,"title":"The Binding Energy Story","primary":"For a family of nuclides you choose, compute binding energy per nucleon by hand via the mass formula, plot the curve, and locate the peak — connecting it to fusion vs fission.","support":"~400 words on why iron sits where it does.","llc":"Defend one computation and answer 'which reaction releases energy here?'"},
      {"option_no":3,"title":"Relativity You Can Compute","primary":"Set up a concrete high-speed scenario and work length contraction, time dilation and the twin situation by hand, then estimate the real speeds at which effects become noticeable.","support":"~400 words on why relativity is invisible in daily life.","llc":"Solve a fresh numerical live."},
      {"option_no":4,"title":"Inside a Real Rectifier","primary":"Safely open a discarded adapter/charger (or use a simulator you drive) to identify the diode/rectifier stage, characterise its behaviour, and explain how it turns AC into DC.","support":"~400 words tracing the signal through the circuit.","llc":"Show the component/trace and answer how a full-wave bridge differs."},
      {"option_no":5,"title":"An Atom's Fingerprint","primary":"Choose one element and build a complete account of its electronic structure (quantum numbers, coupling, exclusion) and, if possible, observe its spectral signature (flame test or a spectroscope you improvise).","support":"~400 words on how structure produces spectrum.","llc":"Present and answer a quantum-number challenge live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHGE2'
  and is_latest = true and is_archived = false;

-- ── 26UPHGEP01 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Perform the Young's-modulus (non-uniform bending) experiment yourself; record every reading in your own hand and compute the modulus with its error.","deliverable_notes":"Your raw observation table (signed/dated) + the computed Young's modulus + 1 line on your largest source of error."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Determine rigidity modulus by BOTH the static-torsion and torsional-oscillation methods and compare your two results for the same wire.","deliverable_notes":"Both observation tables + the two rigidity values + 1 line on which method you trust more and why."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Measure surface tension by the drop-weight method and viscosity by the graduated-burette method; note what property of the liquid each depends on.","deliverable_notes":"Your two result values with the liquid named + 1 line linking each to a molecular-level cause."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Calibrate a low-range voltmeter (or ammeter) against a potentiometer and record the correction at several points.","deliverable_notes":"Your calibration table + the correction curve (hand-drawn) + 1 line on why calibration matters."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Verify the truth tables of basic logic gates and De Morgan's theorems using ICs, and demonstrate NAND as a universal building block.","deliverable_notes":"Your verified truth tables (photo of the wired board) + 1 line proving NAND built one other gate."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"An Elastic Constant, Measured Two Ways","primary":"Determine an elastic constant (Young's or rigidity modulus) by two independent methods in the lab, with full error analysis, and reconcile the two values for the same specimen.","support":"~400 words on measurement uncertainty and how you controlled it.","llc":"Present your data and defend your error budget when challenged."},
      {"option_no":2,"title":"Properties of a Real Liquid","primary":"Choose one liquid and measure both its surface tension and viscosity yourself, then relate the numbers to something real about the liquid (why oil pours slowly, why water beads).","support":"~400 words connecting molecular behaviour to your readings.","llc":"Show the apparatus and predict a second liquid's behaviour."},
      {"option_no":3,"title":"The Instrument I Calibrated","primary":"Fully calibrate a meter against a potentiometer standard, produce a correction curve, and demonstrate the difference calibration makes to a real measurement.","support":"~400 words on why raw instrument readings can't be trusted.","llc":"Defend a correction value and apply it live."},
      {"option_no":4,"title":"A Logic Circuit I Verified from Scratch","primary":"Wire and verify a set of logic gates and De Morgan's identities on real ICs, then build one small useful function from NAND gates only, demonstrating universality.","support":"~400 words on how you debugged a wrong output.","llc":"Demonstrate the working board and add an input live."},
      {"option_no":5,"title":"My Lab Notebook, Defended","primary":"Across the whole practical, keep a rigorous hand-written lab record for at least four experiments with raw data, computations and errors, and select the one whose result you can most confidently defend.","support":"~400 words on what good experimental discipline looks like.","llc":"Present that experiment's data and answer 'how do you know this number is right?'"}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHGEP01'
  and is_latest = true and is_archived = false;

-- ── 26UPHGEP02 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Measure the thickness of a thin wire by the air-wedge interference method; record the fringe data yourself.","deliverable_notes":"Your fringe observation table + the computed thickness + 1 line on how interference made a tiny length measurable."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Determine the wavelength of mercury lines using a spectrometer and grating; record the angles for at least two lines.","deliverable_notes":"Your angle readings + the two wavelengths computed + 1 line on which colour bent most and why."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Find the refractive index of a solid prism by measuring the angle of minimum deviation yourself.","deliverable_notes":"Your minimum-deviation measurement + the refractive index + 1 line on what a higher index would do to the light."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Determine an unknown AC frequency using a sonometer, and separately the specific resistance of a wire using the Post Office box.","deliverable_notes":"Both result values with the specimens named + 1 line on the principle each relied on."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"For any one experiment above, repeat it three times and quantify the spread of your results.","deliverable_notes":"Your three repeat readings + the mean and spread + 1 line on whether the experiment is repeatable and why."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"Measuring the Invisible with Light","primary":"Use an interference or diffraction method (air wedge, grating) to measure something too small or too fine for a ruler — a wire's thickness or light's wavelength — with your own readings and error estimate.","support":"~400 words on how wave optics turns geometry into a measuring tool.","llc":"Show your fringe data and defend the computed value."},
      {"option_no":2,"title":"A Prism's Refractive Index, By My Own Angles","primary":"Determine a prism's refractive index via minimum deviation, take enough readings to estimate error, and connect the number to the prism's optical behaviour you can observe.","support":"~400 words on the physics of minimum deviation.","llc":"Reproduce a reading live and answer how index affects dispersion."},
      {"option_no":3,"title":"Two Quantities, Two Classic Methods","primary":"Measure an AC frequency (sonometer) and a wire's specific resistance (PO box) yourself, documenting the full method and error for each, and state what physical property each result reveals.","support":"~400 words on the elegance of null/comparison methods.","llc":"Defend one measurement when a parameter is questioned."},
      {"option_no":4,"title":"How Repeatable Is My Experiment?","primary":"Take one experiment and study its repeatability rigorously — many repeat runs, spread analysis, and identification of the dominant error source — treating measurement itself as the object of study.","support":"~400 words on random vs systematic error in your data.","llc":"Present your spread and answer how you'd tighten it."},
      {"option_no":5,"title":"The Spectrometer and What It Told Me","primary":"Use the spectrometer to measure the wavelengths of several spectral lines, build a small table, and relate the pattern to the source's physics.","support":"~400 words on how a spectrum encodes an element.","llc":"Show the readings and predict where a new line would sit."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHGEP02'
  and is_latest = true and is_archived = false;

-- ── 26UPHNM1 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Take one real mechanical object from your daily life (a bicycle, a spring scale at a named shop, a ball) and identify and measure one physical quantity that governs how it works.","deliverable_notes":"The named object + your measurement + 2 sentences on the mechanics that makes it work."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Examine a real optical item you own (spectacles, sunglasses, a camera, a magnifier) and determine one optical property (converging/diverging, polarising) by a simple test.","deliverable_notes":"The named item + your test and result + 1 line on the physics behind its purpose."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Read the power rating of three real home appliances (named) and estimate the energy one of them uses per day; check against a real electricity bill if available.","deliverable_notes":"The three appliances with ratings + your daily-energy estimate + 1 line comparing to a real bill or expectation."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Find a real solar device near you (a solar water heater, a garden light, a rooftop panel) and estimate the solar energy it captures using the solar-constant idea.","deliverable_notes":"The named device + your rough energy estimate + 1 line on how weather changes it."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Read about one Indian physicist from the syllabus and connect their real contribution to a device or idea you actually use.","deliverable_notes":"The physicist + the specific contribution + 2 sentences linking it to something in your own life."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Physics Inside One Thing I Use","primary":"Choose one real everyday device (fan, bulb, bicycle, microwave, spectacles) you own or can access, take real measurements of how it behaves, and build a clear physical explanation of how it works — verified by your own observation, not just description.","support":"~400 words on what surprised you when you looked closely.","llc":"Bring or show the device and answer 'what happens if...' live."},
      {"option_no":2,"title":"A Day of Energy in My Home","primary":"Audit the real energy use of your household appliances (named, with ratings and usage you record), estimate daily consumption, and check it against an actual bill — then propose one honest saving.","support":"~400 words on where the energy really goes.","llc":"Present your audit and defend your saving proposal."},
      {"option_no":3,"title":"Catching the Sun Where I Live","primary":"Study a real solar installation you can access (heater, panel, light), measure or estimate its output across conditions you observe, and assess how well it suits your locality's sunlight.","support":"~400 words on the solar-constant reality vs the marketing.","llc":"Present your estimate and answer a 'monsoon month?' challenge."},
      {"option_no":4,"title":"An Indian Physicist and My World","primary":"Research one Indian physicist deeply (using named sources) and trace their real scientific contribution to a specific technology or idea present in your own life — making the link concrete, not generic.","support":"~400 words on why their work mattered.","llc":"Present the connection and answer questions on the science."},
      {"option_no":5,"title":"Everyday Optics, Tested","primary":"Collect several real optical items and design simple tests to reveal each one's optical property (polarisation, focal behaviour, UV blocking), documenting your method and results.","support":"~400 words on the optics that everyday products quietly use.","llc":"Run one test live for the cohort."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHNM1'
  and is_latest = true and is_archived = false;

-- ── 26UPHNM2 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Observe the real night sky from a named location over two or three clear nights; identify and sketch the positions of at least three planets or bright bodies you can confirm.","deliverable_notes":"Your dated sky sketches (place named) + how you confirmed each object + 1 line on any motion you noticed."},
      {"sno":2,"unit":"II","finks_dimension":"Foundational Knowledge","task":"Track sunrise/sunset times or the Sun's shadow at a fixed named spot for several days and relate what you see to the Sun's real motion and layers you studied.","deliverable_notes":"Your dated observations + 2 sentences connecting them to the Sun's physical behaviour."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Document (from a real, dated, named source or your own observation if one occurs) one eclipse and explain its geometry with your own diagram.","deliverable_notes":"The eclipse event (date/source) + your hand-drawn Sun–Earth–Moon geometry + 1 line on why it was total/partial."},
      {"sno":4,"unit":"IV","finks_dimension":"Integration","task":"Summarise, in your own words with a hand timeline, the evidence for one theory of the universe's origin from named sources; note one piece of evidence you find persuasive.","deliverable_notes":"Your evidence timeline + the named sources + 1 line on the evidence you found strongest and why."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Identify a real constellation and, if possible, a variable or binary star in it; record its appearance and look up its type.","deliverable_notes":"Your sketch of the constellation (dated, place named) + the star you identified + its type + 1 line on how it differs from the Sun."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"My Own Sky Journal","primary":"Keep a real observational sky journal over at least two weeks from a named location — planets, the Moon's phases, a constellation's drift — with your own dated sketches, and explain the motions with the astrophysics of the course.","support":"~400 words on what direct observation taught you that a chart couldn't.","llc":"Present your journal and predict where an object will be next week."},
      {"option_no":2,"title":"The Geometry of an Eclipse","primary":"Study one real eclipse (past or upcoming, dated and sourced), reconstruct its Sun–Earth–Moon geometry with your own diagrams and reasoning, and explain the totality/partiality and path.","support":"~400 words on why eclipses are rare from any one place.","llc":"Draw the geometry live and answer 'why not every month?'"},
      {"option_no":3,"title":"How We Know the Universe Began","primary":"Build an evidence-based case for one origin theory (Big Bang vs steady-state vs pulsating) from NAMED scientific sources, weighing the real observational evidence (redshift, CMB, abundances) rather than asserting.","support":"~400 words on what would change your mind.","llc":"Defend your case against a devil's-advocate challenge live."},
      {"option_no":4,"title":"Reading a Star","primary":"Choose one real star or star type (variable, binary, giant), gather its properties from named sources, and compare it systematically to our Sun — what's bigger, hotter, older, and how we can tell.","support":"~400 words on how astronomers measure things they can't touch.","llc":"Present and answer a 'how do we know its distance?' question."},
      {"option_no":5,"title":"The Sun, Watched and Explained","primary":"Make your own safe, dated observations of the Sun's effects (shadow length, sunrise drift, seasonal angle) from a named place and connect them rigorously to the Sun's structure and Earth's motion.","support":"~400 words tying your observations to the physics.","llc":"Present your data and predict a future observation."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UPHNM2'
  and is_latest = true and is_archived = false;

-- ── 26UPHS01 · b-sc-physics ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Find ONE real measuring instrument in your life — a weighing scale at a shop, a fuel meter, a BP monitor — and test its accuracy against a known value.","deliverable_notes":"The named instrument + your accuracy check (measured vs known) in one line + a photo. The comparison number is the deliverable."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Find ONE real sensor around you — an automatic tap (IR), a door alarm, a weighing strain gauge, a phone proximity sensor — and figure out what physical change it senses.","deliverable_notes":"A photo of the named sensor + two sentences: what it senses and what it converts it into. No essay."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Use ONE real digital instrument — a digital multimeter, digital thermometer, digital pH meter, digital tachometer — and take three real readings.","deliverable_notes":"The instrument named + your three dated readings (your own table) + one line on what it measures and its least count."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Visit ONE place with real medical instrumentation — a clinic, hospital, or diagnostic lab near you — and observe ONE instrument (ECG, X-ray, BP monitor) in use (with permission).","deliverable_notes":"The named place + the instrument + two sentences on what body signal it captures and how the operator reads it. A photo if permitted."},
      {"sno":5,"unit":"V","finks_dimension":"Caring","task":"Find where gas or air quality is measured near you — an LPG leak detector, a vehicle emission-check centre, a hospital oxygen monitor — and learn who it protects.","deliverable_notes":"The named detector/analyzer + one line on what gas it measures and who is kept safe by it. Bring a photo or document if shared."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"One Real Instrument, Taken Apart by Me","primary":"Choose ONE real measuring instrument you can access — a weighing scale, digital thermometer, BP monitor, multimeter. Study it yourself: test its accuracy, find its sensor, photograph its parts, sketch how it works. Bring the instrument or your evidence.","support":"~400 words on its performance characteristics and error sources.","llc":"Demonstrate it, take a live reading, answer how it works."},
      {"option_no":2,"title":"The Sensor That Runs My Daily Life","primary":"Pick ONE real sensor you depend on — an automatic tap, a phone sensor, a vehicle sensor. Investigate what it senses and how; test its behaviour yourself (block the IR, tilt the phone). Bring your evidence.","support":"~400 words on the transducer principle.","llc":"Demonstrate the sensor's behaviour live and explain the physics."},
      {"option_no":3,"title":"A Medical Instrument and the Person It Reads","primary":"Visit a real clinic/lab (with permission), observe ONE medical instrument in use, and interview the operator (consent + phone-verifiable) about what it measures and how they read it. Bring their words + a photo if permitted.","support":"~400 words on the instrument's physics.","llc":"Tell the cohort what you saw and the operator's own account. AI cannot visit YOUR local clinic."},
      {"option_no":4,"title":"Testing an Instrument I Was Told to Trust","primary":"Pick ONE instrument whose reading people trust blindly — a shop scale, a fuel pump meter, a fever thermometer. Test its accuracy yourself against a known standard. Bring your comparison data.","support":"~400 words on whether it can be trusted and its error characteristics.","llc":"Present your accuracy test and defend your verdict."},
      {"option_no":5,"title":"The Detector That Keeps Someone Safe","primary":"Find ONE real safety-critical detector near you — an LPG leak alarm, an emission-check analyzer, an oxygen monitor. Study how it works and interview whoever maintains it (consent + contact). Bring their words + a photo.","support":"~400 words on the gas-analysis principle and the stakes.","llc":"Explain what it detects and who is protected."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
