  and is_latest = true and is_archived = false;

-- ── 26UTFC01 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Collect five different real fabric scraps from home or a tailor's cutting-floor: a cotton shirt, a silk saree border, a woollen sweater/shawl, a jute or gunny bag, and one shiny synthetic. Feel each between your fingers and, with an adult beside you, touch a single thread to a flame.","deliverable_notes":"Staple the five scraps (or a photo, your hand in frame) to a sheet + a hand-drawn table classifying each as natural or man-made, and cellulose, protein or synthetic. Write 3-4 sentences: which two felt alike, and which one the flame told apart from the rest."},
      {"sno":2,"unit":"II","finks_dimension":"Caring","task":"Regenerated fibres like viscose, modal, bamboo and lyocell are sold as 'eco' cloth. Find ONE real garment or bolt in your home or a named cloth shop in your town whose label says viscose, rayon, modal, bamboo or Tencel/lyocell.","deliverable_notes":"A clear photo of the actual label (shop name if from a store) + 3-4 sentences: why the fibre is marketed as earth-friendly, and one honest doubt you have about that claim after reading Unit II."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Take one stretchy garment (leggings, sports banian, elastic waistband) and one plain polyester garment. Stretch each and let go to test recovery; then, with an adult, melt a single loose thread of each and compare with a cotton thread.","deliverable_notes":"A hand-written data note: which sprang back, which melted into a hard bead versus which burned to soft ash, and the smell of each + your reading of which fibre (spandex, polyester, cotton) each thread is, with one line of reasoning."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Cotton becomes yarn through ginning, blow room, carding, drawing, combing and spinning. Talk to ONE real named person who handles cotton or yarn every day: a spinning-mill worker in the Erode-Komarapalayam belt, a cotton trader in Erode market, or a handloom weaver.","deliverable_notes":"Their name + a phone-verifiable contact + one sentence you quote in their own words + the process steps THEY named, written beside the textbook sequence so the two can be compared. Note one step the book lists that they never mentioned."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Pull one length of sewing thread or knitting yarn from a reel or an old garment. Untwist it over one inch and count the twists; note whether the spiral leans like an S or a Z. Find the count number printed on a sewing-thread reel (e.g. 40s/2).","deliverable_notes":"Your twists-per-inch number + S or Z + a hand sketch of the twist direction + 3-4 sentences on what happened to the yarn's strength when you fully untwisted it, and what the reel's count number tells you."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Fibre in My Family's Wardrobe","primary":"Pick five real garments from your own family's cupboard, identify each fibre by feel, a supervised burn test and the label, and mount the scraps on a specimen board with your verdicts.","support":"~400 words linking each fibre to its properties and end-uses from Units I-III.","llc":"Bring the board to the cohort and defend one identification the class challenges. AI can list fibre properties; it cannot burn-test YOUR grandmother's shawl."},
      {"option_no":2,"title":"The Cotton That Became My Shirt","primary":"Interview ONE named spinning-mill worker, cotton trader or weaver from the Erode-Tiruppur belt about how raw cotton turns into yarn; record their voice with consent and get a phone-verifiable contact.","support":"~400 words mapping their account onto Unit IV's process sequence.","llc":"Play their words and tell the cohort which step surprised you. AI can describe spinning; it cannot interview YOUR mill worker."},
      {"option_no":3,"title":"Twist, Count and Strength: One Yarn Measured by Me","primary":"Take one real yarn, measure its twists-per-inch, read or work out its count, and test how far it stretches before breaking by hand; tabulate every number.","support":"~400 words on how twist and count decide strength and end-use (hosiery, sewing thread).","llc":"Show the yarn and defend your break-test method under questions. AI cannot pull and snap YOUR thread."},
      {"option_no":4,"title":"Eco or Marketing? A Regenerated Fibre Investigated","primary":"Find a real bamboo, viscose or modal product with its label, and ask a NAMED shopkeeper in your town why they stock it and what customers believe about it; record the reply.","support":"~400 words weighing the eco-claim against the viscose process in Unit II.","llc":"Hold up the label and give the cohort your verdict. AI cannot question YOUR shopkeeper."},
      {"option_no":5,"title":"The Spinning Mill Near My Town","primary":"Visit or phone a real named spinning mill or weaving unit in the Salem-Erode-Kavandampatti area and document the exact machine sequence they run, with a photo or the operator's contact.","support":"~400 words comparing their real line to the blow-room-to-ring-frame sequence of Unit IV.","llc":"Present the sequence and name one machine you had never seen before. AI cannot walk YOUR local mill floor."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFC01'
  and is_latest = true and is_archived = false;

-- ── 26UTFC02 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Before weaving, yarn is wound onto cones, cheeses and pirns. Find one real wound package: a thread cone from a tailor, a sewing-machine bobbin from home, or a pirn/bobbin from a weaver in Bhavani or Chennimalai.","deliverable_notes":"The object (or a photo, in your hand) + a hand sketch of how the yarn crosses as it winds + 3-4 sentences naming the package type (cone, cheese, pirn or bobbin) and why yarn must be re-wound before it can be warped or woven."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Warp yarns are coated with size (starch paste, 'kanji') so they survive the loom's rubbing. Compare a brand-new unwashed shirt with a shirt washed many times by feeling the stiffness; or brush rice-starch on a length of thread and let it dry.","deliverable_notes":"A written note on the stiffness difference you felt (or the stiffened thread itself taped down) + 3-4 sentences on why warp yarn is sized before weaving and what one sizing defect from Unit II would do to the cloth."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"A loom does three primary jobs at once: shedding, picking and beat-up. Find a REAL loom in action, a handloom in Bhavani/Chennimalai/Kavandampatti, a weaver's powerloom, or a school table-loom, and watch one full pick being woven (a video will not do).","deliverable_notes":"A hand sketch of the loom + arrows marking where you saw the shed open, the weft go across, and the reed beat up + 3-4 sentences integrating how the three primary motions must time together for one row of cloth."},
      {"sno":4,"unit":"IV","finks_dimension":"Learning How to Learn","task":"Take three real fabrics: a plain cotton shirt, a denim or drill (twill), and a satin blouse or lining. With a needle or pick glass, separate warp from weft and read how the threads cross over and under in each.","deliverable_notes":"A hand-drawn weave diagram on graph squares for each fabric + the weave name (plain, twill, satin) + the ends-per-inch times picks-per-inch count for one of them + a short 'what I first read wrong' note showing how you corrected yourself."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Interview ONE named weaver in the Bhavani, Chennimalai, Komarapalayam or Erode area about the loom they actually run: is it a shuttle handloom, a powerloom, or does it use a dobby or jacquard for the border/design?","deliverable_notes":"The weaver's name + a phone-verifiable contact + one quoted sentence + which loom type from Unit V they operate + one thing they told you about weaving figured borders or shuttleless speed that the textbook does not mention."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"Reading the Weave in My Own Clothes","primary":"Pick four real garments, separate warp and weft on each with a pick glass, identify the weave, and build a specimen board with the swatch, a hand weave-diagram and warp/weft marked for each.","support":"~400 words linking weave structure to feel and use across Units III-IV.","llc":"Show the board and read one unknown swatch live under the glass. AI cannot un-weave YOUR shirt."},
      {"option_no":2,"title":"The Bhavani Weaver and the Loom","primary":"Interview a named handloom or powerloom weaver from Bhavani, Chennimalai or Komarapalayam about their loom and its motions; record their voice with consent and a phone-verifiable contact.","support":"~400 words mapping their loom onto the primary/secondary/auxiliary motions of Unit III.","llc":"Play their words and name the loom type to the cohort. AI cannot sit at YOUR weaver's loom."},
      {"option_no":3,"title":"EPI x PPI: One Fabric Counted by Me","primary":"Take one real woven fabric, count ends-per-inch and picks-per-inch over a marked square inch, and calculate its cover factor by hand.","support":"~400 words on what the counts and cover factor say about the cloth's density and end-use.","llc":"Show the fabric and defend your cover-factor arithmetic under questions. AI cannot count the threads in YOUR square inch."},
      {"option_no":4,"title":"From Cone to Cloth: The Preparatory Journey","primary":"Document the real winding, warping and sizing steps at a weaver's or relative's set-up with your own photos, or the equivalent at a school loom.","support":"~400 words tracing your photos through the preparatory sequence of Units I-II, naming one defect you looked for.","llc":"Walk the cohort through your photo sequence. AI cannot photograph YOUR preparatory shed."},
      {"option_no":5,"title":"Handloom vs Powerloom: Two Looms, One Town","primary":"Compare two real looms operated by two named people in your area, one slower and one faster, on speed, sound and cloth.","support":"~400 words on why shuttleless/powerlooms out-produce handlooms yet handloom survives, tied to Unit V.","llc":"Present the two looms and the trade-off you found. AI cannot stand between YOUR two looms."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFC02'
  and is_latest = true and is_archived = false;

-- ── 26UTFCP01 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Foundational Knowledge","task":"Using real fabric scraps (from a tailor's floor or an old cotton garment), stitch by hand or machine ONE plain seam with one seam finish (overcast or pinked edge) and ONE hem. Press each flat.","deliverable_notes":"The actual stitched samples, each labelled with your name and the technique + 3-4 sentences on where in a real garment you would use that seam finish and that hem, and which was harder to keep straight."},
      {"sno":2,"unit":"Lab 3-4","finks_dimension":"Application","task":"On real cloth, make one dart sample and one fullness sample (a gather, a pleat or a tuck of your choice). Press the dart to one side and set the gathers evenly.","deliverable_notes":"The two pressed fabric samples + 3-4 sentences on how a dart removes fullness to shape the body while gathers add fullness, and which unit of the wardrobe (blouse waist, skirt top) each would suit."},
      {"sno":3,"unit":"Lab 5-6","finks_dimension":"Integration","task":"Make one placket or fastener sample (a simple bound or faced placket) and set ONE simple sleeve into an armhole scrap so the curves meet cleanly.","deliverable_notes":"The two samples + 3-4 sentences on how you eased the sleeve cap into the armhole without puckers, integrating the seam skills from Lab 1-2 into a real garment section."},
      {"sno":4,"unit":"Lab 7-8","finks_dimension":"Learning How to Learn","task":"Follow a construction step-sheet (from your practical manual, a book, or a tailor's demonstration) to make ONE collar sample and ONE yoke sample. Note the exact step where you got stuck and how you solved it.","deliverable_notes":"The collar and yoke samples + a short 'stuck-and-solved' note naming the step that confused you, what you tried, and what finally worked, so a classmate could avoid the same mistake."},
      {"sno":5,"unit":"Lab 9","finks_dimension":"Human Dimension","task":"Watch a NAMED local tailor set a real pocket (a patch pocket or an in-seam pocket) onto a garment and ask why they do each step in that order. Then make your own pocket sample copying their method.","deliverable_notes":"The tailor's name + a phone-verifiable contact + one quoted tip in their words + your own pocket sample made their way + one sentence on what their hand did that the step-sheet never says."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"My Sample Book: Eight Techniques by My Hands","primary":"Compile a real bound sample book of eight sewn samples, seam, hem, dart, gather, placket, sleeve, collar and pocket, each on real cloth stitched by you and labelled.","support":"~400 words on where each technique is used and which fabric suits it.","llc":"Flip the book for the cohort and let them pick one seam to inspect the underside. AI cannot stitch YOUR sample book."},
      {"option_no":2,"title":"The Tailor's Pocket, Copied by Me","primary":"Watch a named tailor set a real pocket, record their method with a phone-verifiable contact, and reproduce it as your own sample.","support":"~400 words comparing their hand-method to the textbook steps of Lab 9.","llc":"Show both pockets, theirs described and yours made, and name the tip that mattered. AI cannot watch YOUR tailor's hands."},
      {"option_no":3,"title":"One Garment Section, Fully Constructed","primary":"Build one complete bodice-front section on real cloth carrying a dart, a placket and a collar joined correctly.","support":"~400 words on how the separate techniques integrate into one wearable panel.","llc":"Present the panel and defend the collar-to-neckline join under questions. AI cannot construct YOUR panel."},
      {"option_no":4,"title":"Fullness Made Visible","primary":"Make real pressed samples of every fullness type, dart, tuck, pleat, gather, flare, ruffle and godet, on cloth, mounted in order.","support":"~400 words on how each controls fullness and where it appears in real garments.","llc":"Show the mounted set and let the cohort match a sample to a garment. AI cannot press YOUR pleats."},
      {"option_no":5,"title":"Mending as Making: A Repaired Garment","primary":"Repair a real torn or worn family garment using seam, hem and patch techniques; keep before-and-after photos.","support":"~400 words on which techniques you chose and why, and what the garment means to its owner.","llc":"Show before/after and tell whose garment it was and why it was worth saving. AI cannot mend YOUR family's cloth."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFCP01'
  and is_latest = true and is_archived = false;

-- ── 26UTFCP02 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Foundational Knowledge","task":"Gather six real samples, cotton, silk, wool, polyester, viscose and nylon, from home, a tailor or a shop. With an adult present, burn a single thread of each and note the flame behaviour; then measure the yarn count of one sample by the weigh-and-length (or Beesley's) method from your lab.","deliverable_notes":"The six labelled samples + a burn-test data table (flame, smell, and residue: soft ash versus hard bead) + the count value you measured, with one line on which two fibres were hardest to tell apart."},
      {"sno":2,"unit":"Lab 3-4","finks_dimension":"Application","task":"Take ONE real woven fabric. Pull out a single yarn and measure its twists per inch; then, on a marked one-inch square, count ends-per-inch and picks-per-inch with a pick glass.","deliverable_notes":"The fabric swatch + your twist, EPI and PPI numbers written on it + one sentence on what the twist-per-inch value told you about the yarn that a single count number alone could not."},
      {"sno":3,"unit":"Lab 5-8","finks_dimension":"Learning How to Learn","task":"Collect real fabrics showing plain, twill (note whether the diagonal leans left or right) and satin/sateen. Hand-draft each weave on graph paper FIRST, from what you read in the cloth, before checking any reference diagram.","deliverable_notes":"Your hand-drawn weave drafts + the actual swatches taped beside them + the left/right twill direction marked + a 'what I drafted wrong first' note showing the correction you made after checking the reference."},
      {"sno":4,"unit":"Lab 9-11","finks_dimension":"Integration","task":"Find a real honeycomb or huck-a-back towel (kitchen or bath) and a crepe fabric. Do a drop test: place one water drop on each and time how fast it soaks in; also feel the drape.","deliverable_notes":"The swatches + your absorption timings + 3-4 sentences integrating the weave structure with its real job: why the honeycomb/huck cells drink water faster and dry you better than a flat plain weave."},
      {"sno":5,"unit":"Lab 12-15","finks_dimension":"Human Dimension","task":"Find a real fabric with ornamental weaving, an extra-warp or extra-weft bordered saree, a mock-leno, or a pile fabric (velvet or a terry towel), and ask a NAMED shopkeeper or weaver how that raised design is made.","deliverable_notes":"The fabric + the shopkeeper/weaver's name + a phone-verifiable contact + one quoted explanation + which ornamental weave from Lab 12-15 it is, and one thing they said about the extra threads that surprised you."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Full Fabric Analysis Sheet: One Cloth, Every Number","primary":"Take one real fabric and produce a complete analysis all measured by you, fibre, yarn count, twist, EPI x PPI, crimp, cover factor and weight per square yard.","support":"~400 words on what each number means for the cloth's use.","llc":"Bring the fabric and defend your cover-factor and weight calculations under questions. AI cannot weigh and count YOUR swatch."},
      {"option_no":2,"title":"Six Fibres, Six Flames","primary":"Build a burn-test identification board of six real fibres (cotton, silk, wool, polyester, viscose, nylon) with your own recorded flame, smell and residue data for each.","support":"~400 words on how each fibre's chemistry explains its flame behaviour.","llc":"Show the board and identify one unlabelled thread live from its burn. AI cannot smell YOUR burning threads."},
      {"option_no":3,"title":"The Weave Draft I Read by Hand","primary":"Draft four real weaves, plain, twill, satin and one figured, purely by reading the interlacing in swatches you collected.","support":"~400 words on how you distinguished each and where each is used.","llc":"Show swatch and draft side by side and read a new swatch on demand. AI cannot un-weave YOUR four fabrics."},
      {"option_no":4,"title":"Why This Towel Dries You: Weave and Function","primary":"Test real honeycomb/huck-a-back and plain fabrics for water absorption with timed drop tests and record the numbers.","support":"~400 words integrating weave structure with absorbency and drape.","llc":"Show the swatches and your timings and explain the winner. AI cannot time the drop soaking into YOUR towel."},
      {"option_no":5,"title":"The Figured Saree and Its Weaver","primary":"Find a real extra-warp/weft, mock-leno or pile fabric and interview a named weaver or shopkeeper on how the design is woven, with a phone-verifiable contact.","support":"~400 words tying their account to the ornamental weaves of Lab 12-15.","llc":"Show the fabric and play or read their explanation. AI cannot question YOUR saree's weaver."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFCP02'
  and is_latest = true and is_archived = false;

-- ── 26UTFDE01 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Measure ONE real named person, yourself, a sibling or a friend, taking the full set of body measurements with a real tape: bust/chest, waist, hip, shoulder, back width, sleeve length and more.","deliverable_notes":"The completed standardized measurement chart headed with the person's name + a photo of you taking one measurement (the tape visible in frame) + 3-4 sentences on which measurement was hardest to take accurately and the trick you used to steady it."},
      {"sno":2,"unit":"II","finks_dimension":"Learning How to Learn","task":"Using a drafting step-sheet from a book or manual, draft a basic bodice front and back block on paper for the measurements you recorded in Unit I. Work slowly and mark every point.","deliverable_notes":"The hand-drafted paper pattern (front and back) + a 'stuck-and-fixed' note naming the drafting step where your lines did not meet, what you had drawn wrong, and how you corrected it, so a classmate could learn from it."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Pin a piece of real muslin or old plain cloth onto a dress form or a willing person, keeping the lengthwise grain running straight down the centre, and drape a simple bodice front.","deliverable_notes":"A photo of the draped muslin with the grainline marked in pencil + 3-4 sentences on how the flat two-dimensional cloth became a three-dimensional shape over the body, and why keeping the grain straight mattered to the fit."},
      {"sno":4,"unit":"IV","finks_dimension":"Foundational Knowledge","task":"Take a real fabric. Find the selvedge, straighten one cut end by pulling a crosswise thread or tearing, and run a shrinkage test: mark a 10 cm square, wash and dry the cloth, then re-measure the square.","deliverable_notes":"Your before-and-after square measurements + a labelled note pointing out the selvedge and showing on-grain versus off-grain + 3-4 sentences on why fabric must be straightened and pre-shrunk before a pattern is cut on it."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Interview a NAMED tailor or boutique owner in your town about the ONE fitting alteration customers ask for most often, blouse too tight, sleeve too long, shoulder gaping, and how they alter the pattern to fix it.","deliverable_notes":"The tailor's name + a phone-verifiable contact + one quoted sentence + which pattern-alteration principle from Unit V their fix matches + one thing they do by eye that no measurement chart records."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Pattern Fitted to One Real Body","primary":"Measure one named person, draft their bodice block, cut it in muslin, fit it on them and record every adjustment you made.","support":"~400 words connecting the alterations to measurement and grain principles from Units I-IV.","llc":"Show the muslin and defend one alteration the cohort questions. AI cannot fit a muslin on YOUR named person's shoulders."},
      {"option_no":2,"title":"The Tailor's Most-Asked Alteration","primary":"Interview a named tailor about the fitting problem customers bring most, record their fix with a phone-verifiable contact, and reproduce the alteration on a paper pattern.","support":"~400 words tying their fix to Unit V's alteration principles.","llc":"Play their words and demonstrate the pattern change. AI cannot interview YOUR tailor."},
      {"option_no":3,"title":"Grain, Shrink, Straighten: A Fabric Prepared by Me","primary":"Prepare one real fabric for cutting, locate selvedge, straighten the ends, and run a measured shrinkage test with recorded before/after numbers.","support":"~400 words on why grain and shrinkage decide whether a garment hangs true.","llc":"Show the fabric and your shrink data and defend the numbers. AI cannot wash and re-measure YOUR cloth."},
      {"option_no":4,"title":"From Flat Paper to Draped Cloth","primary":"Drape a simple bodice in real muslin on a form or person, keeping grain straight, and photograph each stage.","support":"~400 words on how draping turns two dimensions into three and where it beats flat drafting.","llc":"Show the draped muslin and walk the cohort through your grain decisions. AI cannot pin muslin onto YOUR dress form."},
      {"option_no":5,"title":"Grading One Size Up: A Block Regraded by Hand","primary":"Take one basic block and grade it one full size up by hand, proving each grade increment with measurements.","support":"~400 words on how manual grading distributes growth across the pattern.","llc":"Overlay the two graded patterns for the cohort and defend one increment. AI cannot pencil YOUR graded lines onto real paper."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFDE01'
  and is_latest = true and is_archived = false;

-- ── 26UTFDE04 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Human Dimension","task":"Visit a NAMED tailor, boutique or small garment/knitwear unit (the Tiruppur belt is full of them) and watch how cloth is spread in layers and cut. Ask which cutting tool they use and why.","deliverable_notes":"The unit or tailor's name + a phone-verifiable contact + a photo of the cutting tool or table + which cutting method they use (scissors, straight knife, round knife or band knife) + one quoted reason they gave for choosing it."},
      {"sno":2,"unit":"II","finks_dimension":"Foundational Knowledge","task":"Take three real garments and, with a magnifier, hunt for the stitch types: a lockstitch seam (looks the same on both sides), an overlock/serged edge (looped thread on the inside seams of a T-shirt), and if you can find one, a flatlock.","deliverable_notes":"The garments (or photos) with each stitch circled and named + 3-4 sentences on how you told a lockstitch from an overlock by looking, and where each stitch is used in a real garment."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Examine ONE real sewing machine, a home tailoring machine, a relative's, or a tailor's, up close. Identify its bed type (flat, cylinder or post) and watch the feed dog teeth move the cloth as the needle works.","deliverable_notes":"A photo or sketch of the machine with the bed type labelled + 3-4 sentences on how the feed dog moves the fabric forward stitch by stitch, and what kind of garment that bed shape suits."},
      {"sno":4,"unit":"IV","finks_dimension":"Learning How to Learn","task":"Collect two or three real machine needles (or study a tailor's needle packet) and read the size numbers printed on them; then find one specialized presser foot (a zipper foot, a hemmer or a piping foot).","deliverable_notes":"A photo of the needles and foot + the exact size numbers you read + a short 'what the numbers mean' note you worked out about needle size versus fabric weight, showing how you taught yourself the sizing system."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Take ONE newly bought garment still carrying its finishing, tags, folds, pins, tissue and poly bag. Before you remove anything, study every finishing and packing element the factory added.","deliverable_notes":"A photo of the garment as it was packed + a list of every finishing step you can infer (was the collar fused? the belt loops bar-tacked? the garment pressed and folded to size?) + 3-4 sentences integrating how finishing and packaging shape the customer's first impression."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"Inside One Sewing Machine","primary":"Fully document one real sewing machine, its bed, feed mechanism, needle, presser foot and thread path, with your own photos and labelled sketches.","support":"~400 words on how each part contributes to forming a stitch, tied to Units III-IV.","llc":"Demonstrate the thread path (or defend your feed-type identification) before the cohort. AI cannot photograph the feed dog on YOUR machine."},
      {"option_no":2,"title":"The Cutting Room I Visited","primary":"Visit a named tailor or garment unit, watch spreading and cutting, and record the tool and method with a phone-verifiable contact.","support":"~400 words on why that cutting tool suits their work, tied to Unit I.","llc":"Present your photos and name the cutting machine to the cohort. AI cannot stand in YOUR local cutting room."},
      {"option_no":3,"title":"Stitch Detective: Five Seams Decoded","primary":"Identify the stitch type on five real garment seams (lockstitch, overlock, flatlock, chainstitch) using a magnifier, marking each.","support":"~400 words on how each stitch is formed and why the factory chose it there.","llc":"Show the garments and let the cohort test you on one hidden seam. AI cannot magnify the seams in YOUR wardrobe."},
      {"option_no":4,"title":"How My Shirt Was Finished and Packed","primary":"Deconstruct the finishing and packing of one real bought garment, listing every fusing, pressing, tagging and packaging element before removing them.","support":"~400 words integrating Unit V's finishing sequence with what you found.","llc":"Show the garment as-packed and walk the cohort through the finishing you inferred. AI cannot unwrap YOUR new shirt."},
      {"option_no":5,"title":"Needles, Feet and Attachments: A Machine Toolkit Mapped","primary":"Catalogue real machine needles (with their size numbers) and presser feet/attachments you can find, photographed and explained.","support":"~400 words on how needle size and each foot match specific fabrics and operations.","llc":"Show the toolkit and match one foot to a job on request. AI cannot read the numbers off YOUR real needles."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFDE04'
  and is_latest = true and is_archived = false;

-- ── 26UTFDE05 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Test the water at your home (hardness by lather test with a named soap) and compare washing results in it vs softened water on a real fabric swatch.","deliverable_notes":"Your lather-test observation + the two washed swatches (photo) + 1 line on how hardness affected cleaning."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Take three real stains you create on identical fabric swatches (e.g. turmeric, ink, oil) and remove each by a method you choose; record what worked.","deliverable_notes":"Your before/after swatch photos for all three stains + the method used for each + 1 line on the hardest stain."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Read the real wash-cycle options on an actual washing machine (named) and match two garments' care needs to the correct cycle and drying method.","deliverable_notes":"The machine's cycle list + your two garment-to-cycle matches with reasons + 1 line on a wrong cycle's likely damage."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Launder three real fabrics of different types (cotton, silk/rayon, wool) each by its correct method, and record how each responded.","deliverable_notes":"Your method and result for each real fabric + 1 line on the fabric that needed the most care and why."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Collect and read the real care labels from five of your own garments; decode the symbols and check whether they're actually being followed at home.","deliverable_notes":"Photos of the five real labels + your decoding + 1 line on one label instruction your household ignores."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Textile-Care Manual I Tested","primary":"Build a practical care-and-maintenance manual for a real wardrobe or a named person's garments, where EVERY recommendation is backed by a test YOU ran on real swatches or garments (stain removal, wash method, water effect).","support":"~400 words on where common household practice is wrong.","llc":"Show your tested swatches and defend one counter-intuitive recommendation."},
      {"option_no":2,"title":"The Stain-Removal Trials","primary":"Run a controlled set of real stain-removal experiments (multiple stains × multiple methods on identical swatches), document outcomes with photos, and derive an evidence-based stain guide.","support":"~400 words on the chemistry of why methods worked.","llc":"Remove a fresh stain live and predict the result."},
      {"option_no":3,"title":"Right Fabric, Right Care","primary":"Take several real fabrics of different fibre types, launder each correctly and one incorrectly on purpose, and document the damage that wrong care causes — turning it into a fibre-specific care chart.","support":"~400 words on fibre properties driving care rules.","llc":"Match a mystery fabric to its care needs live."},
      {"option_no":4,"title":"Reading the Care Label Nobody Reads","primary":"Collect real care labels from many garments, decode the full symbol system, and audit whether a real household actually follows them — then produce a simple guide to close the gap.","support":"~400 words on the cost of ignoring labels.","llc":"Decode a fresh label live and answer what happens if it's disobeyed."},
      {"option_no":5,"title":"Hard Water and the Clothes We Wash","primary":"Investigate your real local water's effect on laundry through controlled washing tests (hard vs softened, different detergents/soaps), measuring cleaning and fabric feel.","support":"~400 words on softening methods and their trade-offs.","llc":"Present your swatches and recommend a detergent for your water."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFDE05'
  and is_latest = true and is_archived = false;

-- ── 26UTFDE06 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Collect the real accessories from three of your own garments (buttons, hooks, decorative trims) and classify each as basic/decorative/finishing.","deliverable_notes":"Photos of the real accessories + your classification + 1 line on the accessory that does the most functional work."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Examine real sewing threads (unpick a few cm from spare garments) and compare their construction and ticket number; test relative strength by hand.","deliverable_notes":"Your thread samples + construction/ticket notes + your strength-test result + 1 line on which suits heavy fabric."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Study a real zipper and a real button closure from garments you own; document their parts and test one quality parameter (e.g. zipper pull smoothness, button-hold).","deliverable_notes":"Your labelled photos of both closures + your quality test and result + 1 line on a failure you'd watch for."},
      {"sno":4,"unit":"IV","finks_dimension":"Integration","task":"Find real examples of lining/interlining/fusing in a garment (a shirt collar, a blazer, a bag) and explain what each supporting trim does for the garment's structure.","deliverable_notes":"Photos of the real supporting trims + your explanation of each one's job + 1 line on what the garment would be like without it."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Examine the real packing accessories on a purchased garment (tags, poly bag, hanger) and assess them against the quality/testing norms you studied.","deliverable_notes":"Photos of the real packing accessories + your quality assessment + 1 line on one export norm you can now recognise."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"An Accessory Teardown","primary":"Take several real garments and systematically 'tear down' their accessories and trims — identifying, classifying, and quality-testing each closure, thread, and supporting trim — to build an evidence-based accessory reference from actual objects.","support":"~400 words on which accessory choices most affect a garment's life.","llc":"Present your samples and identify a mystery accessory's purpose live."},
      {"option_no":2,"title":"Threads Under Test","primary":"Gather real sewing threads of different constructions and run your own comparative tests (strength, ticket number, suitability for named fabrics), producing a thread-selection guide.","support":"~400 words on why thread choice matters to seam durability.","llc":"Match a thread to a fabric live and justify it."},
      {"option_no":3,"title":"Closures That Hold — or Fail","primary":"Study real zippers, buttons, and elastic closures from actual garments, test their quality parameters, and document a real or induced failure and its cause.","support":"~400 words on quality requirements and testing.","llc":"Assess a fresh closure's quality live."},
      {"option_no":4,"title":"The Hidden Structure of a Garment","primary":"Investigate the supporting and decorative trims (lining, interlining, fusing) inside real structured garments, document what each does, and demonstrate — by comparison — how the garment behaves with and without proper support.","support":"~400 words on invisible trims doing visible work.","llc":"Show your examples and explain a chosen trim's role."},
      {"option_no":5,"title":"From Factory to Shelf: Packing Accessories","primary":"Examine the real packing accessories of purchased garments against export quality/testing norms, and assess whether they meet the standards you studied — identifying one that falls short.","support":"~400 words on why packing norms exist for export.","llc":"Assess a garment's packing accessories live against the norms."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFDE06'
  and is_latest = true and is_archived = false;

-- ── 26UTFFP01 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Foundational Knowledge","task":"Pick three real garments from your cupboard and hand-sketch their actual collar, sleeve and neckline shapes, drawing exactly what you see in front of you, not from imagination.","deliverable_notes":"The three hand-drawn sketches (pencil, on paper) + the garment names beside each + one sentence per sketch naming the collar, sleeve or neckline type you drew (e.g. Peter Pan collar, puff sleeve, boat neck)."},
      {"sno":2,"unit":"Lab 3-4","finks_dimension":"Application","task":"Lay ONE real ladies' top, shirt or pant flat in front of you and hand-sketch it as a technical flat, getting the proportions and every seam, pocket and button to match the real garment.","deliverable_notes":"The flat sketch + a photo of the actual garment placed beside your drawing + 3-4 sentences on what proportion or detail was hardest to get right and how you measured or checked it by eye."},
      {"sno":3,"unit":"Lab 5-6","finks_dimension":"Caring","task":"Hand-sketch ONE real accessory or ornament that belongs to your family, a grandmother's earring or bangle, a worn pair of slippers, a jute market bag, observing it closely as you draw.","deliverable_notes":"The detailed hand sketch + whose object it is + 3-4 sentences on the object's story or meaning to your family and one small detail you noticed only because you had to draw it."},
      {"sno":4,"unit":"Lab 7-8","finks_dimension":"Human Dimension","task":"Ask a NAMED real person, a friend or family member, to sit for you, and draw their face from life in two views: a front view and either a three-quarter turned view or a profile.","deliverable_notes":"The two face sketches + the person's name + 3-4 sentences on how the features shifted between the front and the three-quarter/profile view, and which feature was hardest to place."},
      {"sno":5,"unit":"Lab 9-10","finks_dimension":"Learning How to Learn","task":"Teach yourself the fashion-figure proportion system: draw a natural lay figure at 7 1/2 heads tall, then an elongated fashion figure at 8 or 10 heads, using the head height as your measuring unit throughout.","deliverable_notes":"Both hand-drawn figures with the head divisions ruled and numbered + a short 'what I learned about proportion' note explaining how stretching the leg length changes the figure, showing how you worked out the system."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"My Sketchbook: A Face I Know, Drawn From Life","primary":"Draw a portrait series of ONE named real person who sits for you, front, three-quarter and profile, plus a study of their hands.","support":"~400 words on how the features changed with each view and what life-drawing taught you that copying cannot.","llc":"Hold the sketches beside a photo of the person and defend the likeness. AI cannot draw YOUR friend from a real sitting."},
      {"option_no":2,"title":"The Heirloom I Drew","primary":"Illustrate in detail one real family ornament or accessory, observed closely from the object itself.","support":"~400 words on the object's story and the details you noticed only through drawing.","llc":"Show the sketch and, if allowed, the object, and tell its story to the cohort. AI cannot draw the wear marks on YOUR grandmother's bangle."},
      {"option_no":3,"title":"A Real Garment, Illustrated Flat","primary":"Produce a technical flat of one real garment laid before you, every seam, dart and closure to true proportion.","support":"~400 words on how you kept the proportions honest and where a flat differs from a fashion sketch.","llc":"Show flat and garment side by side and defend one proportion. AI cannot measure YOUR garment by eye."},
      {"option_no":4,"title":"The Fashion Figure I Built From Nothing","primary":"Draw a full croqui using the head-height proportion system, lay figure and fashion figure, with divisions marked, developed by your own hand.","support":"~400 words on how you learned the proportion system and where you stumbled.","llc":"Show the figures and explain the head-count method live. AI cannot rule YOUR proportion lines on paper."},
      {"option_no":5,"title":"Ten Details From My Wardrobe","primary":"Draw a plate of ten garment details, collars, sleeves, necklines and skirt shapes, each copied from a real garment you own and named.","support":"~400 words classifying the details and noting which real garment each came from.","llc":"Present the plate and match three details to their source garments. AI cannot copy the details from YOUR real clothes."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFFP01'
  and is_latest = true and is_archived = false;

-- ── 26UTFNMP01 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Application","task":"Walk to ONE real shop near you that has a weak or no proper logo - a named tea stall, tailor, or provision store (say, a shop on Kumarapalayam bus-stand road). Ask the owner's permission, note the real shop name and what it sells, then hand-sketch three rough logo thumbnails on paper BEFORE opening any software.","deliverable_notes":"The three hand-drawn thumbnails (pencil on paper, your hand or the shop in frame) + the shop's real name and owner's phone number + 3-4 sentences: what the shop sells, which thumbnail you chose, and why that mark fits this shop and no other."},
      {"sno":2,"unit":"Lab 3","finks_dimension":"Foundational Knowledge","task":"For the SAME real shop, design its visiting card, letter-pad and envelope in the software - but first measure a real visiting card you already own with a ruler (in mm) and rebuild those exact dimensions.","deliverable_notes":"A photo of the real card beside your ruler + your exported set at the same size + 3-4 sentences naming the card size in mm you found and one thing (logo, colour, or font) you kept identical across all three pieces."},
      {"sno":3,"unit":"Lab 4","finks_dimension":"Integration","task":"Design a one-page calendar, a product label and a hang-tag for the same shop, using ONE photograph you take yourself of the shop or its product.","deliverable_notes":"Your own photograph (not downloaded) + the three exported pieces + 3-4 sentences on how you reused the single photo across all three and how the label and tag both speak to the same buyer."},
      {"sno":4,"unit":"Lab 5-6","finks_dimension":"Caring","task":"Go to Erode cloth market or a local flower/garland stall, photograph ONE arrangement of colours that stops you, then rebuild that exact colour set in the software and name its harmony (monochromatic, analogous, complementary, split-complementary, triad, tetrad, or double-complementary).","deliverable_notes":"Your photo of the real colours + a swatch strip you built to match + 3-4 sentences naming the harmony type, the feeling those colours gave you at the stall, and where you would use that palette."},
      {"sno":5,"unit":"Lab 7","finks_dimension":"Human Dimension","task":"Photograph ONE real hand-made thing near you that already uses design principles - a kolam a paati drew this morning, an embroidered blouse, a temple gopuram - and mark on the photo where you see balance, rhythm, emphasis, proportion and harmony.","deliverable_notes":"The marked-up photo (arrows and labels in your own hand) + who made the object and where + 3-4 sentences: which principle is strongest, which is weak or missing, and what the maker wanted your eye to see first."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Shop That Had No Face","primary":"Adopt ONE real, named local shop with weak or no branding (owner's phone verifiable). Build its full identity - logo, card, letter-pad, label, tag - from your own photos and hand thumbnails, and record the owner's brief in their own words.","support":"~400 words on your choices and the owner's reaction.","llc":"Show the before/after to the cohort and faculty and defend why each colour and mark suits THIS shop and not any other."},
      {"option_no":2,"title":"A Palette Stolen From My Street","primary":"Photograph seven colour arrangements on ONE real street or market in Komarapalayam or Erode, then build seven small design pieces, each using one of the seven harmony schemes drawn from one real photo. Bring all seven photo-swatch pairs.","support":"~400 words naming each harmony and its real source.","llc":"Hold up each photo-swatch pair for the cohort and name its harmony live, taking questions on your matches."},
      {"option_no":3,"title":"Designed for One Real Buyer","primary":"Interview ONE named neighbour who would actually buy from a local shop (verifiable). Design a label, tag and calendar aimed only at them, quoting what they said they look for.","support":"~400 words linking each choice to their words.","llc":"Play or read the buyer's own words to the cohort and show how the design answers them, defending any choice they questioned."},
      {"option_no":4,"title":"The Principle in My Grandmother's Kolam","primary":"Photograph a real hand-made local object across several days (a paati's daily kolam, a weaver's border) and dissect its use of balance, rhythm, emphasis, proportion and harmony; then design your own piece that borrows one principle.","support":"~400 words on what you found.","llc":"Show the source object and your piece side by side to the cohort and defend the borrowed principle under questions."},
      {"option_no":5,"title":"From Pencil to Pixel","primary":"Keep every dated hand-drawn thumbnail and rough you made this term for one real local brand, then show the final software version beside them.","support":"~400 words on how the idea changed from paper to screen.","llc":"Fan out the full paper trail for the cohort and faculty and defend one decision the software could never have made for you."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFNMP01'
  and is_latest = true and is_archived = false;

-- ── 26UTFNMP02 · b-sc-textile-and-fashion-designing ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"Lab 1-2","finks_dimension":"Foundational Knowledge","task":"On a real 20 cm x 20 cm piece of cotton from home or a local tailor's scrap bin, hand-stitch five basic stitches - running, back, stem, chain and satin - with needle and thread only, no machine.","deliverable_notes":"The physical stitched sampler (bring it, or a close-up photo with a ruler beside it) + where the cloth came from + 3-4 sentences naming which stitch was hardest to keep even and what you changed to fix it."},
      {"sno":2,"unit":"Lab 3-4","finks_dimension":"Caring","task":"Find ONE real embroidered or woven motif near you - on a paati's old blouse, a temple cloth, a Chennimalai handloom border - sketch it by hand, then embroider your own version of it.","deliverable_notes":"Your hand sketch of the original + your stitched motif + who owns the original and where it is + 3-4 sentences on what the motif traditionally means here and one stitch choice you made to copy its look."},
      {"sno":3,"unit":"Lab 5-6","finks_dimension":"Application","task":"Paint ONE design onto a real cloth (handkerchief, dupatta, pillow cover) using fabric paint and at least two techniques - flat fill, shading, or block - then heat-set it as instructed.","deliverable_notes":"The painted cloth itself (or a daylight photo, your hand in frame) + 3-4 sentences on which technique held colour best after setting and one mistake in bleeding or drying that you learned from."},
      {"sno":4,"unit":"Lab 7-8","finks_dimension":"Integration","task":"Choose one colour harmony (monochrome, analogous, complementary or triad) and make a small panel - painted or stitched - that uses ONLY that harmony, matching your threads and paints to a real object you photograph.","deliverable_notes":"Your reference photo + the finished panel + a hand-drawn swatch of the threads/paints used + 3-4 sentences naming the harmony and whether the real fabric colours matched what you expected on screen."},
      {"sno":5,"unit":"Lab 9-10","finks_dimension":"Human Dimension","task":"Turn your stitched and painted samples into ONE real usable article a named person will actually use - a cushion cover for your mother, a pouch for a friend - and give it to them.","deliverable_notes":"A photo of the finished article in the hands of the named person who received it + their one-line spoken reaction + 3-4 sentences on what you would change if you made a second one for them."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"Stitched by My Own Hand","primary":"Build a physical sampler book of at least eight hand stitches on real cloth, each labelled and dated; bring the book.","support":"~400 words on tension, evenness and what each stitch is good for.","llc":"Pass the sampler around the cohort and faculty and defend your tension and neatness under close questioning - a photo cannot fake a real stitch line."},
      {"option_no":2,"title":"The Motif That Runs in My Family","primary":"Interview ONE named elder (paati, aunt or weaver; phone-verifiable) about a stitch or motif they know by heart; record their voice with consent; then reproduce that motif by hand.","support":"~400 words connecting their craft to what you studied.","llc":"Play their words and show your reproduction beside your sketch of theirs, telling the cohort what they taught you."},
      {"option_no":3,"title":"Painted, Set, and Worn","primary":"Hand-paint a real wearable or usable cloth item, heat-set it, then actually use or gift it to a named person; bring the item back after real use.","support":"~400 words on technique and durability.","llc":"Show the item, including any wear or fading, and defend your setting method to the cohort under questions."},
      {"option_no":4,"title":"A Harmony I Can Touch","primary":"Pick one colour harmony, source real threads and paints to match a photographed local object, and make a panel that proves the harmony in physical thread.","support":"~400 words on how screen colour differed from fabric colour.","llc":"Hold the panel and its source photo up for the cohort and name the harmony live, defending your matches."},
      {"option_no":5,"title":"Needle vs. Machine","primary":"Stitch the same small motif twice - once fully by hand, once on any machine you can borrow - and compare them physically.","support":"~400 words on where the hand won and where the machine won.","llc":"Show both to the cohort and defend which you would choose for a real paying customer and why."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UTFNMP02'
  and is_latest = true and is_archived = false;

-- ── 26UVCC01 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Watch ONE real conversation happen in front of you - a vendor and buyer bargaining at the santhai, a teacher and a student - for two minutes and map it onto the SMCR model (Source, Message, Channel, Receiver).","deliverable_notes":"A hand-drawn SMCR diagram filled in with the real people you watched + where and when + 3-4 sentences naming the channel used and one point where the message nearly broke down."},
      {"sno":2,"unit":"II","finks_dimension":"Integration","task":"Find ONE real Tamil sign, poster or wall painting near you (shop board, film banner, temple notice), photograph it, and write its denotation (what it literally shows) and its connotation (what it makes a local person feel).","deliverable_notes":"Your photo of the real sign + where it stands + 3-4 sentences separating denotation from connotation and naming ONE barrier (language, culture, noise) that could make an outsider misread it."},
      {"sno":3,"unit":"III","finks_dimension":"Human Dimension","task":"Sit with ONE named family member or friend for five minutes and practise active listening - no phone, no interrupting - while quietly noting their body language (hands, eyes, posture).","deliverable_notes":"Your hand-written notes of the gestures you saw + who you sat with + 3-4 sentences on one thing their body said that their words did not, and how your listening changed the talk."},
      {"sno":4,"unit":"IV","finks_dimension":"Caring","task":"Recall ONE real disagreement you had recently with a named person; write down what each of you actually said, then label each of your own lines as assertive, passive, aggressive or passive-aggressive.","deliverable_notes":"Your line-by-line transcript from memory (names or initials) + 3-4 sentences on which style you overused and one assertive sentence you could have said instead to protect the relationship."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Stand in a real room (your home, a classroom) and deliver a two-minute persuasive talk to at least ONE live listener about something you genuinely want them to do.","deliverable_notes":"A phone photo or short clip of you speaking to a real listener + the listener's name + 3-4 sentences on your opening line, one moment of nervousness, and whether the listener was actually persuaded."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Argument I Lost","primary":"Interview ONE named person you once clashed with (phone-verifiable) about how THEY remember the same disagreement; record with consent; compare their memory to yours.","support":"~400 words using nonverbal, listening and conflict-style ideas from Units III-IV.","llc":"Play a clip for the cohort and tell them what hearing their version taught you about your own communication."},
      {"option_no":2,"title":"Read Without Words","primary":"Observe ONE named market vendor or shopkeeper for 20 minutes (with permission) and document their nonverbal repertoire - how they greet, bargain and refuse - in a hand log.","support":"~400 words.","llc":"Perform two of their real gestures and have the cohort guess the meaning, then reveal what you learned."},
      {"option_no":3,"title":"The Sign My Village Reads","primary":"Photograph five real local signs or wall paintings and interview ONE passer-by per sign about what it means to them, capturing the gap between denotation and connotation.","support":"~400 words.","llc":"Show the signs to the cohort and quote the real readers, defending your barrier analysis."},
      {"option_no":4,"title":"Two Minutes That Moved Someone","primary":"Deliver a real persuasive talk to a real, named small audience to get a real outcome (join a clean-up, change a habit); capture their before/after answer.","support":"~400 words on structure and anxiety.","llc":"Re-deliver the talk live to the cohort and report the real result you got."},
      {"option_no":5,"title":"The Listener I Became","primary":"For one week keep a dated log of five real conversations where you practised active listening, noting one change each time; get one partner (named) to confirm you truly listened.","support":"~400 words.","llc":"Read your partner's confirmation to the cohort and defend your hardest listening moment."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCC01'
  and is_latest = true and is_archived = false;

-- ── 26UVCC02 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Choose ONE real object you find beautiful and ONE you find ugly from your own home or street; photograph both and break each down by the elements of visual art (line, shape, colour, texture, form, space).","deliverable_notes":"Both real photos + 3-4 sentences naming which elements make one 'beautiful' to you and testing whether that beauty is objective or subjective - your reaction versus what a neighbour might feel."},
      {"sno":2,"unit":"II","finks_dimension":"Caring","task":"Visit ONE real temple, mandapam or old building near you - name it (Bhavani Sangameswarar, Tiruchengode Ardhanareeswarar, a village temple) - and photograph ONE piece of its painting or sculpture.","deliverable_notes":"Your photo of the real artwork + the temple's name and where + 3-4 sentences on which story or deity it shows and why this local art deserves as much care as the famous Ajanta or Madras Art Movement works you studied."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Pick ONE Western movement (Impressionism, Cubism, Surrealism or Pop) and find ONE real thing around you - an ad, a shop mural, a phone wallpaper - that echoes its look; place both on a hand-drawn timeline.","deliverable_notes":"Your hand-drawn timeline with the movement and your real found example pinned to it + where you found it + 3-4 sentences connecting the two and naming what the movement first broke away from."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Find ONE real social issue in your own town (water, waste, traffic, a demolished building) and sketch by hand how a contemporary installation or data artist (like Shilpa Gupta or Chris Jordan) might make people feel it.","deliverable_notes":"Your hand sketch of the imagined artwork + the real local issue and where it is + 3-4 sentences on what emotion you want a viewer to leave with and one real material from your town you would build it from."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Take ONE real advertisement or poster you can physically hold and run it through Panofsky's three levels - what you literally see, what it conventionally means, and its deeper cultural meaning.","deliverable_notes":"The actual poster or ad (or a photo) + your three-level written breakdown + 3-4 sentences on Barthes' 'rhetoric of the image' - what it is quietly trying to make you believe."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"The Art on My Own Street","primary":"Document ONE real local artwork (temple mural, sign painting, hero-stone) and interview its maker or caretaker (named, verifiable) about it; record with consent.","support":"~400 words placing it against the movements you studied.","llc":"Show the work to the cohort and play the caretaker's own words, defending its place in art history."},
      {"option_no":2,"title":"Beauty, Argued","primary":"Photograph ten real objects and survey five named people on which are beautiful and why; tabulate the disagreements to test objectivism versus subjectivism.","support":"~400 words.","llc":"Present the split to the cohort and defend your own aesthetic stand against their challenges."},
      {"option_no":3,"title":"A Movement, Found Locally","primary":"Build a physical or photo board pairing five studied art movements with five real things you found in Erode or Salem that echo them.","support":"~400 words justifying each pairing.","llc":"Walk the cohort and faculty through the board and take challenges on every pairing."},
      {"option_no":4,"title":"The Issue I Made Visible","primary":"Pick a real local issue, gather real materials, photos and measurements about it, and build a small physical artwork or data piece that makes it felt.","support":"~400 words on your concept and materials.","llc":"Install it for the cohort and defend your material and emotional choices."},
      {"option_no":5,"title":"Reading One Image to the Bone","primary":"Choose one real, physically-held image (family photo, ad, poster) and analyse it fully through Wolfflin, Panofsky and Barthes; bring the object.","support":"~400 words.","llc":"Hold the image up for the cohort and defend your deepest-layer reading under questions."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCC02'
  and is_latest = true and is_archived = false;

-- ── 26UVCC03 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Photograph the SAME real scene near you twice - once framed tight, once framed wide (a vendor, a street, a doorway) - so the two photos tell two different stories.","deliverable_notes":"Both real photos + where and what + 3-4 sentences on how framing alone changed the story and which frame gives the subject more power or dignity."},
      {"sno":2,"unit":"II","finks_dimension":"Caring","task":"Find ONE real advertisement or poster near you that uses a stereotype - about caste, gender, skin colour or region - and photograph it.","deliverable_notes":"Your photo of the real ad + where it is displayed + 3-4 sentences naming the stereotype, who it could hurt, and one honest change that keeps the message but drops the stereotype."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Walk your street and photograph three real examples of Gestalt principles at work - proximity, similarity, closure, figure-ground - in signs, tiles, gates or shop displays.","deliverable_notes":"The three real photos, each labelled with its Gestalt principle in your hand + where found + 3-4 sentences on which principle your eye fell for first and why."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Find ONE real image (film poster, ad, magazine) where a person is being looked at, and ask whether it uses the 'male gaze' - note who is positioned to look and who is looked at.","deliverable_notes":"The image (or a photo of it) + 3-4 sentences on who holds the gaze, how the pose or framing invites it, and how a named woman you ask (initials) actually reads the same image."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Pick ONE real logo or hoarding near you and decode its signs - iconic, indexical, symbolic - together with its colour choice and one design principle, as a single connected reading.","deliverable_notes":"Your photo of the real logo or hoarding + a hand-drawn breakdown labelling icon/index/symbol/colour/principle + 3-4 sentences on how all of them push one message together."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"One Scene, Many Stories","primary":"Photograph ONE real local scene across a day and cut it into a set of frames that each tell a different truth; bring the full set with times.","support":"~400 words on framing and narrative.","llc":"Show the set to the cohort and let them read each frame's story before you reveal your intended one."},
      {"option_no":2,"title":"The Stereotype on Our Walls","primary":"Document five real local ads or posters carrying stereotypes and interview ONE named person from a group they target about how it lands.","support":"~400 words.","llc":"Show the walls to the cohort and quote the real person, defending your proposed fixes."},
      {"option_no":3,"title":"How My Eye Gets Fooled","primary":"Build a photo set of ten real local examples of perception principles (Gestalt, constancy, figure-ground) and test three named viewers on what they see first.","support":"~400 words.","llc":"Run one live perception test on the cohort and explain the theory behind their answers."},
      {"option_no":4,"title":"Who Gets to Look","primary":"Gather five real images that position a viewer's gaze and interview two named people (one man, one woman) on how each reads them.","support":"~400 words on the Gaze and power.","llc":"Present the images and the two real readings side by side to the cohort."},
      {"option_no":5,"title":"The Grammar of One Local Sign","primary":"Choose ONE real hoarding or logo and fully decode its semiotics, colour and design grammar; verify the maker or shop (named).","support":"~400 words.","llc":"Project the sign for the cohort and defend your reading under challenge."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCC03'
  and is_latest = true and is_archived = false;

-- ── 26UVCCP01 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Photograph ONE real subject near you (a well, a cart, a person working) five times using five composition rules - rule of thirds, leading lines, framing, symmetry, and a high angle.","deliverable_notes":"The five real photos labelled by rule in your hand + the subject and place + 3-4 sentences on which composition made the ordinary subject most interesting and why."},
      {"sno":2,"unit":"II","finks_dimension":"Human Dimension","task":"Shoot a 3-5 photo wordless story of ONE real moment in your home or street - a meal being made, a shop opening, water being drawn - so a stranger understands it with no caption.","deliverable_notes":"The photo sequence in order + who and where + 3-4 sentences on what feeling you wanted the viewer to reach and which single frame carries the whole story."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"In manual mode, shoot the SAME real subject three times changing only aperture (or shutter) to prove you control depth of field or motion - for example, freeze then blur a moving cycle.","deliverable_notes":"The three photos with their real settings written under each (f-stop, shutter, ISO) + 3-4 sentences on what changed and one setting that failed and why."},
      {"sno":4,"unit":"IV","finks_dimension":"Learning How to Learn","task":"Get your hands on at least TWO real cameras or lenses you have not used (a friend's DSLR, a phone in pro mode, a borrowed lens) and shoot the same scene with each to learn their differences by doing.","deliverable_notes":"Matched photos from each device + the named gear and whose it is + 3-4 sentences on what each tool did better and one control you taught yourself to find."},
      {"sno":5,"unit":"V","finks_dimension":"Integration","task":"Light ONE real portrait of a named person three ways - window light, a single lamp, and phone torch as fill - to change the mood without moving the person much.","deliverable_notes":"The three lit portraits + the person's name and the light sources + 3-4 sentences naming which is hard or soft light and which mood each lighting created."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Day in One Real Life","primary":"Shoot a photo-essay following ONE named real person through part of their working day (with consent, verifiable) - a weaver, vendor or farmer. Bring 12-15 sequenced photos with times.","support":"~400 words on framing and light.","llc":"Show the essay to the cohort and defend your choices under questions only someone who was there could answer."},
      {"option_no":2,"title":"The Story With No Words","primary":"Shoot a 1-2 minute wordless video of a real local event or task and edit it simply.","support":"~400 words on storytelling and the shots used.","llc":"Screen it for the cohort and explain each shot's job in the story."},
      {"option_no":3,"title":"Light I Controlled","primary":"Make a set of portraits of a named person under at least four real lighting setups (three-point, window, golden hour, single lamp); bring the set with your own light diagrams.","support":"~400 words.","llc":"Show the diagrams to the cohort and defend which lighting best suits the person."},
      {"option_no":4,"title":"One Moment, Every Angle","primary":"Capture ONE real single moment (someone jumping, a lamp being lit, water being poured) from at least six real angles at the same event.","support":"~400 words.","llc":"Lay out the angle set for the cohort and defend which angle told the truth best."},
      {"option_no":5,"title":"My Camera, Learned by Hand","primary":"Keep a dated shooting log proving you moved from auto to full manual on a real camera this term, with paired auto-versus-manual shots of real subjects.","support":"~400 words on what you taught yourself.","llc":"Show one auto/manual pair to the cohort and defend the settings you now choose."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCCP01'
  and is_latest = true and is_archived = false;

-- ── 26UVCDEP01 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Photograph five real examples of the basic design elements (point, line, shape, form, texture, space) in objects around JKKN or your street - a gate grille, a tiled floor, a stack of pots.","deliverable_notes":"The five labelled photos + where found + 3-4 sentences on one place where Gestalt perception (figure-ground or closure) makes you see more than is actually drawn."},
      {"sno":2,"unit":"II","finks_dimension":"Learning How to Learn","task":"Give yourself a real brief - a poster for a real event at home or college - and hand-draw at least eight rough thumbnail ideas in 15 minutes before choosing one, dating the page.","deliverable_notes":"The dated thumbnail sheet (all eight, messy is fine) + the real brief + 3-4 sentences on how ideas 6-8 differed from 1-3 and what your research (what you looked at) changed."},
      {"sno":3,"unit":"III","finks_dimension":"Application","task":"Hand-letter ONE word in three different type styles (a serif, a sans-serif, a display face) on paper, then mark the anatomy - stem, bowl, serif, x-height - on each.","deliverable_notes":"The hand-lettered sheet with anatomy labelled + 3-4 sentences on which letters were hardest to keep even and how you fixed the spacing (kerning) between two tight letters."},
      {"sno":4,"unit":"IV","finks_dimension":"Integration","task":"Take ONE real cluttered printed page (a local newspaper ad, a pamphlet) and redraw its layout by hand onto a grid you draw yourself, fixing its margins, columns and alignment.","deliverable_notes":"The original (or a photo) beside your hand-drawn grid redesign + where it came from + 3-4 sentences on what the grid fixed and which element you gave the most emphasis."},
      {"sno":5,"unit":"V","finks_dimension":"Human Dimension","task":"Pick ONE real emotion (grief, festival joy, calm) and build a small colour palette for it by pulling colours from a real local source you photograph - a funeral, a temple festival, the river at dawn.","deliverable_notes":"Your source photo + the hand-painted or swatched palette + 3-4 sentences on why those colours carry that feeling here, and whether the same colours would mean the same in another culture."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"Eight Roughs to One Poster","primary":"Design a real poster for a real, named, dated event, keeping every hand thumbnail and draft from brief to final.","support":"~400 words on the process.","llc":"Fan out the full paper trail for the cohort and faculty and defend the idea you chose to kill."},
      {"option_no":2,"title":"An Alphabet of My Own","primary":"Hand-design a full display alphabet (A-Z) inspired by a real local lettering source you photograph - a temple board, lorry art, a sign painter's work. Bring the hand-drawn set.","support":"~400 words.","llc":"Show your alphabet beside its real source to the cohort and defend your letterforms."},
      {"option_no":3,"title":"The Sign-Painter's Secret","primary":"Interview ONE named real Tamil sign or banner painter (phone-verifiable) about how they space letters and choose colours by eye; record with consent; then try their method by hand.","support":"~400 words.","llc":"Play their words for the cohort and show your own attempt at their craft."},
      {"option_no":4,"title":"Redeemed by a Grid","primary":"Take a real badly-designed local printed piece and rebuild it on a proper grid; bring both the original and your redesign.","support":"~400 words.","llc":"Show before and after to the cohort and defend every alignment choice under questions."},
      {"option_no":5,"title":"Colour That Feels Like Home","primary":"Build three emotion-palettes, each sourced from a real local photograph, and prove each one in a small design.","support":"~400 words on colour association.","llc":"Show the palettes and their real photo sources to the cohort and defend the feelings live."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCDEP01'
  and is_latest = true and is_archived = false;

-- ── 26UVCDEP02 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Collect THREE real printed publications from home or a shop - a magazine, a newspaper, a wedding invitation or brochure - and identify each one's type, page size (measure in mm) and how its pages are held together.","deliverable_notes":"Photos of the three real items with a ruler + 3-4 sentences naming each publication type and the standard size you measured, plus which was clearly made with a proper design tool and which was not."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Design ONE flyer for a REAL small local business or event (named, with the owner's okay) that has a clear call to action, and prepare it at the correct print size.","deliverable_notes":"The exported flyer at real size + the business name and contact + 3-4 sentences on the one action you want a reader to take and how the layout leads their eye to it."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Design a two-page magazine spread on a REAL local topic (a Bhavani weaver, a JKKN event, a village festival) using your own photos and a grid, pairing two fonts.","deliverable_notes":"The spread + your own source photos + 3-4 sentences naming the two fonts and why they pair, and how the grid holds the images and text together."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Design a book cover or poster for a REAL person you know as the reader (named) - pick colours and an illustration style that suit THAT person's taste, which you confirm by asking them.","deliverable_notes":"The cover or poster + the named reader's stated taste in their own words + 3-4 sentences on how your colour and illustration choices answer what they told you."},
      {"sno":5,"unit":"V","finks_dimension":"Caring","task":"For one of your own designs, replace every borrowed image with a photo YOU took, and write down the copyright or usage status of anything you did not shoot yourself.","deliverable_notes":"A before/after showing borrowed versus your-own images + a short rights table (image, source, licence) + 3-4 sentences on why using your own or properly-licensed images matters to a real client."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Magazine About My Place","primary":"Design a 4-6 page mini-magazine on a real local subject using only your own photos and interviews (named, verifiable sources). Bring it printed or as a full spread set.","support":"~400 words.","llc":"Present the magazine to the cohort and defend your layout and image-rights choices."},
      {"option_no":2,"title":"The Flyer That Got Used","primary":"Design a flyer or poster for a REAL local business or event and actually have it displayed or shared; bring proof it was used (a photo of it up, the owner's word).","support":"~400 words.","llc":"Show where it ran to the cohort and report any real response it drew."},
      {"option_no":3,"title":"Designed for One Named Reader","primary":"Interview ONE named reader about their taste, then design a publication cover made only for them; confirm their reaction afterwards.","support":"~400 words.","llc":"Play or read their taste and reaction to the cohort and defend your choices."},
      {"option_no":4,"title":"From My Camera, Not the Internet","primary":"Rebuild a full design using only self-shot photography, documenting the rights status of everything; bring the shoot and the design.","support":"~400 words on image ethics.","llc":"Show your source shoot to the cohort and defend why nothing was borrowed."},
      {"option_no":5,"title":"Ink on Real Paper","primary":"Get ONE of your designs actually printed at a real local press and interview the press owner (named) about paper, colour accuracy and one print problem; bring the printed piece.","support":"~400 words.","llc":"Pass the print around the cohort and quote the press owner on what changed from screen to paper."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCDEP02'
  and is_latest = true and is_archived = false;

-- ── 26UVCFP01 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities anchored to the lab experiments, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Foundational Knowledge","task":"Hand-draw ONE real everyday object from your home (a pot, a slipper, a cup) using only basic shapes and light/dark shading to show volume, then rebuild the same object digitally in layers.","deliverable_notes":"The hand-drawn sketch beside your digital version + a photo of the real object + 3-4 sentences on where tones created volume and what layers let you do that paper could not."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Stand at ONE real spot - a road, a corridor, a row of shops near JKKN - and draw it in one- or two-point perspective by hand, marking the horizon line and vanishing point(s).","deliverable_notes":"Your perspective drawing with horizon and vanishing points marked + a photo of the real spot from the same position + 3-4 sentences on where your lines went wrong and how the real scene corrected you."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Take ONE photo of a real local surface or building, then use it as an image plane or texture in a digital scene, blending it so it sits believably in the new picture.","deliverable_notes":"Your original photo + the composited result + 3-4 sentences on what gave the blend away at first and how you matched light or perspective to fix it."},
      {"sno":4,"unit":"IV","finks_dimension":"Human Dimension","task":"Make a digital charcoal-style portrait of ONE named real person you can see (family, friend), working from your own photo of them, not a stock or downloaded face.","deliverable_notes":"Your reference photo + the digital charcoal portrait + the person's name + 3-4 sentences on which feature carried their likeness and one mark that made it feel like charcoal, not a filter."},
      {"sno":5,"unit":"V","finks_dimension":"Learning How to Learn","task":"Draw ONE real local scene yourself (by hand or digitally), then ask an AI image tool to make the 'same' scene, and mark on the AI version everything it got wrong about YOUR real place.","deliverable_notes":"Your own drawing + the AI image + your marked list of the AI's real-world mistakes + 3-4 sentences on what you know about the place that the AI could not, and where AI could still genuinely help you."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"Drawn From My Own Window","primary":"Produce a finished digital painting of a real, nameable local view you can physically stand in, backed by your own reference photos and hand thumbnails made at that spot.","support":"~400 words.","llc":"Show the spot's photos to the cohort and defend choices only someone who stood there could make."},
      {"option_no":2,"title":"Perspective, Proven on the Ground","primary":"Pick a real local location and build a perspective-correct digital painting of it, bringing your on-site line drawing with marked vanishing points.","support":"~400 words.","llc":"Overlay your perspective grid on the real photo for the cohort and defend it live."},
      {"option_no":3,"title":"A Face I Know","primary":"Make a digital portrait of ONE named real person from your own sittings or photos (verifiable) and get their spoken reaction to the likeness.","support":"~400 words.","llc":"Show the portrait to the cohort and play or read the sitter's reaction, defending your likeness choices."},
      {"option_no":4,"title":"Me vs. the Machine","primary":"Hand-make and AI-generate the same real local scene, then produce a marked comparison of every real detail the AI missed or invented.","support":"~400 words on where human lived-knowledge beats AI.","llc":"Show both to the cohort and defend your scene's truth under questions."},
      {"option_no":5,"title":"The Tool I Chose to Keep","primary":"Try at least three real digital or AI tools on one project, keeping dated evidence of each attempt, then decide by hand which parts stay human.","support":"~400 words on your workflow judgement.","llc":"Walk the cohort through your tool decisions and defend what you refused to hand to AI."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCFP01'
  and is_latest = true and is_archived = false;

-- ── 26UVCNMP01 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Take one real story from your own life or family and map it onto a named story structure (three-act, Freytag's pyramid, or Hero's Journey) by hand.","deliverable_notes":"Your real story in one line + your hand structure-map + 1 line on where the turning point fell."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"Write one real short script page (a scene you invent about a real place you know) in correct script format.","deliverable_notes":"Your correctly formatted script page + the real place it's set in + 1 line on one formatting rule you had to fix."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Develop one of your script ideas one stage further using a named development strategy; show the before and after.","deliverable_notes":"Your idea before and after development + the strategy named + 1 line on what got stronger."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Write a short script in ONE specific format you haven't tried (PSA, news, radio, or documentary) about a real local issue.","deliverable_notes":"Your script in the chosen format + the real issue it addresses + 1 line on what the format demanded."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Create a simple real photovoice/slideshow story (your own photos of a named place or subject, with a short narrative), analysing your own story with one analysis approach.","deliverable_notes":"Your photo-story (3–5 of your own photos + narration) + your one-paragraph self-analysis using a named approach."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Story Only I Could Tell","primary":"Create an original digital story rooted in a REAL place, person, or event you know (your own photos/footage/voice), fully scripted and structured to a named framework, and produced as a short photo-story or video. AI tools may assist editing but the story, images, and voice must be genuinely yours.","support":"~400 words on the choices that made it personal and true.","llc":"Screen your story and answer questions on your structural and creative decisions."},
      {"option_no":2,"title":"A Script for a Real Local Issue","primary":"Write a complete short script (PSA, documentary, or radio) about a genuine issue in your locality, grounded in real observation or a consented interview, in correct professional format.","support":"~400 words on how the format shaped the message.","llc":"Perform or read a scene and defend a format choice."},
      {"option_no":3,"title":"One Story, Three Structures","primary":"Take a single real story and re-tell it three ways using three different named structures (three-act, Freytag, Hero's Journey), showing how structure changes impact.","support":"~400 words on which structure served your story best.","llc":"Present the three versions and justify your favourite live."},
      {"option_no":4,"title":"The Photovoice of a Place","primary":"Build a photovoice project about a named place or community using only your own photographs and narration, and analyse the story you told with a named analytical approach.","support":"~400 words on what images say that words can't.","llc":"Present the photovoice and answer 'why this frame?'"},
      {"option_no":5,"title":"From Idea to Finished Script","primary":"Take one raw idea and carry it through the full real development pipeline (concept → structure → draft → revision) documented at each stage, ending in a polished script for a real subject.","support":"~400 words on the revision that mattered most.","llc":"Walk through your drafts and defend a cut you made."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCNMP01'
  and is_latest = true and is_archived = false;

-- ── 26UVCSP01 · b-sc-visual-communication ──
update public.bos_course_syllabi
set
  concept_applications = $j${
    "intro_note": "Five short Fink's-shaped activities, one per Unit, conducted as formative learning during the semester. Not separately graded as line items; faculty may credit toward the Activities row (5 marks) at the BoS Chairman's discretion. They build the practice that culminates in the Capstone. The deliverable for each is the evidence — a photo, a reading, a hand-drawn sketch, a data table, a quoted voice, running code — plus three or four sentences, not an essay. Every task requires a named local place, a named person, a real measurement, or a hand-made artefact that an AI cannot fabricate.",
    "activities": [
      {"sno":1,"unit":"I","finks_dimension":"Application","task":"Take one real photograph YOU shoot, and do a basic edit (crop, straighten, exposure) on it; keep the original and the edit.","deliverable_notes":"Your original and edited image side by side + the file format you used + 1 line on what the edit fixed."},
      {"sno":2,"unit":"II","finks_dimension":"Application","task":"On your own photo, perform a colour correction (fix a colour cast or white balance) and one selective/split-tone adjustment; document your steps.","deliverable_notes":"Before/after images + your step list + 1 line on the colour problem you solved."},
      {"sno":3,"unit":"III","finks_dimension":"Integration","task":"Build a small composite from your own images using layers and at least two blend modes; explain what each layer contributes.","deliverable_notes":"Your composite + a labelled layer breakdown + 1 line on the blend mode that did the key work."},
      {"sno":4,"unit":"IV","finks_dimension":"Application","task":"Apply a colour-grading style to one of your own photos and justify the mood it creates; compare graded vs ungraded.","deliverable_notes":"Graded and ungraded versions + your one-line intent + 1 line on the tool you used to achieve it."},
      {"sno":5,"unit":"V","finks_dimension":"Application","task":"Set up a real batch/workflow to process several of your own images consistently, AND compile your Practical Exercises Record — a labelled contact sheet of every technique you practised (crop, exposure, colour correction, sharpening, B&W, raw, advanced colour).","deliverable_notes":"Your batch-processed set + the Practical Exercises Record contact sheet (all techniques, labelled) + 1 line on what batching saved you."}
    ]
  }$j$::jsonb,
  capstone_project = $j${
    "intro_note": "Choose ONE of FIVE — Solo · 10 marks (Internal) · spans the semester · presented at the end-of-course Learners Led Conference. The Senior Learner introduces all five Capstones to the cohort in week 1. The assessment focuses on what AI cannot do. Each Capstone has three parts: (1) the AI-proof primary deliverable — a real measured object, a hand-drawn graph, a named-source interview with a phone-verifiable contact, running code, a real dataset, or a thing you built, as the option specifies; (2) a short ~400-word reflection — deliberately brief, enough to show your thinking, too short to be worth generating; and (3) a 5–7 minute presentation at the end-of-course Learners Led Conference (LLC) where you show the real thing and answer unscripted questions. A long polished essay is exactly what a language model produces best, so it is not the deliverable. No outside-community Public Exhibition — the LLC audience is the cohort and faculty.",
    "options": [
      {"option_no":1,"title":"A Photo Series I Shot and Finished","primary":"Shoot an original photo series (a named subject/place — your locality, a person with consent, an event) and take it through a complete, documented edit-and-colour-management workflow, delivering a coherent finished set plus your Practical Exercises Record proving each technique is yours.","support":"~400 words on the editing decisions that shaped the mood.","llc":"Present the series and reproduce one edit live when asked."},
      {"option_no":2,"title":"The Colour Cast I Conquered","primary":"Take a set of your own genuinely flawed photos (bad white balance, colour casts) and correct each with documented, repeatable steps, then codify your method into a colour-correction guide.","support":"~400 words on the science of colour management behind your fixes.","llc":"Correct a fresh image live."},
      {"option_no":3,"title":"A Composite That Tells the Truth","primary":"Build a layered composite entirely from your own images that communicates one clear idea, using blend modes and masking, and document every layer's role — while being explicit about where editing serves storytelling vs deception.","support":"~400 words on the ethics and craft of compositing.","llc":"Reveal your layer stack and defend one choice."},
      {"option_no":4,"title":"One Photo, Five Grades","primary":"Take a single strong photo of yours and produce five distinct colour grades, each for a named intended use/mood, documenting the tools and reasoning for each.","support":"~400 words on how grade changes meaning.","llc":"Present the grades and match a mood to a grade on request."},
      {"option_no":5,"title":"A Workflow That Scales","primary":"Design and demonstrate a real, efficient editing workflow (import → correct → batch → export with colour management) on a genuine set of your own images, and prove its consistency across the set via your Practical Exercises Record.","support":"~400 words on where manual work must stay and where automation helps.","llc":"Run one workflow step live and answer how you'd adapt it for 500 images."}
    ]
  }$j$::jsonb,
  last_modified_at = now()
where course_code = '26UVCSP01'
  and is_latest = true and is_archived = false;

